package com.potionprofitpro;

import com.potionprofitpro.data.CompostType;
import com.potionprofitpro.data.PlotTextSize;
import com.potionprofitpro.data.PlotView;
import com.potionprofitpro.data.ProfitPotion;
import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Notification;

@ConfigGroup(PotionProfitProConfig.GROUP)
public interface PotionProfitProConfig extends Config
{
	String GROUP = "potionprofitpro";

	@ConfigSection(
		name = "Farming Mode",
		description = "Farming overlays turn on when the required tools are in the inventory.",
		position = 0
	)
	String farmingSection = "farmingSection";

	@ConfigSection(
		name = "Farming gear",
		description = "Optional farming enhancements to watch.",
		position = 1
	)
	String farmingGearSection = "farmingGearSection";

	@ConfigItem(
		keyName = "profitPotion",
		name = "Tracked potion",
		description = "Herb plots follow this potion. Prayer potion uses Ranarr. Super restore and Sanfew serum use Snapdragon. Saradomin brew uses Toadflax.",
		position = -1
	)
	default ProfitPotion profitPotion()
	{
		return ProfitPotion.PRAYER_POTION;
	}

	@ConfigItem(
		keyName = "plotView",
		name = "Plot View",
		description = "Compacted nests allotment status under each herb location. Separated shows herb and allotment plots as two lists.",
		hidden = true
	)
	default PlotView plotView()
	{
		return PlotView.COMPACTED;
	}

	@ConfigItem(
		keyName = "plotTextSize",
		name = "Herb Text Size",
		description = "Herb plot name and status size. Large is easier to read. Small matches the earlier compact rows.",
		hidden = true
	)
	default PlotTextSize plotTextSize()
	{
		return PlotTextSize.LARGE;
	}

	@ConfigItem(
		keyName = "showAllotmentPlots",
		name = "Show Allotment Plots",
		description = "In Compacted view, show allotment status under each matching herb location in the plugin panel.",
		hidden = true
	)
	default boolean showAllotmentPlots()
	{
		return false;
	}

	@ConfigSection(
		name = "Mixing Mode",
		description = "Alerts while mixing the tracked potion.",
		position = 2
	)
	String mixingSection = "mixingSection";

	@ConfigSection(
		name = "Overlay colors",
		description = "Colors for patch and inventory highlights.",
		position = 3
	)
	String colorSection = "colorSection";

	@ConfigSection(
		name = "Overrides",
		description = "Show locked herb and allotment plots before their quest, diary, or Farming level unlocks.",
		position = 4
	)
	String overrideSection = "overrideSection";

	@ConfigItem(
		keyName = "farmingOverlaysEnabled",
		name = "Enable farming overlays",
		description = "Turn Farming Mode overlays on when the required tools are in the inventory. Spade and secateurs are always required. A rake is required unless Tithe Farm Auto-weed is unlocked. A seed dibber is required until Barbarian Training fists-planting is complete.",
		section = farmingSection,
		position = 0
	)
	default boolean farmingOverlaysEnabled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightTeleports",
		name = "Highlight Teleports",
		description = "Highlight each herb-run teleport that still leads to a Ready herb plot, only while Farming Mode overlays are enabled and the required farming tools are in the inventory. Shared teleports stay highlighted until the last Ready plot that uses them is picked.",
		section = farmingSection,
		position = 1
	)
	default boolean highlightTeleports()
	{
		return false;
	}

	@ConfigItem(
		keyName = "useAmuletOfBounty",
		name = "Use Amulet of Bounty",
		description = "Highlight allotment patches based on whether the amulet is equipped.",
		section = farmingGearSection,
		position = 0
	)
	default boolean useAmuletOfBounty()
	{
		return false;
	}

	@ConfigItem(
		keyName = "useBottomlessBucket",
		name = "Use bottomless compost bucket",
		description = "Show remaining compost uses in a bottomless bucket. Planted herb and allotment patches without compost use the Unfertilized overlay color.",
		section = farmingGearSection,
		position = 1
	)
	default boolean useBottomlessBucket()
	{
		return false;
	}

	@ConfigItem(
		keyName = "useCompostBuckets",
		name = "Use compost buckets",
		description = "Show how many buckets of your selected compost type are in the inventory. Planted herb and allotment patches without compost use the Unfertilized overlay color.",
		section = farmingGearSection,
		position = 2
	)
	default boolean useCompostBuckets()
	{
		return false;
	}

	@ConfigItem(
		keyName = "compostType",
		name = "Fertilizer",
		description = "Ultracompost is watermelons plus volcanic ash, or bought ultra buckets. Supercompost is watermelons only, or bought super buckets. Bottomless fills still count double.",
		section = farmingGearSection,
		position = 3
	)
	default CompostType compostType()
	{
		return CompostType.ULTRACOMPOST;
	}

	@ConfigItem(
		keyName = "useAlchemistsAmulet",
		name = "Use Alchemist's Amulet",
		description = "Show a mixing warning if the Alchemist's Amulet is missing. Charges still display whenever it is equipped.",
		section = mixingSection,
		position = 0
	)
	default boolean useAlchemistsAmulet()
	{
		return false;
	}

	@ConfigItem(
		keyName = "usePrescriptionGoggles",
		name = "Use Prescription Goggles",
		description = "Watch for Prescription Goggles while mixing the tracked potion.",
		section = mixingSection,
		position = 1
	)
	default boolean usePrescriptionGoggles()
	{
		return false;
	}

	@ConfigItem(
		keyName = "mixingAlert",
		name = "Mixing alerts",
		description = "Notify if you mix the tracked potion without Prescription Goggles or a charged Alchemist's Amulet. Use RuneLite's notification sound picker for Off, Native, or a custom wav.",
		section = mixingSection,
		position = 2
	)
	default Notification mixingAlert()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "repeatMixingAlert",
		name = "Repeat mixing alerts",
		description = "Send the Mixing alerts notification again after every mix while required goggles or a charged Alchemist's Amulet are missing.",
		section = mixingSection,
		position = 3
	)
	default boolean repeatMixingAlert()
	{
		return false;
	}

	@ConfigItem(
		keyName = "goodColor",
		name = "Good",
		description = "Color when farming or mixing gear is in the expected state.",
		section = colorSection,
		position = 0
	)
	default Color goodColor()
	{
		return new Color(0, 200, 83);
	}

	@ConfigItem(
		keyName = "badColor",
		name = "Bad",
		description = "Color when something required is missing.",
		section = colorSection,
		position = 1
	)
	default Color badColor()
	{
		return new Color(220, 40, 40);
	}

	@ConfigItem(
		keyName = "warningColor",
		name = "Warning",
		description = "Color when the Amulet of Bounty has one charge left.",
		section = colorSection,
		position = 2
	)
	default Color warningColor()
	{
		return new Color(255, 140, 0);
	}

	@ConfigItem(
		keyName = "unfertilizedColor",
		name = "Unfertilized",
		description = "Color when a planted herb or allotment has not been treated with compost.",
		section = colorSection,
		position = 3
	)
	default Color unfertilizedColor()
	{
		return new Color(255, 220, 0);
	}

	@ConfigItem(
		keyName = "readyToHarvestColor",
		name = "Ready to Harvest",
		description = "Color when a herb or allotment patch can be picked or harvested.",
		section = colorSection,
		position = 4
	)
	default Color readyToHarvestColor()
	{
		return new Color(0, 210, 230);
	}

	@ConfigItem(
		keyName = "showHarmonyPatches",
		name = "Show Harmony Patches",
		description = "Always show Harmony herb and allotment plots. They also appear after Morytania Elite Diary.",
		section = overrideSection,
		position = 0
	)
	default boolean showHarmonyPatches()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showFarmingGuildHerb",
		name = "Show Farming Guild herb",
		description = "Always show the Farming Guild herb plot. It also appears at 65 Farming.",
		section = overrideSection,
		position = 1
	)
	default boolean showFarmingGuildHerb()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showFarmingGuildAllotments",
		name = "Show Farming Guild allotments",
		description = "Always show the Farming Guild allotment plots. They also appear at 45 Farming.",
		section = overrideSection,
		position = 2
	)
	default boolean showFarmingGuildAllotments()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showWeissPatch",
		name = "Show Weiss patch",
		description = "Always show the Weiss herb plot. It also appears after Making Friends with My Arm.",
		section = overrideSection,
		position = 3
	)
	default boolean showWeissPatch()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showTrollStrongholdPatch",
		name = "Show Troll Stronghold patch",
		description = "Always show the Troll Stronghold herb plot. It also appears after My Arm's Big Adventure.",
		section = overrideSection,
		position = 4
	)
	default boolean showTrollStrongholdPatch()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPrifPatches",
		name = "Show Prif patches",
		description = "Always show Prifddinas allotment plots. They also appear after Song of the Elves.",
		section = overrideSection,
		position = 5
	)
	default boolean showPrifPatches()
	{
		return false;
	}
}

