@Slf4j
@PluginDescriptor(
	name = "Potion Profit Pro",
	configName = "potionprofitpro",
	internalName = "potion-profit-pro",
	legacyDataDirectory = "potion-profit-pro",
	description = "Track Prayer potion, Super restore, Sanfew serum, and Saradomin brew farming spend versus Grand Exchange sales, with farming and mixing overlays",
	tags = {"farming", "herblore", "prayer", "restore", "sanfew", "brew", "toadflax", "profit"}
)
public class PotionProfitProPlugin extends Plugin
{
	private static final Pattern PLANT_RANARR = Pattern.compile("(?i)you plant (?:a |an |\\d+ )?ranarr seeds?");
	private static final Pattern PLANT_TOADFLAX = Pattern.compile("(?i)you plant (?:a |an |\\d+ )?toadflax seeds?");
	private static final Pattern PLANT_SNAPDRAGON = Pattern.compile("(?i)you plant (?:a |an |\\d+ )?snapdragon seeds?");
	private static final Pattern PLANT_ALLOTMENT = Pattern.compile(
		"(?i)you plant (?:a |an |\\d+ )?(potato|onion|cabbage|tomato|sweetcorn|strawberry|watermelon|snape grass) seeds?");
	private static final Pattern PICK_HERBS = Pattern.compile("(?i)you pick some herbs");
	private static final Pattern HARVEST_SNAPE = Pattern.compile("(?i)you harvest (?:the |some |\\d+ )?snape grass");
	private static final Pattern CRUSH_NEST = Pattern.compile("(?i)you (?:crush|grind) the (?:bird'?s )?nest");
	private static final int HARVEST_GRACE_TICKS = 10;
	private static final int HARVEST_PLOT_DISTANCE = 6;
	private static final int GE_LOGIN_TICKS = 5;
	private static final Pattern TREAT_COMPOST = Pattern.compile(
		"(?i)you treat the .+ with (ultracompost|supercompost|compost)");
	private static final Pattern FILL_COMPOST_BUCKET = Pattern.compile(
		"(?i)you fill the bucket with (ultra|super)?compost");
	private static final Pattern BIN_EMPTY = Pattern.compile("(?i)the compost bin is now empty");
	private static final Pattern BIN_ULTRA = Pattern.compile("(?i)transforms into ultracompost");
	private static final Pattern MINE_ASH = Pattern.compile("(?i)you (?:manage to )?mine some volcanic ash");
	private static final Pattern ALCH_PROC = Pattern.compile(
		"(?i)(?:alchemist['’]?s amulet|amulet of chemistry) helps you create a 4-dose potion");
	private static final Pattern MIX_POTION = Pattern.compile("(?i)you mix the .+ into your potion");
	private static final Set<String> INTERNAL_CONFIG_KEYS = Set.of(
		"profitSync",
		"prayerLedger",
		"supplySnapshot",
		"herbPatchState",
		"allotmentPatchState",
		"patchFertility",
		"achievementCompletions",
		"bountyCharges",
		"bottomlessUses",
		"alchemistCharges",
		"guildSpiritTreeReady",
		"portalNexusDests",
		"houseLocation",
		"achievementsCollapsed",
		"statisticsCollapsed",
		"herbPlotsCollapsed",
		"allotmentPlotsCollapsed",
		"viewSettingsCollapsed"
	);

	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private PotionProfitProConfig config;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private InfoBoxManager infoBoxManager;
	@Inject
	private ItemManager itemManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private Notifier notifier;
	@Inject
	private FarmingModeTracker farmingMode;
	@Inject
	private MixingModeTracker mixingMode;
	@Inject
	private AchievementTracker achievementTracker;
	@Inject
	private ChargeTracker charges;
	@Inject
	private ProfitStore profitStore;
	@Inject
	private PatchHighlightOverlay patchOverlay;
	@Inject
	private MixingItemOverlay mixingOverlay;
	@Inject
	private TeleportHighlightOverlay teleportOverlay;
	@Inject
	private PatchFertilityTracker fertility;
	@Inject
	private CompostTracker compostTracker;
	@Inject
	private HerbPatchTracker herbPatchTracker;
	@Inject
	private AllotmentPatchTracker allotmentPatchTracker;
	@Inject
	private HerbTeleportTracker herbTeleportTracker;
	@Inject
	private StockTracker stockTracker;
	@Inject
	private ScheduledExecutorService executor;

	private PotionProfitProPanel panel;
	private ScheduledFuture<?> growthTask;
	private NavigationButton navButton;
	private boolean lastCompostWasBottomless;
	private boolean mixingAlerted;
	private int lastRanarrCount;
	private int lastSnapdragonCount;
	private int lastToadflaxCount;
	private int lastSnapeCount;
	private boolean harvestCountsReady;
	private int harvestGraceTicks;
	private int lastWatermelonCount;
	private int lastAshCount;
	private boolean pendingAshMine;
	private boolean pendingBountySeedSave;
	private final JewelleryTracker jewelleryTracker = new JewelleryTracker();
	private boolean pendingCrushNest;
	private int lastEmptyNestCount;
	private int lastCrushedNestCount;
	private boolean pendingWatermelonOnBin;
	private boolean pendingAshOnBin;
	private static final int OTHER_TRADEOFFER = InventoryID.TRADEOFFER | 0x8000;

	private boolean pendingTrade;
	private int tradeWaitTicks;
	private int tradeGivePots4;
	private int tradeGivePotsAny;
	private int tradeGiveCoins;
	private int tradeReceivePots4;
	private int tradeReceivePotsAny;
	private int tradeReceiveCoins;
	private boolean pendingPotionDrink;
	private int drinkWaitTicks;
	private final int[] geSoldQty = new int[8];
	private final long[] geSpent = new long[8];
	private final int[] geBoughtQty = new int[8];
	private final long[] geBoughtGp = new long[8];
	private final int[] geItemId = new int[8];
	private final boolean[] gePrimed = new boolean[8];
	private int geIgnoreTicks;
	private boolean pendingBankScan;
	private boolean pendingVaultScan;
	private String lastDialogueText;
	private final Map<String, GearInfoBox> infoBoxes = new HashMap<>();
	private int lastRegionId = -1;
	private int rebuildTicks;
	private int emptyScanCooldown;
	private boolean achievementsDirty;

	@Provides
	PotionProfitProConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PotionProfitProConfig.class);
	}

	@Override
	protected void startUp()
	{
		charges.load();
		profitStore.load();
		profitStore.copyGeSlots(geSoldQty, geSpent, geBoughtQty, geBoughtGp, geItemId);
		fertility.load();
		herbPatchTracker.load();
		allotmentPatchTracker.load();
		herbTeleportTracker.load();
		stockTracker.load();
		achievementTracker.load();
		overlayManager.add(patchOverlay);
		overlayManager.add(mixingOverlay);
		overlayManager.add(teleportOverlay);

		panel = injector.getInstance(PotionProfitProPanel.class);
		refreshAchievements();
		setNavButton(fallbackNavIcon());
		clientThread.invoke(this::loadNavIcon);

		clientThread.invoke(() ->
		{
			refreshHerbPatches();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				lastRegionId = -1;
				rebuildTicks = 25;
				rebuildPatches();
				harvestCountsReady = true;
				snapshotHarvestCounts();
				applyStock(InventoryID.INV);
				beginGrandExchangeSync();
				achievementTracker.tick();
				farmingMode.tick();
				mixingMode.tick();
				herbPatchTracker.tick(client);
				allotmentPatchTracker.tick(client);
				herbTeleportTracker.tick();
				refreshAchievements();
				refreshHerbPatches();
				closeFinishedHarvestRuns();
			}
			refreshOverlays();
		});
		growthTask = executor.scheduleAtFixedRate(() -> clientThread.invoke(this::advancePlotPredictions), 1, 1, TimeUnit.SECONDS);

		log.debug("Potion Profit Pro started!");
	}

	@Override
	protected void shutDown()
	{
		if (growthTask != null)
		{
			growthTask.cancel(false);
			growthTask = null;
		}
		profitStore.persist();
		stockTracker.flush();
		overlayManager.remove(patchOverlay);
		overlayManager.remove(mixingOverlay);
		overlayManager.remove(teleportOverlay);
		clearInfoBoxes();
		patchOverlay.clear();
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		mixingAlerted = false;
		log.debug("Potion Profit Pro stopped!");
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!PotionProfitProConfig.GROUP.equals(event.getGroup())
