	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			achievementTracker.resetLive();
			herbTeleportTracker.resetLive();
			patchOverlay.clear();
			lastRegionId = -1;
			rebuildTicks = 0;
			harvestCountsReady = false;
			harvestGraceTicks = 0;
			pendingTrade = false;
			tradeWaitTicks = 0;
			pendingPotionDrink = false;
			drinkWaitTicks = 0;
			pendingBankScan = false;
			pendingVaultScan = false;
			resetGrandExchangeSlots();
			mixingMode.reset();
			stockTracker.clearPotionSaleSkip();
			stockTracker.resetSession();
		}
		else if (state == GameState.LOADING)
		{
			patchOverlay.clear();
			rebuildTicks = 25;
			herbPatchTracker.freeze(8);
			allotmentPatchTracker.freeze(8);
		}
		else if (state == GameState.LOGGED_IN)
		{
			rebuildTicks = 25;
			rebuildPatches();
			if (!harvestCountsReady)
			{
				harvestCountsReady = true;
				snapshotHarvestCounts();
			}
			applyStock(InventoryID.INV);
			beginGrandExchangeSync();
			achievementTracker.tick();
			farmingMode.tick();
			mixingMode.tick();
			herbPatchTracker.tick(client);
			allotmentPatchTracker.tick(client);
			herbTeleportTracker.tick();
			refreshOverlays();
			refreshAchievements();
			refreshHerbPatches();
			closeFinishedHarvestRuns();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (geIgnoreTicks > 0)
		{
			geIgnoreTicks--;
			finishGrandExchangeSync();
			if (geIgnoreTicks == 0)
			{
				persistGrandExchangeSlots();
			}
		}

		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}

		achievementTracker.tick();
		farmingMode.tick();
		mixingMode.tick();

		WorldPoint location = player.getWorldLocation();
		if (location != null && location.getRegionID() != lastRegionId)
		{
			lastRegionId = location.getRegionID();
			if (farmingScene())
			{
				rebuildTicks = Math.max(rebuildTicks, 3);
			}
			else
			{
				rebuildTicks = 0;
				patchOverlay.clear();
			}
		}

		if (farmingScene())
		{
			if (rebuildTicks > 0)
			{
				rebuildPatches();
				rebuildTicks--;
			}
			else if (patchOverlay.isEmpty())
			{
				if (emptyScanCooldown <= 0)
				{
					rebuildPatches();
					emptyScanCooldown = 5;
				}
				else
				{
					emptyScanCooldown--;
				}
			}
		}
		else
		{
			rebuildTicks = 0;
			if (!patchOverlay.isEmpty())
			{
				patchOverlay.clear();
			}
		}

		if (pendingBankScan && isBankOpen())
		{
			pendingBankScan = false;
			applyStock(InventoryID.BANK);
		}
		if (pendingVaultScan && isSeedVaultOpen())
		{
			pendingVaultScan = false;
			applyStock(InventoryID.INV);
			applyStock(InventoryID.SEED_VAULT);
		}
		readBottomlessDialogue();
		snapshotTradeConfirm();
		expireCancelledTrade();
		refreshHarvestGrace();
		if (pendingPotionDrink)
		{
			recordPotionDrink();
			if (pendingPotionDrink)
			{
				if (drinkWaitTicks <= 0)
				{
					pendingPotionDrink = false;
				}
				else
				{
					drinkWaitTicks--;
				}
			}
		}
		refreshOverlays();
		herbPatchTracker.tick(client);
		allotmentPatchTracker.tick(client);
		if (farmingScene())
		{
			patchOverlay.syncVisibleAllotments(allotmentPatchTracker);
		}
		observeHarvestableHerbs();
		observeHarvestableAllotments();
		herbTeleportTracker.tick();
		refreshHerbPatches();
		closeFinishedHarvestRuns();
		profitStore.flushIfDue();
		stockTracker.flushIfDue();
		if (rebuildTicks > 0 || achievementsDirty || client.getTickCount() % 50 == 0)
		{
			achievementsDirty = false;
			refreshAchievements();
		}
	}

