	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		int groupId = event.getGroupId();
		if (groupId == InterfaceID.BANKMAIN)
		{
			pendingBankScan = true;
			return;
		}
		if (groupId == InterfaceID.SEED_VAULT)
		{
			pendingVaultScan = true;
			return;
		}
		if (groupId == InterfaceID.TRADECONFIRM)
		{
			snapshotTradeConfirm();
			return;
		}
		if (groupId == InterfaceID.QUESTJOURNAL)
		{
			clientThread.invokeLater(() ->
			{
				achievementTracker.scanQuestJournal();
				achievementsDirty = true;
				farmingMode.refreshActive();
				return true;
			});
			return;
		}
		if (groupId != InterfaceID.OBJECTBOX && groupId != InterfaceID.CHAT_RIGHT && groupId != InterfaceID.CHAT_LEFT)
		{
			return;
		}

		clientThread.invokeLater(() ->
		{
			if (readBottomlessDialogue())
			{
				refreshOverlays();
				return true;
			}
			return client.getWidget(InterfaceID.Objectbox.TEXT) == null
				&& client.getWidget(InterfaceID.ChatRight.TEXT) == null
				&& client.getWidget(InterfaceID.ChatLeft.TEXT) == null;
		});
	}

