	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();
		if (containerId == InventoryID.INV || containerId == InventoryID.WORN)
		{
			if (containerId == InventoryID.INV)
			{
				recordHarvestDeltas();
				applyStock(containerId);
				mixingMode.tick();
				if (pendingPotionDrink)
				{
					recordPotionDrink();
				}
			}
			farmingMode.refreshActive();
		}
		else if (containerId == InventoryID.SEED_VAULT)
		{
			pendingVaultScan = true;
		}
		else if (containerId == InventoryID.BANK && isBankOpen())
		{
			if (!stockTracker.hasBankThisSession())
			{
				pendingBankScan = true;
			}
			else
			{
				applyStock(containerId);
			}
		}
		if (containerId != InventoryID.INV && containerId != InventoryID.WORN
			&& containerId != InventoryID.BANK && containerId != InventoryID.SEED_VAULT)
		{
			return;
		}

		refreshOverlays();
	}

