	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = Text.removeTags(event.getMenuOption() != null ? event.getMenuOption() : "");
		String target = Text.removeTags(event.getMenuTarget() != null ? event.getMenuTarget() : "")
			.toLowerCase();
		if (target.contains("compost bin") && "Fill".equals(option))
		{
			pendingWatermelonOnBin = true;
		}
		if (target.contains("bottomless") && "Fill".equals(option))
		{
			compostTracker.setFillWithBottomless(true);
		}
		if ("Compost".equalsIgnoreCase(option))
		{
			lastCompostWasBottomless = farmingMode.hasFilledBottomless();
			WorldPoint compostLocation = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
			fertility.rememberAction(compostLocation);
		}

		herbTeleportTracker.observeMenu(option, target);

		if (event.getMenuAction() == MenuAction.WIDGET_TARGET_ON_GAME_OBJECT || "Inspect".equals(option))
		{
			WorldPoint actionLocation = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
			fertility.rememberAction(actionLocation);
		}

		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return;
		}

		Widget widget = client.getSelectedWidget();
		if (widget == null)
		{
			return;
		}

		int itemId = itemManager.canonicalize(widget.getItemId());
		lastCompostWasBottomless = PrayerPotionItems.BOTTOMLESS_IDS.contains(itemId);
		if (PrayerPotionItems.BOTTOMLESS_IDS.contains(itemId) || itemId == PrayerPotionItems.EMPTY_BUCKET)
		{
			compostTracker.setFillWithBottomless(PrayerPotionItems.BOTTOMLESS_IDS.contains(itemId));
		}
		if (itemId == PrayerPotionItems.WATERMELON)
		{
			pendingWatermelonOnBin = true;
		}
		if (itemId == PrayerPotionItems.VOLCANIC_ASH)
		{
			pendingAshOnBin = true;
			pendingWatermelonOnBin = false;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM
			&& event.getType() != ChatMessageType.ENGINE)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		jewelleryTracker.onChat(message);
		if (CRUSH_NEST.matcher(message).find())
		{
			pendingCrushNest = true;
		}
		charges.onGameMessage(message);
		recordChargeProfits();
		if (ALCH_PROC.matcher(message).find() || MIX_POTION.matcher(message).find())
		{
			if (config.repeatMixingAlert() && mixingAlerted && mixingMode.missingCheckedGear())
			{
				notifyMixingAlert();
			}
		}
		if (isAcceptedTrade(message))
		{
			settleTrade();
		}
		if (isPotionDrink(message))
		{
			pendingPotionDrink = true;
			drinkWaitTicks = 2;
			recordPotionDrink();
		}

		Player player = client.getLocalPlayer();
		WorldPoint fallback = player != null ? player.getWorldLocation() : null;
		WorldPoint actionLocation = fallback;
		String lower = message.toLowerCase();
		if (lower.contains("compost") || lower.contains("you plant") || lower.contains("soil has"))
		{
			actionLocation = fertility.takePendingOr(fallback);
			long patchKey = patchOverlay.nearestPatchKey(actionLocation);
			fertility.onGameMessage(message, patchKey);
			updateHerbCompost(message, actionLocation);
		}

		if (PICK_HERBS.matcher(message).find())
		{
			harvestGraceTicks = HARVEST_GRACE_TICKS;
		}
		if (HARVEST_SNAPE.matcher(message).find())
		{
			harvestGraceTicks = HARVEST_GRACE_TICKS;
		}

		if (TREAT_COMPOST.matcher(message).find())
		{
			int compostId = compostItemId(message);
			boolean usedBottomless = lastCompostWasBottomless
				|| (farmingMode.hasFilledBottomless() && farmingMode.compostBuckets() == 0);
			if (usedBottomless)
			{
				charges.usedBottomlessCharge();
			}
			else
			{
				addProfit(LedgerType.SPEND, compostId, 1, price(compostId));
			}
			lastCompostWasBottomless = false;
		}
		else if (PLANT_RANARR.matcher(message).find())
		{
			herbPatchTracker.markPlanted(actionLocation, PrayerPotionItems.RANARR_GROW_START);
			refreshHerbPatches();
		}
		else if (PLANT_TOADFLAX.matcher(message).find())
		{
			herbPatchTracker.markPlanted(actionLocation, PrayerPotionItems.TOADFLAX_GROW_START);
			refreshHerbPatches();
		}
		else if (PLANT_SNAPDRAGON.matcher(message).find())
		{
			herbPatchTracker.markPlanted(actionLocation, PrayerPotionItems.SNAPDRAGON_GROW_START);
			refreshHerbPatches();
		}
		else if (PLANT_ALLOTMENT.matcher(message).find())
		{
			java.util.regex.Matcher planted = PLANT_ALLOTMENT.matcher(message);
			if (planted.find())
			{
				String crop = planted.group(1);
				if (crop.toLowerCase().contains("snape"))
				{
					recordBountySeedSave(PrayerPotionItems.SNAPE_GRASS_SEED);
				}
				else if (crop.toLowerCase().contains("watermelon"))
				{
					recordBountySeedSave(PrayerPotionItems.WATERMELON_SEED);
				}
				markAllotmentPlanted(actionLocation, AllotmentCrops.growStartForSeed(crop));
				refreshHerbPatches();
			}
		}
		else if (BIN_ULTRA.matcher(message).find())
		{
			recordUltraUpgrade();
		}
		else if (FILL_COMPOST_BUCKET.matcher(message).find() && !compostTracker.isFillWithBottomless())
		{
			recordCompostFill(1, false);
		}
		else if (BIN_EMPTY.matcher(message).find() && compostTracker.pendingBinWatermelons() > 0)
		{
			recordCompostFill(compostTracker.pendingBinWatermelons(), compostTracker.isFillWithBottomless());
		}
		else if (MINE_ASH.matcher(message).find())
		{
			pendingAshMine = true;
		}
		else if (ALCH_PROC.matcher(message).find())
		{
			ProfitPotion potion = config.profitPotion();
			long extra = Math.max(0L, price(potion.getPotion4Id()) - price(potion.getPotion3Id()));
			addProfit(LedgerType.ALCH_GAIN, potion.getPotion4Id(), 1, extra);
		}

		refreshOverlays();
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		int slot = event.getSlot();
		if (slot < 0 || slot >= geSoldQty.length)
		{
			return;
		}
		applyGrandExchangeOffer(slot, event.getOffer());
	}

	private void beginGrandExchangeSync()
	{
		geIgnoreTicks = GE_LOGIN_TICKS;
	}

	private void finishGrandExchangeSync()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}
		for (int slot = 0; slot < geSoldQty.length && slot < offers.length; slot++)
		{
			GrandExchangeOffer offer = offers[slot];
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			applyGrandExchangeOffer(slot, offer);
		}
	}

	private void applyGrandExchangeOffer(int slot, GrandExchangeOffer offer)
	{
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			if (geIgnoreTicks > 0 || !gePrimed[slot])
			{
				return;
			}
			geSoldQty[slot] = 0;
			geSpent[slot] = 0;
			geBoughtQty[slot] = 0;
			geBoughtGp[slot] = 0;
			geItemId[slot] = 0;
			gePrimed[slot] = false;
			persistGrandExchangeSlots();
			return;
		}

		boolean alreadyPrimed = gePrimed[slot];
		int itemId = itemManager.canonicalize(offer.getItemId());
		boolean sameItem = geItemId[slot] == 0 || geItemId[slot] == itemId;
		if (!sameItem)
		{
			geSoldQty[slot] = 0;
			geSpent[slot] = 0;
			geBoughtQty[slot] = 0;
			geBoughtGp[slot] = 0;
		}
		boolean countDeltas = profitStore.isGeTracked()
			&& (alreadyPrimed
				|| (sameItem && (geSoldQty[slot] != 0
					|| geSpent[slot] != 0
					|| geBoughtQty[slot] != 0
					|| geBoughtGp[slot] != 0)));
		geItemId[slot] = itemId;
		gePrimed[slot] = true;

		GrandExchangeOfferState state = offer.getState();
		if (state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.BUYING)
		{
			int qtyDelta = offer.getQuantitySold() - geBoughtQty[slot];
			long gpDelta = offer.getSpent() - geBoughtGp[slot];
			geBoughtQty[slot] = offer.getQuantitySold();
			geBoughtGp[slot] = offer.getSpent();
			geSoldQty[slot] = 0;
			geSpent[slot] = 0;
			if (countDeltas && qtyDelta > 0 && gpDelta > 0)
			{
				LedgerType jewelleryType = JewelleryTracker.geSpendType(itemId);
				if (jewelleryType != null)
				{
					addProfit(jewelleryType, itemId, qtyDelta, gpDelta);
				}
				else if (PrayerPotionItems.GE_SPEND_IDS.contains(itemId))
				{
					addProfit(LedgerType.SPEND, itemId, qtyDelta, gpDelta);
					stockTracker.adjust(itemId, qtyDelta);
				}
			}
			persistGrandExchangeSlots();
			profitStore.markGeTracked();
			return;
		}

		if (state != GrandExchangeOfferState.SOLD && state != GrandExchangeOfferState.SELLING)
		{
			persistGrandExchangeSlots();
			profitStore.markGeTracked();
			return;
		}

		int qtyDelta = offer.getQuantitySold() - geSoldQty[slot];
		long gpDelta = offer.getSpent() - geSpent[slot];
		geSoldQty[slot] = offer.getQuantitySold();
		geSpent[slot] = offer.getSpent();
		geBoughtQty[slot] = 0;
		geBoughtGp[slot] = 0;
		if (countDeltas && qtyDelta > 0 && gpDelta > 0
			&& PrayerPotionItems.TRACKED_POTION_IDS.contains(itemId))
		{
			addProfit(LedgerType.GAIN, itemId, qtyDelta, gpDelta);
			stockTracker.adjust(itemId, -qtyDelta);
		}
		persistGrandExchangeSlots();
		profitStore.markGeTracked();
	}

	private void persistGrandExchangeSlots()
	{
		profitStore.saveGeSlots(geSoldQty, geSpent, geBoughtQty, geBoughtGp, geItemId);
	}

	private void resetGrandExchangeSlots()
	{
		profitStore.copyGeSlots(geSoldQty, geSpent, geBoughtQty, geBoughtGp, geItemId);
		Arrays.fill(gePrimed, false);
		geIgnoreTicks = 0;
	}

	private void refreshOverlays()
	{
		boolean farming = config.farmingOverlaysEnabled() && farmingMode.isActive();
		syncInfoBox("secateurs", farming && farmingMode.requiresMagicSecateurs() && !farmingMode.hasMagicSecateurs(),
			PrayerPotionItems.MAGIC_SECATEURS, "X", config.badColor(), true, "Magic secateurs missing");
		syncInfoBox("cape", farming && farmingMode.requiresFarmingCape() && !farmingMode.hasFarmingCapeEquipped(),
			PrayerPotionItems.FARMING_CAPE, "X", config.badColor(), true, "Farming cape not equipped");

		charges.noteBountyEquipped(farmingMode.hasBountyEquipped());
		if (farming && config.useAmuletOfBounty())
		{
			boolean equipped = farmingMode.hasBountyEquipped();
			int bounty = charges.getBountyCharges();
			Color color = !equipped
				? config.badColor()
				: ChargeColors.bounty(bounty, config.goodColor(), config.warningColor(), config.badColor());
			String text = !equipped ? "X" : bounty >= 0 ? Integer.toString(bounty) : "?";
			syncInfoBox("bounty", true, PrayerPotionItems.AMULET_OF_BOUNTY, text, color, !equipped, "Amulet of Bounty");
		}
		else
		{
			removeInfoBox("bounty");
		}

		if (farming && config.useBottomlessBucket())
		{
			int uses = charges.getBottomlessUses();
			String text = uses >= 0 ? Integer.toString(uses) : "?";
			Color color = ChargeColors.longCharge(uses, config.goodColor(), config.warningColor(), config.badColor());
			syncInfoBox("bottomless", true, PrayerPotionItems.BOTTOMLESS_FILLED, text, color, false, "Bottomless compost uses");
		}
		else
		{
			removeInfoBox("bottomless");
		}

		if (farming && config.useCompostBuckets())
		{
			int itemId = config.compostType().getItemId();
			syncInfoBox("buckets", true, itemId,
				Integer.toString(farmingMode.compostBuckets()), config.goodColor(), false,
				config.compostType().toString() + " buckets");
		}
		else
		{
			removeInfoBox("buckets");
		}

		boolean mixing = mixingMode.isActive();
		boolean equippedAlch = mixingMode.hasAlchemistsAmuletEquipped();
		if (mixing && config.usePrescriptionGoggles())
		{
			boolean equipped = mixingMode.hasGogglesEquipped();
			syncInfoBox("goggles", true, PrayerPotionItems.GOGGLES, equipped ? "" : "X",
				equipped ? config.goodColor() : config.badColor(), !equipped, "Prescription Goggles");
		}
		else
		{
			removeInfoBox("goggles");
		}

		if (mixing && config.useAlchemistsAmulet() && !mixingMode.hasUsableAlchemistsAmulet())
		{
			syncInfoBox("alchemist", true, PrayerPotionItems.ALCHEMISTS_AMULET_CHARGED,
				equippedAlch ? "0" : "X", config.badColor(), true, "Alchemist's Amulet");
		}
		else if (equippedAlch)
		{
			int amuletCharges = charges.getAlchemistCharges();
			String text = amuletCharges >= 0 ? Integer.toString(amuletCharges) : "?";
			Color color = ChargeColors.longCharge(amuletCharges, config.goodColor(), config.warningColor(), config.badColor());
			syncInfoBox("alchemist", true, PrayerPotionItems.ALCHEMISTS_AMULET_CHARGED, text,
				color, false, "Alchemist's Amulet");
		}
		else
		{
			removeInfoBox("alchemist");
		}

		if (mixing && mixingMode.missingCheckedGear())
		{
			if (!mixingAlerted)
			{
				notifyMixingAlert();
				mixingAlerted = true;
			}
		}
		else
		{
			mixingAlerted = false;
		}
	}

	private void notifyMixingAlert()
	{
		Notification notification = config.mixingAlert();
		if (!notification.isEnabled())
		{
			return;
		}
		notifier.notify(notification.withSendWhenFocused(true).withInitialized(true),
			"Mixing " + mixingMode.mixingDisplayName() + "s without required Mixology gear");
	}

