	private void updateHerbCompost(String message, WorldPoint location)
	{
		String lower = message.toLowerCase();
		boolean herb = lower.contains("herb");
		boolean allotment = !herb && (lower.contains("allotment")
			|| lower.contains("potato") || lower.contains("onion") || lower.contains("cabbage")
			|| lower.contains("tomato") || lower.contains("sweetcorn") || lower.contains("strawberry")
			|| lower.contains("watermelon") || lower.contains("snape"));
		if (!herb && !allotment && (TREAT_COMPOST.matcher(message).find()
			|| lower.contains("soil has been treated")
			|| lower.contains("already been treated")
			|| lower.contains("already been fertilised")
			|| lower.contains("soil has not been treated")))
		{
			allotment = allotmentAt(location) != null;
			herb = !allotment;
		}
		if (TREAT_COMPOST.matcher(message).find()
			|| lower.contains("soil has been treated")
			|| lower.contains("already been treated")
			|| lower.contains("already been fertilised"))
		{
			if (herb)
			{
				herbPatchTracker.setCompost(location, compostName(message));
			}
			AllotmentPatch allotmentPatch = allotmentAt(location);
			if (allotment && allotmentPatch != null)
			{
				allotmentPatchTracker.setCompost(allotmentPatch, compostName(message));
			}
			refreshHerbPatches();
			return;
		}
		if (lower.contains("soil has not been treated"))
		{
			if (herb)
			{
				herbPatchTracker.clearCompost(location);
			}
			AllotmentPatch allotmentPatch = allotmentAt(location);
			if (allotment && allotmentPatch != null)
			{
				allotmentPatchTracker.clearCompost(allotmentPatch);
			}
			refreshHerbPatches();
		}
	}

	private static String compostName(String message)
	{
		String lower = message.toLowerCase();
		if (lower.contains("ultracompost"))
		{
			return "Ultracompost";
		}
		if (lower.contains("supercompost"))
		{
			return "Supercompost";
		}
		if (lower.contains("compost"))
		{
			return "Compost";
		}
		return null;
	}

