	private boolean readBottomlessDialogue()
	{
		String text = firstDialogueText(
			InterfaceID.Objectbox.TEXT,
			InterfaceID.ChatRight.TEXT,
			InterfaceID.ChatLeft.TEXT);
		if (text == null)
		{
			if (lastDialogueText != null)
			{
				lastDialogueText = null;
				charges.clearLingeringApply();
			}
			return false;
		}
		if (text.equals(lastDialogueText))
		{
			return true;
		}
		lastDialogueText = text;
		boolean handled = charges.onGameMessage(text);
		recordChargeProfits();
		return handled;
	}

	private String firstDialogueText(int... widgetIds)
	{
		for (int widgetId : widgetIds)
		{
			Widget widget = client.getWidget(widgetId);
			if (widget == null)
			{
				continue;
			}

			String text = widget.getText();
			if (text == null || text.isEmpty())
			{
				continue;
			}

			return Text.removeTags(text.replace("<br>", " ").replace('\n', ' '))
				.replace('\u00A0', ' ')
				.trim()
				.replaceAll("\\s+", " ");
		}
		return null;
	}

	private boolean farmingScene()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.isInInstancedRegion())
		{
			return false;
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint location = player.getWorldLocation();
		if (location == null)
		{
			return false;
		}
		int regionId = location.getRegionID();
		return HerbPatch.forRegion(regionId) != null || AllotmentPatch.inFarmingRegion(regionId);
	}

	private void rebuildPatches()
	{
		if (!farmingScene())
		{
			patchOverlay.clear();
			rebuildTicks = 0;
			return;
		}

		java.util.ArrayList<GameObject> found = new java.util.ArrayList<>();
		WorldView worldView = client.getTopLevelWorldView();
		if (worldView != null)
		{
			collectPatches(worldView.getScene(), found);
		}
		else
		{
			collectPatches(client.getScene(), found);
		}
		if (!found.isEmpty())
		{
			patchOverlay.clear();
			for (GameObject object : found)
			{
				patchOverlay.add(object);
			}
		}
	}

	private void collectPatches(Scene scene, java.util.List<GameObject> found)
	{
		if (scene == null)
		{
			return;
		}

		Tile[][][] tiles = scene.getTiles();
		if (tiles == null)
		{
			return;
		}

		for (Tile[][] plane : tiles)
		{
			if (plane == null)
			{
				continue;
			}
			for (Tile[] row : plane)
			{
				if (row == null)
				{
					continue;
				}
				for (Tile tile : row)
				{
					if (tile == null || tile.getGameObjects() == null)
					{
						continue;
					}
					for (GameObject object : tile.getGameObjects())
					{
						if (object != null)
						{
							found.add(object);
						}
					}
				}
			}
		}
	}

