	private void recordHarvestDeltas()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		int ranarr = countHarvestRanarr(inventory);
		int snapdragon = countHarvestSnapdragon(inventory);
		int toadflax = countHarvestToadflax(inventory);
		int snape = countHarvestSnape(inventory);
		int watermelon = countItems(inventory, PrayerPotionItems.WATERMELON);
		int ash = countItems(inventory, PrayerPotionItems.VOLCANIC_ASH);
		if (shouldCountHarvest())
		{
			int ranarrDelta = ranarr - lastRanarrCount;
			int snapdragonDelta = snapdragon - lastSnapdragonCount;
			int toadflaxDelta = toadflax - lastToadflaxCount;
			int snapeDelta = snape - lastSnapeCount;
			int watermelonDelta = watermelon - lastWatermelonCount;
			if (isPatchHarvestDelta(ranarrDelta))
			{
				addProfit(LedgerType.HARVEST, PrayerPotionItems.GRIMY_RANARR, ranarrDelta, 0);
			}
			if (isPatchHarvestDelta(snapdragonDelta))
			{
				addProfit(LedgerType.HARVEST, PrayerPotionItems.GRIMY_SNAPDRAGON, snapdragonDelta, 0);
			}
			if (isPatchHarvestDelta(toadflaxDelta))
			{
				addProfit(LedgerType.HARVEST, PrayerPotionItems.GRIMY_TOADFLAX, toadflaxDelta, 0);
			}
			if (isPatchHarvestDelta(snapeDelta))
			{
				addProfit(LedgerType.HARVEST, PrayerPotionItems.SNAPE_GRASS, snapeDelta, 0);
			}
			if (watermelonDelta > 0 && farmingMode.isActive())
			{
				compostTracker.harvested(watermelonDelta);
				addProfit(LedgerType.GAIN, PrayerPotionItems.WATERMELON, watermelonDelta,
					watermelonDelta * price(PrayerPotionItems.WATERMELON));
			}
		}
		int watermelonUsed = lastWatermelonCount - watermelon;
		if (watermelonUsed > 0 && pendingWatermelonOnBin)
		{
			recordWatermelonsAdded(watermelonUsed);
			pendingWatermelonOnBin = false;
		}
		int ashUsed = lastAshCount - ash;
		if (ashUsed > 0 && pendingAshOnBin)
		{
			recordUltraUpgrade(ashUsed >= 50 ? 30 : 15);
			pendingAshOnBin = false;
		}
		if (ash > lastAshCount && pendingAshMine)
		{
			int mined = ash - lastAshCount;
			addProfit(LedgerType.GAIN, PrayerPotionItems.VOLCANIC_ASH, mined, mined * price(PrayerPotionItems.VOLCANIC_ASH));
			pendingAshMine = false;
		}
		jewelleryTracker.record(inventory, isBankOpen() || isSeedVaultOpen(), this::price, this::addProfit);
		recordNestCrush(inventory);
		lastRanarrCount = ranarr;
		lastSnapdragonCount = snapdragon;
		lastToadflaxCount = toadflax;
		lastSnapeCount = snape;
		lastWatermelonCount = watermelon;
		lastAshCount = ash;
	}

	private void recordChargeProfits()
	{
		int amulets = charges.consumeAppliedAmuletCount();
		if (amulets > 0)
		{
			recordAlchCharge(amulets);
		}
		int alchUsed = charges.consumeAlchemistUsed();
		if (alchUsed > 0)
		{
			profitStore.addAlchChargesUsed(alchUsed);
		}
		int bountyUsed = charges.consumeBountyUsed();
		if (bountyUsed > 0)
		{
			profitStore.addBountyChargesUsed(bountyUsed);
		}
		if (charges.consumeBountySave())
		{
			pendingBountySeedSave = true;
		}
		int delta = charges.consumeBottomlessDelta();
		if (delta > 0)
		{
			recordCompostFill(Math.max(1, delta / 2), true);
		}
		if (alchUsed > 0 || bountyUsed > 0)
		{
			panel.update();
		}
	}

	private void recordBountySeedSave(int seedId)
	{
		if (!pendingBountySeedSave)
		{
			return;
		}
		pendingBountySeedSave = false;
		addProfit(LedgerType.BOUNTY_GAIN, seedId, 2, 2 * price(seedId));
	}

	private void recordAlchCharge(int amulets)
	{
		long unit = price(PrayerPotionItems.AMULET_OF_CHEMISTRY);
		long gp = amulets * unit * 2;
		if (gp > 0)
		{
			addProfit(LedgerType.ALCH_GAIN, PrayerPotionItems.AMULET_OF_CHEMISTRY, amulets, gp);
		}
	}

	private void recordWatermelonsAdded(int quantity)
	{
		compostTracker.addedToBin(quantity);
		int harvestedUsed = compostTracker.consumeHarvested(quantity);
		long melonGp = harvestedUsed * price(PrayerPotionItems.WATERMELON);
		if (melonGp > 0)
		{
			addProfit(LedgerType.SPEND, PrayerPotionItems.WATERMELON, harvestedUsed, melonGp);
		}
		long superGp = quantity * price(PrayerPotionItems.SUPERCOMPOST);
		if (superGp > 0)
		{
			addProfit(LedgerType.GAIN, PrayerPotionItems.SUPERCOMPOST, quantity, superGp);
		}
	}

	private void recordUltraUpgrade()
	{
		int buckets = compostTracker.pendingBinWatermelons();
		recordUltraUpgrade(buckets > 0 ? buckets : 15);
	}

	private void recordUltraUpgrade(int buckets)
	{
		if (compostTracker.isUltra() || buckets <= 0)
		{
			compostTracker.setUltra(true);
			return;
		}
		compostTracker.setUltra(true);
		long extra = buckets * Math.max(0L, price(PrayerPotionItems.ULTRACOMPOST) - price(PrayerPotionItems.SUPERCOMPOST));
		if (extra > 0)
		{
			addProfit(LedgerType.GAIN, PrayerPotionItems.ULTRACOMPOST, buckets, extra);
		}
	}

	private void recordCompostFill(int buckets, boolean doubled)
	{
		if (buckets <= 0)
		{
			return;
		}

		int fromBin = compostTracker.consumeBin(buckets);
		int valued = compostTracker.consumeValued(Math.max(fromBin, buckets));
		int material = Math.max(buckets, fromBin);
		boolean doubledFill = doubled || compostTracker.isFillWithBottomless();
		int productId = compostTracker.isUltra()
			? PrayerPotionItems.ULTRACOMPOST
			: (fromBin > 0 || valued > 0 ? PrayerPotionItems.SUPERCOMPOST : config.compostType().getItemId());
		long unit = price(productId);
		if (valued > 0)
		{
			if (doubledFill && unit > 0)
			{
				addProfit(LedgerType.GAIN, productId, material, material * unit);
			}
			return;
		}

		int harvestedUsed = compostTracker.consumeHarvested(fromBin > 0 ? fromBin : 0);
		int outputQty = doubledFill ? material * 2 : material;
		long melonGp = harvestedUsed * price(PrayerPotionItems.WATERMELON);
		long outputGp = outputQty * unit;
		if (melonGp > 0)
		{
			addProfit(LedgerType.SPEND, PrayerPotionItems.WATERMELON, harvestedUsed, melonGp);
		}
		if (outputGp > 0)
		{
			addProfit(LedgerType.GAIN, productId, outputQty, outputGp);
		}
	}

