	private void snapshotTradeConfirm()
	{
		if (client.getWidget(InterfaceID.Tradeconfirm.UNIVERSE) == null
			&& client.getWidget(InterfaceID.Tradeconfirm.YOUR_OFFER) == null)
		{
			return;
		}
		TradeSide give = mergeTrade(
			readTradeContainer(client.getItemContainer(InventoryID.TRADEOFFER)),
			readTradeSide(client.getWidget(InterfaceID.Tradeconfirm.YOUR_OFFER)),
			readTradeText(client.getWidget(InterfaceID.Tradeconfirm.YOU_WILL_GIVE)));
		TradeSide receive = mergeTrade(
			readTradeContainer(client.getItemContainer(OTHER_TRADEOFFER)),
			readTradeSide(client.getWidget(InterfaceID.Tradeconfirm.OTHER_OFFER)),
			readTradeText(client.getWidget(InterfaceID.Tradeconfirm.YOU_WILL_RECEIVE)));
		if (give.empty && receive.empty)
		{
			return;
		}
		boolean firstSnapshot = !pendingTrade;
		pendingTrade = true;
		tradeWaitTicks = 4;
		tradeGivePots4 = give.pots4;
		tradeGivePotsAny = give.potsAny;
		tradeGiveCoins = give.coins;
		tradeReceivePots4 = receive.pots4;
		tradeReceivePotsAny = receive.potsAny;
		tradeReceiveCoins = receive.coins;
		if (firstSnapshot)
		{
			stockTracker.skipNextPotionSales(Math.max(0, tradeGivePots4));
		}
	}

	private void expireCancelledTrade()
	{
		if (!pendingTrade
			|| client.getWidget(InterfaceID.Tradeconfirm.UNIVERSE) != null
			|| client.getWidget(InterfaceID.Tradeconfirm.YOUR_OFFER) != null)
		{
			return;
		}
		if (tradeWaitTicks > 0)
		{
			tradeWaitTicks--;
			return;
		}
		pendingTrade = false;
		stockTracker.clearPotionSaleSkip();
	}

	private void settleTrade()
	{
		if (!pendingTrade)
		{
			snapshotTradeConfirm();
		}
		if (!pendingTrade)
		{
			return;
		}
		int potNetAny = tradeReceivePotsAny - tradeGivePotsAny;
		int potNet4 = tradeReceivePots4 - tradeGivePots4;
		int coinNet = tradeReceiveCoins - tradeGiveCoins;
		pendingTrade = false;
		tradeWaitTicks = 0;
		if (tradeGivePotsAny == 0 && tradeReceivePotsAny == 0)
		{
			stockTracker.clearPotionSaleSkip();
			return;
		}
		int potion4Id = config.profitPotion().getPotion4Id();
		if (potNetAny < 0 && coinNet > 0)
		{
			addProfit(LedgerType.GAIN, potion4Id, Math.max(1, -potNet4), coinNet);
		}
		else if (potNetAny > 0 && coinNet < 0)
		{
			addProfit(LedgerType.SPEND, potion4Id, Math.max(1, potNet4), -coinNet);
		}
		if (!stockTracker.hasBankThisSession() && potNet4 != 0)
		{
			stockTracker.adjust(potion4Id, potNet4);
		}
	}

	private static boolean isAcceptedTrade(String message)
	{
		String lower = message.toLowerCase();
		return (lower.contains("accepted trade") || lower.contains("accepted the trade"))
			&& !lower.contains("has accepted")
			&& !lower.contains("other player");
	}

	private static boolean isPotionDrink(String message)
	{
		String lower = message.toLowerCase();
		return lower.contains("you drink")
			&& (lower.contains("prayer potion") || lower.contains("super restore") || lower.contains("sanfew"));
	}

	private void recordPotionDrink()
	{
		if (!pendingPotionDrink || pendingTrade)
		{
			return;
		}
		int drop = stockTracker.peekPp4Decrease();
		if (drop <= 0)
		{
			return;
		}
		pendingPotionDrink = false;
		stockTracker.consumePp4Decrease();
		if (!stockTracker.hasBankThisSession())
		{
			stockTracker.skipNextPotionSales(drop);
		}
	}

	private TradeSide readTradeSide(Widget parent)
	{
		TradeSide side = new TradeSide();
		if (parent == null)
		{
			side.empty = true;
			return side;
		}
		addTradeWidgets(side, parent.getDynamicChildren());
		addTradeWidgets(side, parent.getChildren());
		side.empty = side.potsAny == 0 && side.coins == 0;
		return side;
	}

	private void addTradeWidgets(TradeSide side, Widget[] children)
	{
		if (children == null)
		{
			return;
		}
		for (Widget child : children)
		{
			if (child == null)
			{
				continue;
			}
			int rawId = child.getItemId();
			if (rawId <= 0)
			{
				continue;
			}
			int itemId = itemManager.canonicalize(rawId);
			int qty = Math.max(child.getItemQuantity(), 0);
			if (itemId == ItemID.COINS)
			{
				side.coins += qty;
			}
			else if (PrayerPotionItems.TRACKED_POTION_IDS.contains(itemId))
			{
				side.potsAny += qty;
				if (PrayerPotionItems.TRACKED_POTION_4_IDS.contains(itemId))
				{
					side.pots4 += qty;
				}
			}
		}
	}

	private TradeSide readTradeContainer(ItemContainer container)
	{
		TradeSide side = new TradeSide();
		if (container == null || container.getItems() == null)
		{
			side.empty = true;
			return side;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			int itemId = itemManager.canonicalize(item.getId());
			int qty = Math.max(item.getQuantity(), 0);
			if (itemId == ItemID.COINS)
			{
				side.coins += qty;
			}
			else if (PrayerPotionItems.TRACKED_POTION_IDS.contains(itemId))
			{
				side.potsAny += qty;
				if (PrayerPotionItems.TRACKED_POTION_4_IDS.contains(itemId))
				{
					side.pots4 += qty;
				}
			}
		}
		side.empty = side.potsAny == 0 && side.coins == 0;
		return side;
	}

	private static TradeSide mergeTrade(TradeSide... sides)
	{
		TradeSide merged = new TradeSide();
		merged.empty = true;
		for (TradeSide side : sides)
		{
			if (side == null)
			{
				continue;
			}
			merged.pots4 = Math.max(merged.pots4, side.pots4);
			merged.potsAny = Math.max(merged.potsAny, side.potsAny);
			merged.coins = Math.max(merged.coins, side.coins);
		}
		merged.empty = merged.potsAny == 0 && merged.coins == 0;
		return merged;
	}

	private static TradeSide readTradeText(Widget widget)
	{
		TradeSide side = new TradeSide();
		if (widget == null || widget.getText() == null || widget.getText().isEmpty())
		{
			side.empty = true;
			return side;
		}
		String text = Text.removeTags(widget.getText()).toLowerCase();
		if (text.contains("nothing"))
		{
			side.empty = true;
			return side;
		}
		side.pots4 = countNamedAmount(text, "prayer potion(4)") + countNamedAmount(text, "prayer potion (4)");
		side.potsAny = side.pots4
			+ countNamedAmount(text, "prayer potion(3)") + countNamedAmount(text, "prayer potion (3)")
			+ countNamedAmount(text, "prayer potion(2)") + countNamedAmount(text, "prayer potion (2)")
			+ countNamedAmount(text, "prayer potion(1)") + countNamedAmount(text, "prayer potion (1)");
		side.coins = countNamedAmount(text, "coins");
		side.empty = side.potsAny == 0 && side.coins == 0;
		return side;
	}

	private static int countNamedAmount(String text, String name)
	{
		int index = text.indexOf(name);
		if (index < 0)
		{
			return 0;
		}
		String after = text.substring(index + name.length());
		StringBuilder digits = new StringBuilder();
		for (int i = 0; i < after.length(); i++)
		{
			char ch = after.charAt(i);
			if (Character.isDigit(ch))
			{
				digits.append(ch);
			}
			else if (ch == ',' || ch == ' ' || ch == 'x' || ch == ':')
			{
				if (digits.length() > 0 && ch != ',')
				{
					break;
				}
			}
			else if (digits.length() > 0)
			{
				break;
			}
		}
		if (digits.length() == 0)
		{
			return 1;
		}
		try
		{
			return Integer.parseInt(digits.toString());
		}
		catch (NumberFormatException ignored)
		{
			return 1;
		}
	}

	private static final class TradeSide
	{
		private int pots4;
		private int potsAny;
		private int coins;
		private boolean empty;
	}

	private int countHarvestRanarr(ItemContainer inventory)
	{
		return countItems(inventory, PrayerPotionItems.GRIMY_RANARR)
			+ countItems(inventory, PrayerPotionItems.CLEAN_RANARR);
	}

	private int countHarvestSnapdragon(ItemContainer inventory)
	{
		return countItems(inventory, PrayerPotionItems.GRIMY_SNAPDRAGON)
			+ countItems(inventory, PrayerPotionItems.CLEAN_SNAPDRAGON);
	}

	private int countHarvestToadflax(ItemContainer inventory)
	{
		return countItems(inventory, PrayerPotionItems.GRIMY_TOADFLAX)
			+ countItems(inventory, PrayerPotionItems.CLEAN_TOADFLAX);
	}

	private void recordNestCrush(ItemContainer inventory)
	{
		int empty = countItems(inventory, PrayerPotionItems.BIRD_NEST_EMPTY);
		int crushed = countItems(inventory, PrayerPotionItems.CRUSHED_BIRD_NEST);
		boolean storageOpen = isBankOpen() || isSeedVaultOpen();
		if (!storageOpen)
		{
			int crushedMade = Math.min(Math.max(0, lastEmptyNestCount - empty),
				Math.max(0, crushed - lastCrushedNestCount));
			if (crushedMade > 0 && (pendingCrushNest || lastEmptyNestCount > empty))
			{
				long unit = price(PrayerPotionItems.CRUSHED_BIRD_NEST) - price(PrayerPotionItems.BIRD_NEST_EMPTY);
				if (unit > 0)
				{
					addProfit(LedgerType.GAIN, PrayerPotionItems.CRUSHED_BIRD_NEST, crushedMade, unit * crushedMade);
				}
				else if (unit < 0)
				{
					addProfit(LedgerType.SPEND, PrayerPotionItems.CRUSHED_BIRD_NEST, crushedMade, -unit * crushedMade);
				}
			}
		}
		pendingCrushNest = false;
		lastEmptyNestCount = empty;
		lastCrushedNestCount = crushed;
	}

	private int countHarvestSnape(ItemContainer inventory)
	{
		return countItems(inventory, PrayerPotionItems.SNAPE_GRASS);
	}

	private void refreshHarvestGrace()
	{
		if (harvestGraceTicks > 0)
		{
			harvestGraceTicks--;
		}
	}

	private boolean shouldCountHarvest()
	{
		return harvestCountsReady
			&& !isBankOpen()
			&& !isSeedVaultOpen()
			&& (harvestGraceTicks > 0 || isAtHarvestablePlot());
	}

	private boolean isAtHarvestablePlot()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return false;
		}
		WorldPoint loc = player.getWorldLocation();
		return nearHarvestable(loc, patchOverlay.harvestableHerbLocations())
			|| nearHarvestable(loc, patchOverlay.harvestableAllotmentLocations());
	}

	private static boolean nearHarvestable(WorldPoint loc, List<WorldPoint> patches)
	{
		for (WorldPoint patch : patches)
		{
			if (patch != null && patch.distanceTo(loc) <= HARVEST_PLOT_DISTANCE)
			{
				return true;
			}
		}
		return false;
	}

	private boolean isPatchHarvestDelta(int delta)
	{
		return delta > 0 && delta <= ProfitStore.MAX_HARVEST_DELTA;
	}

	private boolean isBankOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		return bank != null && !bank.isHidden();
	}

	private boolean isSeedVaultOpen()
	{
		Widget frame = client.getWidget(InterfaceID.SeedVault.FRAME);
		if (frame != null && !frame.isHidden())
		{
			return true;
		}
		Widget vault = client.getWidget(InterfaceID.SEED_VAULT, 0);
		if (vault != null && !vault.isHidden())
		{
			return true;
		}
		Widget deposit = client.getWidget(InterfaceID.SEED_VAULT_DEPOSIT, 0);
		return deposit != null && !deposit.isHidden();
	}

	private int countItems(ItemContainer inventory, int itemId)
	{
		if (inventory == null || inventory.getItems() == null)
		{
			return 0;
		}

		int total = 0;
		for (Item item : inventory.getItems())
		{
			if (item != null && isSameItem(item.getId(), itemId))
			{
				total += Math.max(item.getQuantity(), 0);
			}
		}
		return total;
	}

	private boolean isSameItem(int inventoryId, int targetId)
	{
		if (inventoryId <= 0)
		{
			return false;
		}
		if (inventoryId == targetId || itemManager.canonicalize(inventoryId) == targetId)
		{
			return true;
		}
		ItemComposition composition = itemManager.getItemComposition(inventoryId);
		return composition != null && composition.getLinkedNoteId() == targetId;
	}

	private long price(int itemId)
	{
		return Math.max(0L, itemManager.getItemPrice(itemId));
	}

