	private static BufferedImage fitNavIcon(BufferedImage source)
	{
		int width = source.getWidth();
		int height = source.getHeight();
		int minX = width;
		int minY = height;
		int maxX = -1;
		int maxY = -1;
		for (int y = 0; y < height; y++)
		{
			for (int x = 0; x < width; x++)
			{
				if ((source.getRGB(x, y) >>> 24) > 16)
				{
					minX = Math.min(minX, x);
					minY = Math.min(minY, y);
					maxX = Math.max(maxX, x);
					maxY = Math.max(maxY, y);
				}
			}
		}
		if (maxX < minX)
		{
			return ImageUtil.resizeImage(source, 16, 16);
		}

		BufferedImage cropped = new BufferedImage(maxX - minX + 1, maxY - minY + 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = cropped.createGraphics();
		graphics.drawImage(source, 0, 0, cropped.getWidth(), cropped.getHeight(), minX, minY, maxX + 1, maxY + 1, null);
		graphics.dispose();
		return ImageUtil.resizeImage(cropped, 16, 16);
	}

	private static BufferedImage fallbackNavIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setColor(new Color(46, 160, 67));
		graphics.fillRoundRect(2, 1, 12, 14, 4, 4);
		graphics.setColor(new Color(20, 80, 30));
		graphics.drawRoundRect(2, 1, 12, 14, 4, 4);
		graphics.dispose();
		return image;
	}
