package com.potionprofitpro.charges;

import java.awt.Color;

public final class ChargeColors
{
	private static final Color YELLOW = new Color(255, 210, 0);

	private ChargeColors()
	{
	}

	public static Color bounty(int charges, Color good, Color warning, Color bad)
	{
		return fade(charges, 5, 1, good, warning, bad);
	}

	public static Color longCharge(int charges, Color good, Color warning, Color bad)
	{
		return fade(charges, 50, 10, good, warning, bad);
	}

	static Color fade(int charges, int greenAt, int redAt, Color good, Color warning, Color bad)
	{
		if (charges < 0 || charges >= greenAt)
		{
			return good;
		}
		if (charges <= redAt)
		{
			return bad;
		}

		float t = (greenAt - charges) / (float) (greenAt - redAt);
		if (t <= 0.5f)
		{
			return lerp(good, YELLOW, t / 0.5f);
		}
		if (t <= 0.75f)
		{
			return lerp(YELLOW, warning, (t - 0.5f) / 0.25f);
		}
		return lerp(warning, bad, (t - 0.75f) / 0.25f);
	}

	private static Color lerp(Color from, Color to, float t)
	{
		float clamped = Math.max(0f, Math.min(1f, t));
		int r = Math.round(from.getRed() + (to.getRed() - from.getRed()) * clamped);
		int g = Math.round(from.getGreen() + (to.getGreen() - from.getGreen()) * clamped);
		int b = Math.round(from.getBlue() + (to.getBlue() - from.getBlue()) * clamped);
		return new Color(r, g, b);
	}
}

