import com.potionprofitpro.PotionProfitProConfig;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.client.config.ConfigManager;

@Singleton
public class ChargeTracker
{
	private static final String KEY_BOUNTY = "bountyCharges";
	private static final String KEY_BOTTOMLESS = "bottomlessUses";
	private static final String KEY_ALCHEMIST = "alchemistCharges";
	private static final int BOUNTY_FULL_CHARGES = 10;

	private static final Pattern BOUNTY_CHECK = Pattern.compile(
		"Your amulet of bounty has (\\d+) charges? left\\.");
	private static final Pattern BOUNTY_USED = Pattern.compile(
		"Your amulet of bounty saves some seeds for you\\. It has (\\d) charges? left\\.");
	private static final String BOUNTY_BREAK =
		"Your amulet of bounty saves some seeds for you. It then crumbles to dust.";

	private static final Pattern BOTTOMLESS_USES = Pattern.compile(
		"(?i)(?:bottomless compost bucket|the bucket) (?:has|contains) ([\\d,]+) uses?");
	private static final Pattern BOTTOMLESS_HOLDING = Pattern.compile(
		"(?i)(?:bottomless )?compost bucket is currently holding ([\\d,]+) uses");
	private static final Pattern BOTTOMLESS_TOTAL = Pattern.compile(
		"(?i)now contains a total of ([\\d,]+) uses");
	private static final Pattern BOTTOMLESS_CONTAINS_USES = Pattern.compile(
		"(?i)(?:bottomless compost bucket|the bucket).{0,80}?([\\d,]+) uses");
	private static final Pattern BOTTOMLESS_COMPOST_USES = Pattern.compile(
		"(?i)([\\d,]+) uses of (?:ultra|super)?compost");
	private static final Pattern BOTTOMLESS_REMAINING = Pattern.compile(
		"(?i)([\\d,]+) uses? of (?:ultra|super)?compost remaining");
	private static final Pattern BOTTOMLESS_EMPTY = Pattern.compile(
		"(?i)(?:bottomless )?compost bucket is currently empty");

	private static final Pattern ALCHEMIST_CHARGES = Pattern.compile(
		"(?i)(?:alchemist['’]?s amulet|amulet of chemistry) has ([\\d,]+) charges?");
	private static final Pattern ALCHEMIST_USED = Pattern.compile(
		"(?i)helps you create a 4-dose potion\\. It has ([\\d,]+|one) charges? left");
	private static final Pattern ALCHEMIST_EMPTY = Pattern.compile(
		"(?i)helps you create a 4-dose potion\\. It no longer has any charges");
	private static final Pattern ALCHEMIST_BREAK = Pattern.compile(
		"(?i)(?:alchemist['’]?s amulet|amulet of chemistry).+crumbles to dust");
	private static final Pattern ALCHEMIST_APPLY = Pattern.compile(
		"(?i)you apply (?:an additional )?([\\d,]+) charges to your alchemist['’]?s amulet");
	private static final Pattern ALCHEMIST_TOTAL = Pattern.compile(
		"(?i)it now has ([\\d,]+) charges in total");

	@Inject
	private ConfigManager configManager;

	@Getter
	private int bountyCharges = -1;

	@Getter
	private int bottomlessUses = -1;

	@Getter
	private int alchemistCharges = -1;

	private int lastAppliedCharges;
	private int lastBottomlessDelta;
	private int lastAlchemistUsed;
	private int lastBountyUsed;
	private boolean bountySaved;
	private int lastApplyCharges = -1;
	private boolean applyConsumed;
	private boolean bountyEquipped;

	public void load()
	{
		Integer bounty = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_BOUNTY, Integer.class);
		Integer bottomless = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_BOTTOMLESS, Integer.class);
		Integer alchemist = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_ALCHEMIST, Integer.class);
		bountyCharges = bounty == null ? -1 : bounty;
		bottomlessUses = bottomless == null ? -1 : bottomless;
		alchemistCharges = alchemist == null ? -1 : alchemist;
		bountyEquipped = false;
	}

	public boolean onGameMessage(String message)
	{
		Matcher bountyCheck = BOUNTY_CHECK.matcher(message);
		if (bountyCheck.find())
		{
			setBounty(Integer.parseInt(bountyCheck.group(1)));
			return true;
		}

		Matcher bountyUsed = BOUNTY_USED.matcher(message);
		if (bountyUsed.find())
		{
			int next = Integer.parseInt(bountyUsed.group(1));
			lastBountyUsed += 1;
			setBounty(next);
			bountySaved = true;
			return true;
		}

		if (BOUNTY_BREAK.equals(message))
		{
			lastBountyUsed += 1;
			setBounty(0);
			bountySaved = true;
			return true;
		}

		if (parseBottomless(message))
		{
			return true;
		}

		Matcher apply = ALCHEMIST_APPLY.matcher(message);
		if (apply.find())
		{
			int applied = parseCount(apply.group(1));
			if (applyConsumed && applied == lastApplyCharges)
			{
				return true;
			}
			lastApplyCharges = applied;
			lastAppliedCharges = applied;
			applyConsumed = false;
			Matcher appliedTotal = ALCHEMIST_TOTAL.matcher(message);
			if (appliedTotal.find())
			{
				setAlchemist(parseCount(appliedTotal.group(1)));
			}
			else if (alchemistCharges >= 0)
			{
				setAlchemist(alchemistCharges + lastAppliedCharges);
			}
			return true;
		}

		Matcher alchemistCheck = ALCHEMIST_CHARGES.matcher(message);
		if (alchemistCheck.find())
		{
			setAlchemist(parseCount(alchemistCheck.group(1)));
			return true;
		}

		Matcher alchemistUsed = ALCHEMIST_USED.matcher(message);
		if (alchemistUsed.find())
		{
			String match = alchemistUsed.group(1);
			int next = "one".equalsIgnoreCase(match) ? 1 : parseCount(match);
			lastAlchemistUsed += 1;
			setAlchemist(next);
			return true;
		}

		if (ALCHEMIST_EMPTY.matcher(message).find() || ALCHEMIST_BREAK.matcher(message).find())
		{
			lastAlchemistUsed += 1;
			setAlchemist(0);
			return true;
		}

		return false;
	}

	public int consumeAppliedAmuletCount()
	{
		int charges = lastAppliedCharges;
		lastAppliedCharges = 0;
		if (charges > 0)
		{
			applyConsumed = true;
		}
		return charges <= 0 ? 0 : charges / 10;
	}

	public void clearLingeringApply()
	{
		applyConsumed = false;
		lastApplyCharges = -1;
	}

	public int consumeBottomlessDelta()
	{
		int delta = lastBottomlessDelta;
		lastBottomlessDelta = 0;
		return delta;
	}

	public int consumeBountyUsed()
	{
		int used = lastBountyUsed;
		lastBountyUsed = 0;
		return used;
	}

	public int consumeAlchemistUsed()
	{
		int used = lastAlchemistUsed;
		lastAlchemistUsed = 0;
		return used;
	}

	public boolean consumeBountySave()
	{
		boolean saved = bountySaved;
		bountySaved = false;
		return saved;
	}

	public void noteBountyEquipped(boolean equipped)
	{
		boolean wasEquipped = bountyEquipped;
		bountyEquipped = equipped;
		if (equipped && !wasEquipped && bountyCharges == 0)
		{
			setBounty(BOUNTY_FULL_CHARGES);
		}
	}

	public void usedBottomlessCharge()
	{
		if (bottomlessUses > 0)
		{
			setBottomless(bottomlessUses - 1);
		}
	}

	private void setBounty(int charges)
	{
		if (bountyCharges == charges)
		{
			return;
		}
		bountyCharges = charges;
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_BOUNTY, charges);
	}

	private void setBottomless(int uses)
	{
		if (bottomlessUses == uses)
		{
			return;
		}
		if (bottomlessUses >= 0 && uses > bottomlessUses)
		{
			lastBottomlessDelta = uses - bottomlessUses;
		}
		bottomlessUses = uses;
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_BOTTOMLESS, uses);
	}

	private void setAlchemist(int charges)
	{
		if (alchemistCharges == charges)
		{
			return;
		}
		alchemistCharges = charges;
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY_ALCHEMIST, charges);
	}

	private boolean parseBottomless(String message)
	{
		Matcher bottomless = BOTTOMLESS_USES.matcher(message);
		if (bottomless.find())
		{
			setBottomless(parseCount(bottomless.group(1)));
			return true;
		}

		Matcher holding = BOTTOMLESS_HOLDING.matcher(message);
		if (holding.find())
		{
			setBottomless(parseCount(holding.group(1)));
			return true;
		}

		Matcher total = BOTTOMLESS_TOTAL.matcher(message);
		if (total.find())
		{
			setBottomless(parseCount(total.group(1)));
			return true;
		}

		Matcher remaining = BOTTOMLESS_REMAINING.matcher(message);
		if (remaining.find())
		{
			setBottomless(parseCount(remaining.group(1)));
			return true;
		}

		if (BOTTOMLESS_EMPTY.matcher(message).find())
		{
			setBottomless(0);
			return true;
		}

		Matcher compostUses = BOTTOMLESS_COMPOST_USES.matcher(message);
		if (compostUses.find())
		{
			setBottomless(parseCount(compostUses.group(1)));
			return true;
		}

		Matcher containsUses = BOTTOMLESS_CONTAINS_USES.matcher(message);
		if (containsUses.find())
		{
			setBottomless(parseCount(containsUses.group(1)));
			return true;
		}

		return false;
	}

	private static int parseCount(String value)
	{
		return Integer.parseInt(value.replace(",", ""));
	}
}

