	public static Decoded decode(int value)
	{
		if (isEmpty(value))
		{
			return Decoded.empty();
		}
		Decoded healthy = healthy(value);
		if (healthy != null)
		{
			return healthy;
		}
		Decoded diseased = diseased(value);
		if (diseased != null)
		{
			return diseased;
		}
		return Decoded.unknown();
	}

	public static boolean isEmpty(int value)
	{
		return between(value, 0, 5)
			|| between(value, 74, 76)
			|| between(value, 81, 83)
			|| between(value, 88, 90)
			|| between(value, 95, 97)
			|| between(value, 104, 106)
			|| between(value, 113, 115)
			|| between(value, 124, 127)
			|| value == 141
			|| between(value, 145, 148)
			|| between(value, 152, 155)
			|| between(value, 159, 162)
			|| between(value, 168, 171)
			|| between(value, 177, 180)
			|| between(value, 188, 192)
			|| value == 205
			|| value == 212
			|| between(value, 216, 219)
			|| between(value, 223, 226)
			|| between(value, 232, 235)
			|| between(value, 241, 244)
			|| between(value, 252, 255);
	}

	public static boolean isUnknown(int value)
