	private static Decoded healthy(int value)
	{
		Decoded potato = crop(value, "Potato", ItemID.POTATO, 6, 9, 10, 12, 70, 73, 4);
		if (potato != null)
		{
			return potato;
		}
		Decoded onion = crop(value, "Onion", ItemID.ONION, 13, 16, 17, 19, 77, 80, 4);
		if (onion != null)
		{
			return onion;
		}
		Decoded cabbage = crop(value, "Cabbage", ItemID.CABBAGE, 20, 23, 24, 26, 84, 87, 4);
		if (cabbage != null)
		{
			return cabbage;
		}
		Decoded tomato = crop(value, "Tomato", ItemID.TOMATO, 27, 30, 31, 33, 91, 94, 4);
		if (tomato != null)
		{
			return tomato;
		}
		Decoded sweetcorn = crop(value, "Sweetcorn", ItemID.SWEETCORN, 34, 39, 40, 42, 98, 103, 6);
		if (sweetcorn != null)
		{
			return sweetcorn;
		}
		Decoded strawberry = crop(value, "Strawberry", ItemID.STRAWBERRY, 43, 48, 49, 51, 107, 112, 6);
		if (strawberry != null)
		{
			return strawberry;
		}
		Decoded watermelon = crop(value, "Watermelon", ItemID.WATERMELON, 52, 59, 60, 62, 116, 123, 8);
		if (watermelon != null)
		{
			return watermelon;
		}
		return crop(value, "Snape grass", ItemID.SNAPE_GRASS, 63, 69, 138, 140, 128, 134, 7);
	}

	private static Decoded diseased(int value)
	{
		if (between(value, 135, 137) || between(value, 199, 201))
		{
			return Decoded.of("Potato", ItemID.POTATO, value <= 137 ? "Diseased" : "Dead", -1, 4, 10);
		}
		if (between(value, 142, 144) || between(value, 206, 208))
		{
			return Decoded.of("Onion", ItemID.ONION, value <= 144 ? "Diseased" : "Dead", -1, 4, 17);
		}
		if (between(value, 149, 151) || between(value, 213, 215))
		{
			return Decoded.of("Cabbage", ItemID.CABBAGE, value <= 151 ? "Diseased" : "Dead", -1, 4, 24);
		}
		if (between(value, 156, 158) || between(value, 220, 222))
		{
			return Decoded.of("Tomato", ItemID.TOMATO, value <= 158 ? "Diseased" : "Dead", -1, 4, 31);
		}
		if (between(value, 163, 167) || between(value, 227, 231))
		{
			return Decoded.of("Sweetcorn", ItemID.SWEETCORN, value <= 167 ? "Diseased" : "Dead", -1, 6, 40);
		}
		if (between(value, 172, 176) || between(value, 236, 240))
		{
			return Decoded.of("Strawberry", ItemID.STRAWBERRY, value <= 176 ? "Diseased" : "Dead", -1, 6, 49);
		}
		if (between(value, 181, 187) || between(value, 245, 251))
		{
			return Decoded.of("Watermelon", ItemID.WATERMELON, value <= 187 ? "Diseased" : "Dead", -1, 8, 60);
		}
		if (between(value, 193, 198) || between(value, 202, 204) || between(value, 209, 211))
		{
			String state = between(value, 196, 198) || between(value, 202, 204) ? "Diseased" : "Dead";
			return Decoded.of("Snape grass", ItemID.SNAPE_GRASS, state, -1, 7, 138);
		}
		return null;
	}

	private static Decoded crop(int value, String name, int itemId, int growStart, int growEnd,
		int harvestStart, int harvestEnd, int wateredStart, int wateredEnd, int stages)
	{
		if (between(value, growStart, growEnd) || between(value, wateredStart, wateredEnd))
		{
			int stage = between(value, growStart, growEnd) ? value - growStart : value - wateredStart;
			return Decoded.of(name, itemId, "Growing", stages - stage, stages, harvestStart);
		}
		if (between(value, harvestStart, harvestEnd))
		{
			return Decoded.of(name, itemId, "Ready", 0, stages, harvestStart);
		}
		return null;
	}

	private static boolean between(int value, int min, int max)
	{
		return value >= min && value <= max;
	}

	public static final class Decoded
	{
		public final String crop;
		public final int itemId;
		public final String state;
		public final int remainingTicks;
		public final int totalTicks;
		public final int harvestStart;

		private Decoded(String crop, int itemId, String state, int remainingTicks, int totalTicks, int harvestStart)
		{
			this.crop = crop;
			this.itemId = itemId;
			this.state = state;
			this.remainingTicks = remainingTicks;
			this.totalTicks = totalTicks;
			this.harvestStart = harvestStart;
		}

		private static Decoded of(String crop, int itemId, String state, int remainingTicks, int totalTicks, int harvestStart)
		{
			return new Decoded(crop, itemId, state, remainingTicks, totalTicks, harvestStart);
		}

		private static Decoded empty()
		{
			return new Decoded("Empty", 0, "Empty", -1, 0, 0);
		}

		private static Decoded unknown()
		{
			return new Decoded("Unknown", 0, "Visit to update", -1, 0, 0);
		}
	}
