	public enum TeleportGroup
	{
		FARMING_GUILD,
		ARDOUGNE,
		CATHERBY,
		FALADOR,
		HOSIDIUS,
		MORYTANIA,
		FORTIS,
		PRIF,
		HARMONY
	}

	private final String location;
	private final int varbit;
	private final TeleportGroup teleportGroup;
	private final boolean teleportAnchor;
	private final int[] regions;

	AllotmentPatch(String location, int varbit, TeleportGroup teleportGroup, boolean teleportAnchor, int... regions)
	{
		this.location = location;
		this.varbit = varbit;
		this.teleportGroup = teleportGroup;
		this.teleportAnchor = teleportAnchor;
		this.regions = regions;
	}

	public String getSiteName()
	{
		switch (teleportGroup)
		{
			case FARMING_GUILD:
				return "Farming Guild";
			case ARDOUGNE:
				return "Ardougne";
			case CATHERBY:
				return "Catherby";
			case FALADOR:
				return "Falador";
			case HOSIDIUS:
				return "Hosidius";
			case MORYTANIA:
				return "Morytania";
			case FORTIS:
				return "Fortis";
			case PRIF:
				return "Prif";
			case HARMONY:
				return "Harmony";
			default:
				return location;
		}
	}

	public boolean containsRegion(int regionId)
	{
		for (int region : regions)
		{
			if (region == regionId)
			{
				return true;
			}
		}
		return false;
	}

	public static boolean inFarmingRegion(int regionId)
	{
		for (AllotmentPatch patch : values())
		{
			if (patch.containsRegion(regionId))
			{
				return true;
			}
		}
		return false;
	}

	public boolean inBounds(WorldPoint location)
	{
		if (location == null || !containsRegion(location.getRegionID()))
		{
			return false;
		}
		if (teleportGroup == TeleportGroup.FALADOR)
		{
			return location.getY() >= 3272;
		}
		if (teleportGroup == TeleportGroup.CATHERBY
			&& location.getX() >= 2816 && location.getY() < 3456)
		{
			return location.getX() < 2840 && location.getY() >= 3440 && location.getPlane() == 0;
		}
		return true;
	}

	public static AllotmentPatch forRegionAndVarbit(int regionId, int varbitId)
	{
		if (varbitId <= 0)
		{
			return null;
		}
		for (AllotmentPatch patch : values())
		{
			if (patch.varbit == varbitId && patch.containsRegion(regionId))
			{
				return patch;
			}
		}
		return null;
	}

	public static AllotmentPatch byLocation(String location)
	{
		if (location == null)
		{
			return null;
		}
		for (AllotmentPatch patch : values())
		{
			if (patch.location.equals(location))
			{
				return patch;
			}
		}
		return null;
	}

	public static AllotmentPatch unambiguousAt(WorldPoint location)
	{
		if (location == null)
		{
			return null;
		}
		AllotmentPatch found = null;
		for (AllotmentPatch patch : values())
		{
			if (!patch.inBounds(location))
			{
				continue;
			}
			if (found != null)
			{
				return null;
			}
			found = patch;
		}
		return found;
	}
}

