@Getter
public enum HerbPatch
{
	FARMING_GUILD("Farming Guild", VarbitID.FARMING_TRANSMIT_E,
		4922, 5177, 5178, 5179, 4921, 4923, 4665, 4666, 4667),
	ARDOUGNE("Ardougne", VarbitID.FARMING_TRANSMIT_D, 10548),
	CATHERBY("Catherby", VarbitID.FARMING_TRANSMIT_D, 11062, 11061, 11318),
	FALADOR("Falador", VarbitID.FARMING_TRANSMIT_D, 12083),
	HOSIDIUS("Hosidius", VarbitID.FARMING_TRANSMIT_D, 6967, 6711),
	MORYTANIA("Morytania", VarbitID.FARMING_TRANSMIT_D, 14391, 14390),
	FORTIS("Fortis", VarbitID.FARMING_TRANSMIT_D, 6192, 6447, 6448, 6449, 6191, 6193),
	TROLL_STRONGHOLD("Troll Stronghold", VarbitID.FARMING_TRANSMIT_A, 11321),
	WEISS("Weiss", VarbitID.FARMING_TRANSMIT_A, 11325),
	HARMONY("Harmony", VarbitID.FARMING_TRANSMIT_B, 15148);

	private final String location;
	private final int varbit;
	private final int[] regions;

	HerbPatch(String location, int varbit, int... regions)
	{
		this.location = location;
		this.varbit = varbit;
		this.regions = regions;
	}

	public boolean containsRegion(int regionId)
	{
		for (int region : regions)
		{
			if (region == regionId)
			{
				return true;
			}
		}
		return false;
	}

	public static HerbPatch forRegion(int regionId)
	{
		for (HerbPatch patch : values())
		{
			if (patch.containsRegion(regionId))
			{
				return patch;
			}
		}
		return null;
	}

	public static HerbPatch byLocation(String location)
	{
		if (location == null)
		{
			return null;
		}
		for (HerbPatch patch : values())
		{
			if (patch.location.equals(location))
			{
				return patch;
			}
		}
		return null;
	}
}

