import lombok.Value;

@Value
public class HerbReadyTime
{
	String clock;
	String tooltip;
	int remainingTicks;
	int totalTicks;

	public static HerbReadyTime none()
	{
		return new HerbReadyTime("", "", 0, 0);
	}

	public boolean isPresent()
	{
		return clock != null && !clock.isEmpty();
	}

	public int percentComplete()
	{
		if (!isPresent() || totalTicks <= 0)
		{
			return 0;
		}
		int grown = totalTicks - remainingTicks;
		return Math.max(0, Math.min(100, grown * 100 / totalTicks));
	}
}

