import lombok.Value;

@Value
public class HerbTeleport
{
	List<Icon> icons;
	String tooltip;
	boolean ready;

	public static HerbTeleport missing()
	{
		return new HerbTeleport(Collections.emptyList(), "No teleport ready", false);
	}

	public static HerbTeleport direct(int itemId, String tooltip)
	{
		return new HerbTeleport(Collections.singletonList(Icon.item(itemId)), tooltip, true);
	}

	public static HerbTeleport directSprite(int spriteId, String tooltip)
	{
		return new HerbTeleport(Collections.singletonList(Icon.sprite(spriteId)), tooltip, true);
	}

	public static HerbTeleport direct(Icon icon, String tooltip)
	{
		return new HerbTeleport(Collections.singletonList(icon), tooltip, true);
	}

	public static HerbTeleport chain(int fromItemId, int toItemId, String tooltip)
	{
		return chain(Icon.item(fromItemId), Icon.item(toItemId), tooltip);
	}

	public static HerbTeleport chain(Icon from, int toItemId, String tooltip)
	{
		return chain(from, Icon.item(toItemId), tooltip);
	}

	public static HerbTeleport chain(Icon from, Icon to, String tooltip)
	{
		return new HerbTeleport(Arrays.asList(from, to), tooltip, true);
	}

	@Value
	public static class Icon
	{
		int id;
		boolean sprite;

		public static Icon item(int itemId)
		{
			return new Icon(itemId, false);
		}

		public static Icon sprite(int spriteId)
		{
			return new Icon(spriteId, true);
		}
	}
}

