	private PrayerPotionItems()
	{
	}

	public static int count(ItemContainer container, int... itemIds)
	{
		int total = 0;
		for (int itemId : itemIds)
		{
			total += quantityOf(container, itemId);
		}
		return total;
	}

	public static int count(ItemContainer container, Set<Integer> itemIds)
	{
		int total = 0;
		for (int itemId : itemIds)
		{
			total += quantityOf(container, itemId);
		}
		return total;
	}

	public static boolean contains(ItemContainer container, int... itemIds)
	{
		return count(container, itemIds) > 0;
	}

	public static boolean contains(ItemContainer container, Set<Integer> itemIds)
	{
		return count(container, itemIds) > 0;
	}

	public static int quantityOf(ItemContainer container, int itemId)
	{
		if (container == null)
		{
			return 0;
		}

		int total = 0;
		Item[] items = container.getItems();
		if (items == null)
		{
			return 0;
		}

		for (Item item : items)
		{
			if (item != null && item.getId() == itemId)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}
}

