package com.potionprofitpro.data;

import lombok.Getter;
import net.runelite.api.ItemContainer;

@Getter
public enum ProfitPotion
{
	PRAYER_POTION("Prayer potion", "Ranarr", PrayerPotionItems.RANARR_GROW_START,
		PrayerPotionItems.GRIMY_RANARR, PrayerPotionItems.CLEAN_RANARR, PrayerPotionItems.RANARR_SEED,
		PrayerPotionItems.RANARR_UNF, PrayerPotionItems.PRAYER_POTION_4, PrayerPotionItems.PRAYER_POTION_3,
		14, PrayerPotionItems.SNAPE_GRASS),
	SUPER_RESTORE("Super restore", "Snapdragon", PrayerPotionItems.SNAPDRAGON_GROW_START,
		PrayerPotionItems.GRIMY_SNAPDRAGON, PrayerPotionItems.CLEAN_SNAPDRAGON, PrayerPotionItems.SNAPDRAGON_SEED,
		PrayerPotionItems.SNAPDRAGON_UNF, PrayerPotionItems.SUPER_RESTORE_4, PrayerPotionItems.SUPER_RESTORE_3,
		14, PrayerPotionItems.RED_SPIDERS_EGGS),
	SANFEW_SERUM("Sanfew serum", "Snapdragon", PrayerPotionItems.SNAPDRAGON_GROW_START,
		PrayerPotionItems.GRIMY_SNAPDRAGON, PrayerPotionItems.CLEAN_SNAPDRAGON, PrayerPotionItems.SNAPDRAGON_SEED,
		PrayerPotionItems.SUPER_RESTORE_4, PrayerPotionItems.SANFEW_4, PrayerPotionItems.SANFEW_3,
		5, PrayerPotionItems.UNICORN_HORN_DUST, PrayerPotionItems.SNAKE_WEED, PrayerPotionItems.NAIL_BEAST_NAILS),
	SARADOMIN_BREW("Saradomin brew", "Toadflax", PrayerPotionItems.TOADFLAX_GROW_START,
		PrayerPotionItems.GRIMY_TOADFLAX, PrayerPotionItems.CLEAN_TOADFLAX, PrayerPotionItems.TOADFLAX_SEED,
		PrayerPotionItems.TOADFLAX_UNF, PrayerPotionItems.SARADOMIN_BREW_4, PrayerPotionItems.SARADOMIN_BREW_3,
		14, PrayerPotionItems.CRUSHED_BIRD_NEST);

	private final String displayName;
	private final String herbName;
	private final int herbGrowStart;
	private final int grimyHerbId;
	private final int cleanHerbId;
	private final int herbSeedId;
	private final int mixPrimaryId;
	private final int potion4Id;
	private final int potion3Id;
	private final int mixCount;
	private final int[] mixSecondaryIds;

	ProfitPotion(String displayName, String herbName, int herbGrowStart, int grimyHerbId, int cleanHerbId,
		int herbSeedId, int mixPrimaryId, int potion4Id, int potion3Id, int mixCount, int... mixSecondaryIds)
	{
		this.displayName = displayName;
		this.herbName = herbName;
		this.herbGrowStart = herbGrowStart;
		this.grimyHerbId = grimyHerbId;
		this.cleanHerbId = cleanHerbId;
		this.herbSeedId = herbSeedId;
		this.mixPrimaryId = mixPrimaryId;
		this.potion4Id = potion4Id;
		this.potion3Id = potion3Id;
		this.mixCount = mixCount;
		this.mixSecondaryIds = mixSecondaryIds;
	}

	public boolean isMixItem(int itemId)
	{
		if (itemId == mixPrimaryId)
		{
			return true;
		}
		for (int secondaryId : mixSecondaryIds)
		{
			if (itemId == secondaryId)
			{
				return true;
			}
		}
		return false;
	}

	public boolean hasMixStacks(ItemContainer inventory)
	{
		return hasAtLeast(inventory, mixCount);
	}

	public boolean canMix(ItemContainer inventory)
	{
		return hasAtLeast(inventory, 1);
	}

	public static boolean hasAnyMixStacks(ItemContainer inventory)
	{
		for (ProfitPotion potion : values())
		{
			if (potion.hasMixStacks(inventory))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean canMixAny(ItemContainer inventory)
	{
		for (ProfitPotion potion : values())
		{
			if (potion.canMix(inventory))
			{
				return true;
			}
		}
		return false;
	}

	public static boolean isMixItemForOpenMix(ItemContainer inventory, int itemId)
	{
		for (ProfitPotion potion : values())
		{
			if (potion.canMix(inventory) && potion.isMixItem(itemId))
			{
				return true;
			}
		}
		return false;
	}

	public static String mixingDisplayName(ItemContainer inventory)
	{
		ProfitPotion stacked = null;
		ProfitPotion mixing = null;
		for (ProfitPotion potion : values())
		{
			if (potion.hasMixStacks(inventory))
			{
				stacked = potion;
				break;
			}
			if (mixing == null && potion.canMix(inventory))
			{
				mixing = potion;
			}
		}
		ProfitPotion chosen = stacked != null ? stacked : mixing;
		return chosen == null ? "potion" : chosen.getDisplayName();
	}

	private boolean hasAtLeast(ItemContainer inventory, int count)
	{
		if (PrayerPotionItems.count(inventory, mixPrimaryId) < count)
		{
			return false;
		}
		for (int secondaryId : mixSecondaryIds)
		{
			if (PrayerPotionItems.count(inventory, secondaryId) < count)
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

