@Singleton
public class AchievementTracker
{
	private static final String KEY = "achievementCompletions";
	private static final String FISTS_PLANTED = "i managed to plant a seed with my fists";
	private static final int QUEST_READY_TICKS = 8;
	private static final Set<Integer> DIARY_VARBITS = ImmutableSet.of(
		VarbitID.FARMING_BLOCKWEEDS,
		VarbitID.BRUT_FARMING_PLANTING,
		VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
		VarbitID.KANDARIN_DIARY_HARD_COMPLETE,
		VarbitID.KANDARIN_DIARY_ELITE_COMPLETE,
		VarbitID.KOUREND_DIARY_EASY_COMPLETE,
		VarbitID.KOUREND_DIARY_HARD_COMPLETE,
		VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE,
		VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE
	);

	private static final Quest[] QUESTS = {
		Quest.FAIRYTALE_I__GROWING_PAINS,
		Quest.MY_ARMS_BIG_ADVENTURE,
		Quest.MAKING_FRIENDS_WITH_MY_ARM,
		Quest.SONG_OF_THE_ELVES
	};

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final Set<String> completed = new HashSet<>();
	private final Map<Quest, Boolean> questFinished = new EnumMap<>(Quest.class);
	private boolean journalFistsPlanting;
	private int questReadyTicks;

	@Inject
	private AchievementTracker(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	public void load()
	{
		completed.clear();
		journalFistsPlanting = false;
		String json = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		String[] ids = gson.fromJson(json, String[].class);
		if (ids != null)
		{
			for (String id : ids)
			{
				if (id != null && !id.isEmpty())
				{
					completed.add(id);
				}
			}
		}
	}

	public void resetLive()
	{
		questReadyTicks = 0;
		questFinished.clear();
	}

	public void tick()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			resetLive();
			return;
		}
		if (questReadyTicks < QUEST_READY_TICKS)
		{
			questReadyTicks++;
			if (questReadyTicks < QUEST_READY_TICKS)
			{
				return;
			}
		}
		for (Quest quest : QUESTS)
		{
			questFinished.put(quest, readQuestFinished(quest));
		}
		scanQuestJournal();
	}

	public boolean isTrackedVarbit(int varbitId)
	{
		return DIARY_VARBITS.contains(varbitId);
	}

	public List<FarmingAchievement> list()
