		achievements.add(quest(
			"my_arms_big_adventure",
			Quest.MY_ARMS_BIG_ADVENTURE,
			"My Arm's Big Adventure",
			"Disease-free Troll Stronghold herb patch"));
		achievements.add(quest(
			"making_friends_with_my_arm",
			Quest.MAKING_FRIENDS_WITH_MY_ARM,
			"Making Friends with My Arm",
			"Disease-free Weiss herb patch"));
		achievements.add(skill(
			"farming_45",
			Skill.FARMING,
			45,
			"45 Farming",
			"Farming Guild allotment patches"));
		achievements.add(skill(
			"farming_65",
			Skill.FARMING,
			65,
			"65 Farming",
			"Farming Guild herb patch"));
		achievements.add(skill(
			"farming_99",
			Skill.FARMING,
			99,
			"99 Farming",
			"Farming cape (5% chance to save herb harvest lives)"));
		achievements.add(diary(
			"kandarin_medium",
			VarbitID.KANDARIN_DIARY_MEDIUM_COMPLETE,
			"Kandarin Medium Diary",
			"5% chance to save herb lives at Catherby"));
		achievements.add(diary(
			"kandarin_hard",
			VarbitID.KANDARIN_DIARY_HARD_COMPLETE,
			"Kandarin Hard Diary",
			"10% chance to save herb lives at Catherby"));
		achievements.add(diary(
			"kandarin_elite",
			VarbitID.KANDARIN_DIARY_ELITE_COMPLETE,
			"Kandarin Elite Diary",
			"15% chance to save herb lives at Catherby"));
		achievements.add(diary(
			"kourend_easy",
			VarbitID.KOUREND_DIARY_EASY_COMPLETE,
			"Kourend & Kebos Easy Diary",
			"Disease-free Hosidius herb and allotment patches"));
		achievements.add(diary(
			"kourend_hard",
			VarbitID.KOUREND_DIARY_HARD_COMPLETE,
			"Kourend & Kebos Hard Diary",
			"5% chance to save herb lives at Hosidius and the Farming Guild"));
		achievements.add(diary(
			"lumbridge_hard",
			VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE,
			"Lumbridge Hard Diary",
			"Unlimited Explorer's ring teleports to Falador farm"));
		achievements.add(quest(
			"song_of_the_elves",
			Quest.SONG_OF_THE_ELVES,
