	public boolean harmonyUnlocked()
	{
		return unlocked("morytania_elite", diaryLive(VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE));
	}

	public boolean guildHerbUnlocked()
	{
		return unlocked("farming_65", skillLive(Skill.FARMING, 65));
	}

	public boolean guildAllotmentUnlocked()
	{
		return unlocked("farming_45", skillLive(Skill.FARMING, 45)) || guildHerbUnlocked();
	}

	public boolean weissUnlocked()
	{
		return unlocked("making_friends_with_my_arm", questLive(Quest.MAKING_FRIENDS_WITH_MY_ARM));
	}

	public boolean trollUnlocked()
	{
		return unlocked("my_arms_big_adventure", questLive(Quest.MY_ARMS_BIG_ADVENTURE));
	}

	public boolean prifUnlocked()
	{
		return unlocked("song_of_the_elves", questLive(Quest.SONG_OF_THE_ELVES));
	}

	public boolean fairyTaleIUnlocked()
	{
		return unlocked("fairytale_i", questLive(Quest.FAIRYTALE_I__GROWING_PAINS));
	}

	public boolean autoWeedUnlocked()
	{
		return unlocked("tithe_auto_weed", diaryLive(VarbitID.FARMING_BLOCKWEEDS));
	}

	public boolean fistsPlantingUnlocked()
	{
		return unlocked("barbarian_fists_planting", fistsPlantingLive());
	}

	public void scanQuestJournal()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Widget layer = client.getWidget(InterfaceID.Questjournal.TEXTLAYER);
		if (layer == null)
		{
			layer = client.getWidget(InterfaceID.Questjournal.CONTAINER);
		}
		if (layer == null)
		{
			return;
		}
		if (containsText(layer, FISTS_PLANTED))
		{
			journalFistsPlanting = true;
			fistsPlantingUnlocked();
		}
	}

	private boolean fistsPlantingLive()
	{
		return journalFistsPlanting || diaryLive(VarbitID.BRUT_FARMING_PLANTING);
	}

	private static boolean containsText(Widget widget, String needle)
	{
		if (widget == null)
		{
			return false;
		}
		String text = widget.getText();
		if (text != null && text.toLowerCase().contains(needle))
		{
			return true;
		}
		Widget[][] groups = {
			widget.getDynamicChildren(),
			widget.getStaticChildren(),
			widget.getNestedChildren()
		};
		for (Widget[] children : groups)
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				if (containsText(child, needle))
				{
					return true;
				}
			}
		}
		return false;
	}

	private FarmingAchievement quest(String id, Quest quest, String name, String benefit)
	{
		return stored(id, name, benefit, questLive(quest));
	}

	private FarmingAchievement skill(String id, Skill skill, int level, String name, String benefit)
	{
		return stored(id, name, benefit, skillLive(skill, level));
	}

	private FarmingAchievement diary(String id, int varbit, String name, String benefit)
	{
		return stored(id, name, benefit, diaryLive(varbit));
	}

	private boolean questLive(Quest quest)
	{
		return achievementsReady()
			&& Boolean.TRUE.equals(questFinished.get(quest));
	}

	private boolean skillLive(Skill skill, int level)
	{
		try
		{
			return client.getGameState() == GameState.LOGGED_IN
				&& client.getRealSkillLevel(skill) >= level;
		}
		catch (Exception ignored)
		{
			return false;
		}
	}

	private boolean diaryLive(int varbit)
	{
		try
		{
			return client.getGameState() == GameState.LOGGED_IN
				&& client.getVarbitValue(varbit) > 0;
		}
		catch (Exception ignored)
		{
			return false;
		}
	}

	private FarmingAchievement stored(String id, String name, String benefit, boolean live)
	{
		return new FarmingAchievement(name, benefit, unlocked(id, live));
	}

	private boolean unlocked(String id, boolean live)
	{
		if (live)
		{
			if (completed.add(id))
			{
				save();
			}
			return true;
		}
		if (achievementsReady() && completed.remove(id))
		{
			save();
		}
		return !achievementsReady() && completed.contains(id);
	}

	private boolean achievementsReady()
	{
		return client.getGameState() == GameState.LOGGED_IN
			&& client.getLocalPlayer() != null
			&& questReadyTicks >= QUEST_READY_TICKS;
	}

	private boolean readQuestFinished(Quest quest)
	{
		try
		{
			if (quest.getState(client) != QuestState.FINISHED)
			{
				return false;
			}
			if (quest == Quest.SONG_OF_THE_ELVES)
			{
				return client.getVarbitValue(VarbitID.SOTE) > 0;
			}
			return true;
		}
		catch (Exception ignored)
		{
			return false;
		}
	}

	private void save()
	{
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY,
			gson.toJson(completed.toArray(new String[0])));
	}
}

