package com.potionprofitpro.mode;

import com.potionprofitpro.PotionProfitProConfig;
import com.potionprofitpro.data.PrayerPotionItems;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;

@Singleton
public class FarmingModeTracker
{
	@Inject
	private Client client;

	@Inject
	private PotionProfitProConfig config;

	@Inject
	private AchievementTracker achievements;

	private boolean active;

	public void tick()
	{
		refreshActive();
	}

	public void refreshActive()
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			active = false;
			return;
		}
		active = hasRequiredTools();
	}

	public boolean isActive()
	{
		return active;
	}

	public boolean allowsTeleportHighlights()
	{
		return active;
	}

	private boolean hasRequiredTools()
	{
		if (!config.farmingOverlaysEnabled() || !client.isClientThread() || client.getLocalPlayer() == null)
		{
			return false;
		}

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			return false;
		}

		if (!PrayerPotionItems.contains(inventory, PrayerPotionItems.SPADE))
		{
			return false;
		}
		if (!hasRequiredSecateurs())
		{
			return false;
		}
		if (!achievements.autoWeedUnlocked() && !PrayerPotionItems.contains(inventory, PrayerPotionItems.RAKE))
		{
			return false;
		}
		if (!achievements.fistsPlantingUnlocked()
			&& !PrayerPotionItems.contains(inventory, PrayerPotionItems.DIBBER))
		{
			return false;
		}

		return true;
	}

	private boolean hasRequiredSecateurs()
	{
		if (requiresMagicSecateurs())
		{
			return hasMagicSecateurs();
		}
		return hasTool(PrayerPotionItems.SECATEURS) || hasMagicSecateurs();
	}

	public boolean requiresMagicSecateurs()
	{
		return achievements.fairyTaleIUnlocked();
	}

	public boolean hasMagicSecateurs()
	{
		return hasTool(PrayerPotionItems.MAGIC_SECATEURS_IDS);
	}

	public boolean requiresFarmingCape()
	{
		return client.getRealSkillLevel(Skill.FARMING) >= 99;
	}

	public boolean hasFarmingCapeEquipped()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), PrayerPotionItems.FARMING_CAPE_IDS);
	}

	public boolean hasBountyEquipped()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), PrayerPotionItems.AMULET_OF_BOUNTY);
	}

	public boolean hasAllotmentSeeds()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.INV),
			PrayerPotionItems.SNAPE_GRASS_SEED, PrayerPotionItems.WATERMELON_SEED);
	}

	public int compostBuckets()
	{
		return PrayerPotionItems.count(client.getItemContainer(InventoryID.INV), config.compostType().getItemId());
	}

	public boolean hasBottomlessBucket()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		return PrayerPotionItems.contains(inventory, PrayerPotionItems.BOTTOMLESS_IDS)
			|| PrayerPotionItems.contains(worn, PrayerPotionItems.BOTTOMLESS_IDS);
	}

	public boolean hasFilledBottomless()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.INV), PrayerPotionItems.BOTTOMLESS_FILLED)
			|| PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), PrayerPotionItems.BOTTOMLESS_FILLED);
	}

	public boolean herbGearMissing()
	{
		boolean missingSecateurs = requiresMagicSecateurs() && !hasMagicSecateurs();
		boolean missingCape = requiresFarmingCape() && !hasFarmingCapeEquipped();
		return missingSecateurs || missingCape;
	}

	private boolean hasTool(int itemId)
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.INV), itemId)
			|| PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), itemId);
	}

	private boolean hasTool(Set<Integer> itemIds)
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.INV), itemIds)
			|| PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), itemIds);
	}
