package com.potionprofitpro.mode;

import com.potionprofitpro.PotionProfitProConfig;
import com.potionprofitpro.charges.ChargeTracker;
import com.potionprofitpro.data.PrayerPotionItems;
import com.potionprofitpro.data.ProfitPotion;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

@Singleton
public class MixingModeTracker
{
	@Inject
	private Client client;

	@Inject
	private PotionProfitProConfig config;

	@Inject
	private ChargeTracker charges;

	private boolean mixingRun;
	private boolean missingGear;

	public void tick()
	{
		if (!client.isClientThread())
		{
			return;
		}

		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory == null)
		{
			mixingRun = false;
			missingGear = false;
			return;
		}

		if (ProfitPotion.hasAnyMixStacks(inventory))
		{
			mixingRun = true;
		}
		else if (!ProfitPotion.canMixAny(inventory))
		{
			mixingRun = false;
		}
		missingGear = mixingRun && computeMissingGear();
	}

	public boolean isActive()
	{
		return mixingRun;
	}

	public void reset()
	{
		mixingRun = false;
		missingGear = false;
	}

	public boolean hasGogglesEquipped()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), PrayerPotionItems.GOGGLES_IDS);
	}

	public boolean hasAlchemistsAmuletEquipped()
	{
		return PrayerPotionItems.contains(client.getItemContainer(InventoryID.WORN), PrayerPotionItems.ALCHEMISTS_AMULET_IDS);
	}

	public boolean missingCheckedGear()
	{
		return missingGear;
	}

	public boolean hasUsableAlchemistsAmulet()
	{
		return hasAlchemistsAmuletEquipped() && charges.getAlchemistCharges() != 0;
	}

	public boolean watchingGear()
	{
		return config.usePrescriptionGoggles() || config.useAlchemistsAmulet();
	}

	public boolean isMixItem(int itemId)
	{
		return ProfitPotion.isMixItemForOpenMix(client.getItemContainer(InventoryID.INV), itemId);
	}

	public String mixingDisplayName()
	{
		return ProfitPotion.mixingDisplayName(client.getItemContainer(InventoryID.INV));
	}

	private boolean computeMissingGear()
	{
		boolean missingGoggles = config.usePrescriptionGoggles() && !hasGogglesEquipped();
		boolean missingAmulet = config.useAlchemistsAmulet() && !hasUsableAlchemistsAmulet();
		return missingGoggles || missingAmulet;
	}
}

