import net.runelite.client.util.ColorUtil;

public class MixingItemOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final PotionProfitProConfig config;
	private final MixingModeTracker mixingMode;

	@Inject
	private MixingItemOverlay(Client client, PotionProfitProConfig config, MixingModeTracker mixingMode)
	{
		this.client = client;
		this.config = config;
		this.mixingMode = mixingMode;
		showOnInventory();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!mixingMode.isActive() || !mixingMode.watchingGear() || !mixingMode.missingCheckedGear())
		{
			return;
		}

		if (!mixingMode.isMixItem(itemId))
		{
			return;
		}

		Color color = config.badColor();
		if (client.getGameCycle() % 40 < 20)
		{
			color = ColorUtil.colorWithAlpha(color, 80);
		}
		else
		{
			color = ColorUtil.colorWithAlpha(color, 160);
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.setColor(color);
		graphics.fill(bounds);
		graphics.setColor(config.badColor());
		graphics.draw(bounds);
	}
}

