package com.potionprofitpro.overlay;

import com.google.gson.Gson;
import com.potionprofitpro.PotionProfitProConfig;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

@Singleton
public class PatchFertilityTracker
{
	private static final String KEY = "patchFertility";
	private static final Pattern TREATED = Pattern.compile(
		"(?i)(?:you treat the .+ with|(?:the soil has been treated|has been treated) with|(?:already been (?:treated|fertilised) with)) (?:ultra|super)?compost");
	private static final Pattern UNTREATED = Pattern.compile(
		"(?i)the soil has not been treated");
	private static final Pattern PLANTED = Pattern.compile(
		"(?i)you plant (?:a |an )?.+ seeds?");

	private final Set<Long> composted = new HashSet<>();
	private final Set<Long> unfertilized = new HashSet<>();
	private final Set<Long> plantedThisTick = new HashSet<>();
	private final Map<Long, Boolean> lastPlanted = new HashMap<>();
	private WorldPoint pendingLocation;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private PatchFertilityTracker()
	{
	}

	public void rememberAction(WorldPoint location)
	{
		pendingLocation = location;
	}

	public WorldPoint takePendingOr(WorldPoint fallback)
	{
		WorldPoint location = pendingLocation != null ? pendingLocation : fallback;
		pendingLocation = null;
		return location;
	}

	public boolean isUnfertilized(long patchKey)
	{
		return unfertilized.contains(patchKey);
	}

	public boolean isComposted(long patchKey)
	{
		return composted.contains(patchKey);
	}

	public void observe(long patchKey, boolean planted)
	{
		Boolean previous = lastPlanted.put(patchKey, planted);
		boolean changed = false;
		if (previous != null && previous && !planted)
		{
			changed |= composted.remove(patchKey);
			if (!plantedThisTick.contains(patchKey))
			{
				changed |= unfertilized.remove(patchKey);
			}
		}
		plantedThisTick.remove(patchKey);
		if (changed)
		{
			save();
		}
	}

	public boolean onGameMessage(String message, long patchKey)
	{
		if (patchKey < 0)
		{
			return false;
		}
		if (TREATED.matcher(message).find())
		{
			composted.add(patchKey);
			unfertilized.remove(patchKey);
			save();
			return true;
		}
		if (UNTREATED.matcher(message).find())
		{
			composted.remove(patchKey);
			unfertilized.add(patchKey);
			save();
			return true;
		}
		if (PLANTED.matcher(message).find())
		{
			markPlanted(patchKey);
			return true;
		}
		return false;
	}

	public void load()
	{
		composted.clear();
		unfertilized.clear();
		plantedThisTick.clear();
		lastPlanted.clear();
		pendingLocation = null;

		String json = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		StoredState state = gson.fromJson(json, StoredState.class);
		if (state == null)
		{
			return;
		}
		if (state.composted != null)
		{
			composted.addAll(state.composted);
		}
		if (state.unfertilized != null)
		{
			unfertilized.addAll(state.unfertilized);
		}
		if (state.lastPlanted != null)
		{
			for (Map.Entry<String, Boolean> entry : state.lastPlanted.entrySet())
			{
				try
				{
					lastPlanted.put(Long.parseLong(entry.getKey()), Boolean.TRUE.equals(entry.getValue()));
				}
				catch (NumberFormatException ignored)
				{
				}
			}
		}
	}

	private void markPlanted(long patchKey)
	{
		Boolean planted = lastPlanted.get(patchKey);
		if (Boolean.FALSE.equals(planted) && composted.contains(patchKey))
		{
			return;
		}
		composted.remove(patchKey);
		unfertilized.add(patchKey);
		plantedThisTick.add(patchKey);
		save();
	}

	private void save()
	{
		StoredState state = new StoredState();
		state.composted = new HashSet<>(composted);
		state.unfertilized = new HashSet<>(unfertilized);
		state.lastPlanted = new HashMap<>();
		for (Map.Entry<Long, Boolean> entry : lastPlanted.entrySet())
		{
			state.lastPlanted.put(Long.toString(entry.getKey()), entry.getValue());
		}
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY, gson.toJson(state));
	}

	private static final class StoredState
	{
		private Set<Long> composted;
		private Set<Long> unfertilized;
		private Map<String, Boolean> lastPlanted;
	}
}

