public class PatchHighlightOverlay extends Overlay
{
	public enum PatchType
	{
		HERB,
		ALLOTMENT
	}

	private static final String[] HERB_CROPS = {
		"guam", "marrentill", "tarromin", "harralander", "goutweed", "ranarr",
		"toadflax", "irit", "avantoe", "kwuarm", "snapdragon", "huasca",
		"cadantine", "lantadyme", "dwarf weed", "torstol"
	};

	private static final String[] ALLOTMENT_CROPS = {
		"potato", "onion", "cabbage", "tomato", "sweetcorn", "strawberry",
		"watermelon", "snape grass", "kale"
	};

	private final Client client;
	private final PotionProfitProConfig config;
	private final FarmingModeTracker farmingMode;
	private final ChargeTracker charges;
	private final PatchFertilityTracker fertility;
	private final Map<Long, TrackedPatch> patches = new HashMap<>();

	@Inject
	private PatchHighlightOverlay(Client client, PotionProfitProConfig config, FarmingModeTracker farmingMode,
		ChargeTracker charges, PatchFertilityTracker fertility)
	{
		this.client = client;
		this.config = config;
		this.farmingMode = farmingMode;
		this.charges = charges;
		this.fertility = fertility;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_MED);
	}

	public void add(GameObject object)
	{
		if (object == null)
		{
			return;
		}

		PatchType type = typeOf(object);
		if (type != null)
		{
			long patchKey = key(object);
			boolean planted = isPlanted(object, type);
			fertility.observe(patchKey, planted);
			patches.put(patchKey, new TrackedPatch(object, type, planted));
		}
	}

	public void remove(GameObject object)
	{
		patches.remove(key(object));
	}

	public void clear()
	{
		patches.clear();
	}

	public boolean isEmpty()
	{
		return patches.isEmpty();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!farmingMode.isActive())
		{
			return null;
		}

		Color herbColor = farmingMode.herbGearMissing() ? config.badColor() : config.goodColor();
		Color allotmentColor = allotmentColor();
		int plane = client.getPlane();

		for (TrackedPatch patch : patches.values())
		{
			GameObject object = patch.object;
			if (!onCurrentPlane(object, plane))
			{
				continue;
			}

			patch.planted = isPlanted(object, patch.type);
			fertility.observe(key(object), patch.planted);
			if (patch.type == PatchType.ALLOTMENT && !farmingMode.hasAllotmentSeeds())
			{
				continue;
			}

			LocalPoint localPoint = object.getLocalLocation();
			if (localPoint == null)
			{
				continue;
			}

			Color color = patch.type == PatchType.HERB ? herbColor : allotmentColor;
			long patchKey = key(object);
			if (watchingCompost() && (fertility.isUnfertilized(patchKey)
				|| (patch.planted && !fertility.isComposted(patchKey))))
			{
				color = config.unfertilizedColor();
			}
			if (isHarvestable(object))
			{
				color = config.readyToHarvestColor();
			}
			if (color == null)
			{
				continue;
			}
			if (!patch.planted && color.equals(config.goodColor()) && client.getGameCycle() % 40 < 20)
			{
				continue;
			}

			Shape shape = object.getClickbox();
			if (shape == null)
			{
				shape = object.getConvexHull();
			}
			if (shape == null)
			{
				shape = Perspective.getCanvasTileAreaPoly(client, localPoint, Math.max(object.sizeX(), object.sizeY()));
			}
			if (shape == null)
			{
				shape = Perspective.getCanvasTilePoly(client, localPoint);
			}
			if (shape != null)
			{
				OverlayUtil.renderPolygon(graphics, shape, color);
			}
		}

		return null;
	}

	private Color allotmentColor()
	{
		if (!config.useAmuletOfBounty())
		{
			return config.goodColor();
		}
		if (!farmingMode.hasBountyEquipped())
		{
			return config.badColor();
		}
		if (charges.getBountyCharges() == 1)
		{
			return config.warningColor();
		}
		return config.goodColor();
	}

	private boolean watchingCompost()
	{
		return config.useBottomlessBucket() || config.useCompostBuckets();
	}

	public long nearestPatchKey(WorldPoint location)
	{
		if (location == null || patches.isEmpty())
		{
			return -1;
		}

		long bestKey = -1;
		int bestDistance = Integer.MAX_VALUE;
		for (TrackedPatch patch : patches.values())
		{
			WorldPoint patchLocation = patch.object.getWorldLocation();
			if (patchLocation == null || patchLocation.getPlane() != location.getPlane())
			{
				continue;
			}
			int distance = patchLocation.distanceTo(location);
			if (distance < bestDistance)
			{
				bestDistance = distance;
				bestKey = key(patch.object);
			}
		}
		return bestDistance <= 6 ? bestKey : -1;
	}

	public List<WorldPoint> harvestableHerbLocations()
	{
		List<WorldPoint> locations = new ArrayList<>();
		int playerRegion = playerRegionId();
		for (TrackedPatch patch : patches.values())
		{
			if (patch.type != PatchType.HERB || !isHarvestable(patch.object))
			{
				continue;
			}
			WorldPoint loc = patch.object.getWorldLocation();
			if (loc != null && loc.getRegionID() == playerRegion)
			{
				locations.add(loc);
			}
		}
		return locations;
	}

	public List<WorldPoint> harvestableAllotmentLocations()
	{
		List<WorldPoint> locations = new ArrayList<>();
		int playerRegion = playerRegionId();
		for (TrackedPatch patch : patches.values())
		{
			if (patch.type != PatchType.ALLOTMENT || !isHarvestable(patch.object))
			{
				continue;
			}
			WorldPoint loc = patch.object.getWorldLocation();
			if (loc != null && loc.getRegionID() == playerRegion)
			{
				locations.add(loc);
			}
		}
		return locations;
	}

	public AllotmentPatch nearestAllotment(WorldPoint location)
	{
		if (location == null || patches.isEmpty())
		{
			return null;
		}

		AllotmentPatch best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (TrackedPatch patch : patches.values())
		{
			if (patch.type != PatchType.ALLOTMENT)
			{
				continue;
			}
			WorldPoint patchLocation = patch.object.getWorldLocation();
			if (patchLocation == null || patchLocation.getPlane() != location.getPlane())
			{
				continue;
			}
			int distance = patchLocation.distanceTo(location);
			if (distance >= bestDistance || distance > 8)
			{
				continue;
			}
			AllotmentPatch match = matchAllotment(patch.object);
			if (match == null)
			{
				continue;
			}
			best = match;
			bestDistance = distance;
		}
		return best;
	}

	public boolean syncVisibleAllotments(AllotmentPatchTracker tracker)
	{
		if (tracker == null || patches.isEmpty())
		{
			return false;
		}

		int playerRegion = playerRegionId();
		if (playerRegion < 0)
		{
			return false;
		}

		Map<AllotmentPatch.TeleportGroup, List<GameObject>> byGroup = new EnumMap<>(AllotmentPatch.TeleportGroup.class);
		for (TrackedPatch patch : patches.values())
		{
			if (patch.type != PatchType.ALLOTMENT || patch.object == null)
			{
				continue;
			}
			WorldPoint loc = patch.object.getWorldLocation();
			if (loc == null || loc.getRegionID() != playerRegion)
			{
				continue;
			}
			AllotmentPatch.TeleportGroup group = teleportGroupAt(loc);
			if (group == null)
			{
				continue;
			}
			byGroup.computeIfAbsent(group, key -> new ArrayList<>()).add(patch.object);
		}

		boolean changed = false;
		for (Map.Entry<AllotmentPatch.TeleportGroup, List<GameObject>> entry : byGroup.entrySet())
		{
			List<AllotmentPatch> named = patchesInGroup(entry.getKey());
			List<GameObject> objects = new ArrayList<>(entry.getValue());
			objects.sort(Comparator
				.comparingInt((GameObject object) -> yOf(object))
				.reversed()
				.thenComparingInt(PatchHighlightOverlay::xOf));
			if (named.size() == 2 && objects.size() >= 2)
			{
				changed |= tracker.observeVisible(named.get(0), liveValue(objects.get(0)), objectName(objects.get(0)),
					playerRegion);
				changed |= tracker.observeVisible(named.get(named.size() - 1), liveValue(objects.get(objects.size() - 1)),
					objectName(objects.get(objects.size() - 1)), playerRegion);
				continue;
			}
			for (GameObject object : objects)
			{
				AllotmentPatch match = matchAllotment(object);
				if (match != null)
				{
					changed |= tracker.observeVisible(match, liveValue(object), objectName(object), playerRegion);
				}
			}
		}
		return changed;
	}

	private AllotmentPatch matchAllotment(GameObject object)
	{
		WorldPoint loc = object.getWorldLocation();
		if (loc == null)
		{
			return null;
		}
		AllotmentPatch byVarbit = AllotmentPatch.forRegionAndVarbit(loc.getRegionID(), varbitOf(object));
		if (byVarbit != null)
		{
			return byVarbit;
		}
		AllotmentPatch.TeleportGroup group = teleportGroupAt(loc);
		if (group == null)
		{
			return null;
		}
		List<AllotmentPatch> named = patchesInGroup(group);
		if (named.size() == 1)
		{
			return named.get(0);
		}
		return null;
	}

	private static List<AllotmentPatch> patchesInGroup(AllotmentPatch.TeleportGroup group)
	{
		List<AllotmentPatch> named = new ArrayList<>();
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (patch.getTeleportGroup() == group)
			{
				named.add(patch);
			}
		}
		named.sort(Comparator.comparingInt(PatchHighlightOverlay::northRank));
		return named;
	}

	private static int northRank(AllotmentPatch patch)
	{
		String location = patch.getLocation();
		if (location.contains("NW") || location.contains("NE") || location.contains("(N)"))
		{
			return 0;
		}
		if (location.contains("SW") || location.contains("SE") || location.contains("(S)"))
		{
			return 2;
		}
		return 1;
	}

	private static AllotmentPatch.TeleportGroup teleportGroupAt(WorldPoint location)
	{
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (patch.containsRegion(location.getRegionID()) && patch.inBounds(location))
			{
				return patch.getTeleportGroup();
			}
		}
		return null;
	}

	private int liveValue(GameObject object)
	{
		int varbit = varbitOf(object);
		return varbit > 0 ? client.getVarbitValue(varbit) : -1;
	}

	private String objectName(GameObject object)
	{
		ObjectComposition visible = visibleComposition(object);
		return visible == null ? null : visible.getName();
	}

	private static int yOf(GameObject object)
	{
		WorldPoint loc = object.getWorldLocation();
		return loc == null ? Integer.MIN_VALUE : loc.getY();
	}

	private static int xOf(GameObject object)
	{
		WorldPoint loc = object.getWorldLocation();
		return loc == null ? Integer.MIN_VALUE : loc.getX();
	}

	private int varbitOf(GameObject object)
	{
		ObjectComposition definition = client.getObjectDefinition(object.getId());
		if (definition == null)
		{
			return -1;
		}
		int varbit = definition.getVarbitId();
		if (varbit > 0)
		{
			return varbit;
		}
		ObjectComposition visible = impostorOr(definition);
		return visible == null ? -1 : visible.getVarbitId();
	}

	private boolean isHarvestable(GameObject object)
	{
		ObjectComposition visible = visibleComposition(object);
		if (visible == null)
		{
			return false;
		}
		// Herbs use Pick; allotments use Harvest. Both mean the crop is collectable.
		return hasAction(visible, "harvest", "pick");
	}

	private boolean isPlanted(GameObject object, PatchType type)
	{
		ObjectComposition visible = visibleComposition(object);
		if (visible == null)
		{
			return false;
		}
		if (hasAction(visible, "pick", "harvest", "cure", "clear"))
		{
			return true;
		}

		String name = normalize(visible.getName());
		if (name.contains("herb patch") || name.equals("allotment"))
		{
			return false;
		}
		if (name.contains("herbs") || name.contains("diseased") || name.contains("dead"))
		{
			return true;
		}
		return type == PatchType.HERB
			? matchesCrop(name, HERB_CROPS)
			: matchesCrop(name, ALLOTMENT_CROPS);
	}

	private PatchType typeOf(GameObject object)
	{
		ObjectComposition base = client.getObjectDefinition(object.getId());
		if (base == null)
		{
			return null;
		}

		// Farming patches keep the base name "Herb patch" / "Allotment" even when the
		// visible impostor is a grown crop. Classify from that first so harvest-ready
		// snape grass still counts, and Hosidius cabbage fields do not.
		PatchType fromBase = typeFromPatchName(normalize(base.getName()));
		if (fromBase != null)
		{
			return fromBase;
		}

		ObjectComposition visible = impostorOr(base);
		String visibleName = normalize(visible.getName());
		if (isSceneryPatch(visibleName) || isOtherFarmingPatch(visibleName) || isSceneryPatch(normalize(base.getName())))
		{
			return null;
		}

		PatchType fromVisible = typeFromPatchName(visibleName);
		if (fromVisible != null)
		{
			return fromVisible;
		}

		if (matchesCrop(visibleName, HERB_CROPS) && hasAction(visible, "rake", "pick", "clear", "cure", "harvest", "guide"))
		{
			return PatchType.HERB;
		}

		// Allotments use Harvest, not Pick. Pick-only "Cabbage" / "Cabbage patch"
		// objects around Hosidius are scenery, not player patches.
		if (matchesCrop(visibleName, ALLOTMENT_CROPS) && hasAction(visible, "rake", "harvest", "clear", "cure", "guide"))
		{
			return PatchType.ALLOTMENT;
		}

		return null;
	}

	private ObjectComposition visibleComposition(GameObject object)
	{
		ObjectComposition definition = client.getObjectDefinition(object.getId());
		if (definition == null)
		{
			return null;
		}
		return impostorOr(definition);
	}

	private ObjectComposition impostorOr(ObjectComposition definition)
	{
		if (definition.getImpostorIds() == null)
		{
			return definition;
		}

		try
		{
			ObjectComposition impostor = definition.getImpostor();
			if (impostor != null)
			{
				String name = impostor.getName();
				if (name != null && !"null".equals(name))
				{
					return impostor;
				}
			}
		}
		catch (Exception ignored)
		{
		}
		return definition;
	}

	private static PatchType typeFromPatchName(String lower)
	{
		if (lower.contains("herb patch") || lower.equals("herbs") || lower.startsWith("herbs")
			|| lower.contains("diseased herb") || lower.contains("dead herb"))
		{
			return PatchType.HERB;
		}
		if (lower.contains("allotment"))
		{
			return PatchType.ALLOTMENT;
		}
		return null;
	}

	private static boolean isSceneryPatch(String lower)
	{
		return lower.contains("patch") && !lower.contains("herb patch") && !lower.contains("allotment");
	}

	private static boolean isOtherFarmingPatch(String lower)
	{
		return lower.contains("flower") || lower.contains("hops") || lower.contains("bush")
			|| lower.contains("tree") || lower.contains("cactus") || lower.contains("compost")
			|| lower.contains("spirit") || lower.contains("calquat") || lower.contains("celastrus")
			|| lower.contains("redwood") || lower.contains("hespori") || lower.contains("anima")
			|| lower.contains("belladonna") || lower.contains("mushroom") || lower.contains("seaweed")
			|| lower.contains("grape") || lower.contains("hardwood");
	}

	private static boolean matchesCrop(String lower, String[] crops)
	{
		for (String crop : crops)
		{
			if (lower.equals(crop) || lower.equals(crop + "s") || lower.equals(crop + "es")
				|| lower.startsWith(crop + " ") || lower.startsWith(crop + "s ")
				|| lower.equals("diseased " + crop) || lower.equals("dead " + crop)
				|| lower.startsWith("diseased " + crop) || lower.startsWith("dead " + crop))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean hasAction(ObjectComposition definition, String... wanted)
	{
		String[] actions = definition.getActions();
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if (action == null)
			{
				continue;
			}
			String value = action.toLowerCase(Locale.ROOT);
			for (String match : wanted)
			{
				if (value.equals(match) || value.startsWith(match + " "))
				{
					return true;
				}
			}
		}
		return false;
	}

	private static String normalize(String name)
	{
		if (name == null || "null".equals(name))
		{
			return "";
		}
		return name.toLowerCase(Locale.ROOT);
	}

	private static boolean onCurrentPlane(GameObject object, int plane)
	{
		WorldPoint worldPoint = object.getWorldLocation();
		if (worldPoint != null)
		{
			return worldPoint.getPlane() == plane;
		}
		return object.getPlane() == plane;
	}

	private int playerRegionId()
	{
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return -1;
		}
		return player.getWorldLocation().getRegionID();
	}

	private static long key(GameObject object)
	{
		WorldPoint worldPoint = object.getWorldLocation();
		if (worldPoint == null)
		{
			return object.getHash();
		}
		return ((long) worldPoint.getPlane() << 42) ^ ((long) worldPoint.getX() << 16) ^ worldPoint.getY();
	}

	private static final class TrackedPatch
	{
		private final GameObject object;
		private final PatchType type;

		private boolean planted;

		private TrackedPatch(GameObject object, PatchType type, boolean planted)
		{
			this.object = object;
			this.type = type;
			this.planted = planted;
		}
	}
}

