import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ImageUtil;

public class TeleportHighlightOverlay extends WidgetItemOverlay
{
	private final Client client;
	private final PotionProfitProConfig config;
	private final FarmingModeTracker farmingMode;
	private final HerbTeleportTracker teleports;
	private final ItemManager itemManager;
	private final SpriteManager spriteManager;
	private final Map<Integer, BufferedImage> spriteOutlines = new HashMap<>();
	private int cachedOutlineRgb = Integer.MIN_VALUE;

	@Inject
	private TeleportHighlightOverlay(Client client, PotionProfitProConfig config, FarmingModeTracker farmingMode,
		HerbTeleportTracker teleports, ItemManager itemManager, SpriteManager spriteManager)
	{
		this.client = client;
		this.config = config;
		this.farmingMode = farmingMode;
		this.teleports = teleports;
		this.itemManager = itemManager;
		this.spriteManager = spriteManager;
		showOnInventory();
		showOnEquipment();
		showOnInterfaces(InterfaceID.EQUIPMENT, InterfaceID.EQUIPMENT_SIDE, InterfaceID.WORNITEMS);
		drawAfterLayer(InterfaceID.MagicSpellbook.SPELLLAYER);
		drawAfterLayer(InterfaceID.Wornitems.UNIVERSE);
		drawAfterLayer(InterfaceID.Equipment.CONTENTS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Dimension dim = super.render(graphics);
		if (!highlightsEnabled())
		{
			return dim;
		}
		highlightWidgetTree(graphics, client.getWidget(InterfaceID.Wornitems.UNIVERSE));
		highlightWidgetTree(graphics, client.getWidget(InterfaceID.Equipment.CONTENTS));
		highlightWidgetTree(graphics, client.getWidget(InterfaceID.EquipmentSide.ITEMS));
		highlightWidgetTree(graphics, client.getWidget(InterfaceID.MagicSpellbook.SPELLLAYER));
		return dim;
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!highlightsEnabled() || !teleports.isReadyTeleportItem(itemId))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null)
		{
			return;
		}
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), outlineColor());
		if (outline != null)
		{
			graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
		}
	}

	private void highlightWidgetTree(Graphics2D graphics, Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		int itemId = widget.getItemId();
		if (itemId > 0 && teleports.isReadyTeleportItem(itemId))
		{
			drawCentered(graphics, itemManager.getItemOutline(itemId, Math.max(1, widget.getItemQuantity()),
				outlineColor()), widget.getBounds());
		}
		else
		{
			int spriteId = widget.getSpriteId();
			if (spriteId > 0 && (teleports.isReadyTeleportSprite(spriteId)
				|| teleports.isReadyTeleportSpell(widget.getId())))
			{
				drawCentered(graphics, spriteOutline(spriteId), widget.getBounds());
			}
		}
		Widget[][] groups = {
			widget.getDynamicChildren(),
			widget.getStaticChildren(),
			widget.getNestedChildren()
		};
		for (Widget[] children : groups)
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				highlightWidgetTree(graphics, child);
			}
		}
	}

	private BufferedImage spriteOutline(int spriteId)
	{
		Color color = outlineColor();
		if (color.getRGB() != cachedOutlineRgb)
		{
			spriteOutlines.clear();
			cachedOutlineRgb = color.getRGB();
		}
		BufferedImage cached = spriteOutlines.get(spriteId);
		if (cached != null)
		{
			return cached;
		}
		BufferedImage sprite = spriteManager.getSprite(spriteId, 0);
		if (sprite == null)
		{
			return null;
		}
		BufferedImage outline = silhouetteOutline(sprite, color);
		spriteOutlines.put(spriteId, outline);
		return outline;
	}

	private Color outlineColor()
	{
		return config.readyToHarvestColor();
	}

	private boolean highlightsEnabled()
	{
		return config.highlightTeleports() && farmingMode.allowsTeleportHighlights();
	}

	private static BufferedImage silhouetteOutline(BufferedImage image, Color color)
	{
		BufferedImage outlined = ImageUtil.outlineImage(image, color);
		for (int x = 0; x < image.getWidth(); x++)
		{
			for (int y = 0; y < image.getHeight(); y++)
			{
				if ((image.getRGB(x, y) >>> 24) != 0)
				{
					outlined.setRGB(x, y, 0);
				}
			}
		}
		return outlined;
	}

	private static void drawCentered(Graphics2D graphics, BufferedImage outline, Rectangle bounds)
	{
		if (outline == null || bounds == null)
		{
			return;
		}
		int x = bounds.x + (bounds.width - outline.getWidth()) / 2;
		int y = bounds.y + (bounds.height - outline.getHeight()) / 2;
		graphics.drawImage(outline, x, y, null);
	}
}

