@Singleton
public class AllotmentPatchTracker
{
	private static final String KEY = "allotmentPatchState";
	private static final int HARVEST_LIVES = 2;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("h:mm a", Locale.US);

	private final Map<AllotmentPatch, Integer> values = new EnumMap<>(AllotmentPatch.class);
	private final Map<AllotmentPatch, String> compost = new EnumMap<>(AllotmentPatch.class);
	private final Map<AllotmentPatch, Long> observedAt = new EnumMap<>(AllotmentPatch.class);
	private Integer farmTickOffset;
	private Integer farmTickOffsetPrecision;
	private boolean harvestCycleReady;
	private Long cycleCompleteEpoch;
	private int lockedRegion = -1;
	private int freezeTicks;
	private WorldPoint lastPoint;
	private final Map<AllotmentPatch, Integer> resetConfirm = new EnumMap<>(AllotmentPatch.class);
	private final Map<AllotmentPatch, String> visibleCrop = new EnumMap<>(AllotmentPatch.class);

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	public void load()
	{
		values.clear();
		compost.clear();
		observedAt.clear();
		resetConfirm.clear();
		visibleCrop.clear();
		String json = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		StoredState state = gson.fromJson(json, StoredState.class);
		if (state == null || state.values == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> entry : state.values.entrySet())
		{
			try
			{
				if (AllotmentCrops.isUnknown(entry.getValue()))
				{
					continue;
				}
				values.put(AllotmentPatch.valueOf(entry.getKey()), entry.getValue());
			}
			catch (IllegalArgumentException ignored)
			{
			}
		}
		if (state.compost != null)
		{
			for (Map.Entry<String, String> entry : state.compost.entrySet())
			{
				try
				{
					compost.put(AllotmentPatch.valueOf(entry.getKey()), entry.getValue());
				}
				catch (IllegalArgumentException ignored)
				{
				}
			}
		}
		if (state.observedAt != null)
		{
			for (Map.Entry<String, Long> entry : state.observedAt.entrySet())
			{
				try
				{
					AllotmentPatch patch = AllotmentPatch.valueOf(entry.getKey());
					if (values.containsKey(patch) && entry.getValue() != null)
					{
						observedAt.put(patch, entry.getValue());
					}
				}
				catch (IllegalArgumentException ignored)
				{
				}
			}
		}
		farmTickOffset = state.farmTickOffset;
		farmTickOffsetPrecision = state.farmTickOffsetPrecision;
		harvestCycleReady = Boolean.TRUE.equals(state.harvestCycleReady)
			|| (state.cycleReadyEpoch != null && state.cycleReadyEpoch <= Instant.now().getEpochSecond());
		cycleCompleteEpoch = state.cycleCompleteEpoch != null ? state.cycleCompleteEpoch : state.cycleReadyEpoch;
	}

	public void tick(Client client)
	{
		if (persistMaturePatches())
		{
			save();
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return;
		}

		if (client.isInInstancedRegion())
		{
			return;
		}
		WorldPoint location = player.getWorldLocation();
		int regionId = location.getRegionID();
		if (lastPoint != null && location.distanceTo(lastPoint) > 16)
		{
			freeze(4);
		}
		lastPoint = location;
		if (regionId != lockedRegion)
		{
			lockedRegion = regionId;
			freeze(4);
			return;
		}
		if (freezeTicks > 0)
		{
			freezeTicks--;
			return;
		}
		boolean changed = false;
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (!patch.inBounds(location))
			{
				continue;
			}
			if (applyObserved(patch, client.getVarbitValue(patch.getVarbit())))
			{
				changed = true;
			}
		}
		if (persistMaturePatches())
		{
			changed = true;
		}
		if (changed)
		{
			save();
		}
	}

	public void advancePredictions()
	{
		if (persistMaturePatches())
		{
			save();
		}
	}

	public void freeze(int ticks)
	{
		freezeTicks = Math.max(freezeTicks, ticks);
		resetConfirm.clear();
	}

	public boolean isAllotmentVarbit(int varbitId)
	{
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (patch.getVarbit() == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	public boolean applyVarbit(Client client, int varbitId)
	{
		if (client.getGameState() != GameState.LOGGED_IN || !isAllotmentVarbit(varbitId))
		{
			return false;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null || client.isInInstancedRegion())
		{
			return false;
		}
		WorldPoint location = player.getWorldLocation();
		int value = client.getVarbitValue(varbitId);
		boolean changed = false;
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (patch.getVarbit() != varbitId || !patch.inBounds(location))
			{
				continue;
			}
			Integer previous = values.get(patch);
			if (!isLiveVarbitUpdate(previous, value) || isPrematureReady(patch, previous, value))
			{
				freeze(8);
				continue;
			}
			if (freezeTicks > 0 && !isHarvestLifeDrop(previous, value) && !isHarvestFinish(previous, value))
			{
				continue;
			}
			if (applyObserved(patch, value))
			{
				changed = true;
			}
		}
		if (changed)
		{
			save();
		}
		return changed;
	}

	public void setCompost(AllotmentPatch patch, String compostName)
	{
		if (patch == null || compostName == null || compostName.isEmpty())
		{
			return;
		}
		if (compostName.equals(compost.get(patch)))
		{
			return;
		}
		compost.put(patch, compostName);
		save();
	}

	public void clearCompost(AllotmentPatch patch)
	{
		if (patch == null || compost.remove(patch) == null)
		{
			return;
		}
		save();
	}

	public void observeReadyAt(AllotmentPatch patch, Client client)
	{
		if (patch == null || client == null)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null
			|| !patch.containsRegion(player.getWorldLocation().getRegionID()))
		{
			return;
		}
		int value = client.getVarbitValue(patch.getVarbit());
		Integer current = values.get(patch);
		if (freezeTicks > 0 && !isHarvestLifeDrop(current, value) && !isHarvestFinish(current, value))
		{
			return;
		}
		if (applyObserved(patch, value))
		{
			save();
		}
	}

	public void markPlanted(AllotmentPatch patch, int growStart)
	{
		if (patch == null || growStart <= 0)
		{
			return;
		}
		values.put(patch, growStart);
		observedAt.put(patch, Instant.now().getEpochSecond());
		harvestCycleReady = false;
		cycleCompleteEpoch = null;
		save();
	}

	public boolean observeVisible(AllotmentPatch patch, int value, String objectName, int playerRegion)
	{
		if (patch == null || !patch.containsRegion(playerRegion))
		{
			return false;
		}
		boolean changed = false;
		if (value >= 0 && !AllotmentCrops.isUnknown(value))
		{
			changed |= applyObserved(patch, value);
		}
		Integer stored = values.get(patch);
		if (stored != null && AllotmentCrops.isEmpty(stored))
		{
			if (visibleCrop.remove(patch) != null)
			{
				changed = true;
			}
		}
		else
		{
			String crop = AllotmentCrops.fromObjectName(objectName);
			if (crop != null && !crop.equals(visibleCrop.get(patch)))
			{
				visibleCrop.put(patch, crop);
				changed = true;
			}
		}
		if (changed)
		{
			save();
		}
		return changed;
	}

	public List<HerbPatchView> snapshot()
	{
		return snapshot(patch -> true);
	}

	public List<HerbPatchView> snapshot(Predicate<AllotmentPatch> include)
	{
		if (persistMaturePatches())
		{
			save();
		}
		Predicate<AllotmentPatch> visible = include == null ? patch -> true : include;
		List<HerbPatchView> views = new ArrayList<>();
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (!visible.test(patch))
			{
				continue;
			}
			Integer value = values.get(patch);
			if (value == null)
			{
				views.add(new HerbPatchView(patch.getLocation(), "Unknown", 0, "Visit to update", null, false,
					HerbPatchView.noTeleportIcons(), "No teleport ready", false, -1, -1, patch.isTeleportAnchor()));
				continue;
			}
			AllotmentCrops.Decoded decoded = AllotmentCrops.decode(value);
			String crop = visibleCrop.getOrDefault(patch, decoded.crop);
			int cropItemId = AllotmentCrops.itemIdForCrop(crop);
			if (cropItemId <= 0)
			{
				cropItemId = decoded.itemId;
			}
			int remaining = predictedRemaining(patch, value);
			String state = decoded.state;
			int harvestLives = -1;
			if ("Growing".equals(state) && remaining == 0 && growthTimeElapsed(patch, value))
			{
				state = "Ready";
				harvestLives = 2;
			}
			else if ("Growing".equals(state) && remaining == 0)
			{
				remaining = Math.max(1, decoded.remainingTicks);
			}
			else if ("Ready".equals(state) && decoded.harvestStart > 0)
			{
				harvestLives = Math.max(0, decoded.harvestStart + 2 - value);
			}
			views.add(new HerbPatchView(
				patch.getLocation(),
				crop,
				cropItemId,
				state,
				compost.get(patch),
				true,
				HerbPatchView.noTeleportIcons(),
				"No teleport ready",
				false,
				remaining,
				harvestLives,
				patch.isTeleportAnchor()));
		}
		return views;
	}

	public HerbReadyTime sharedReadyTime()
	{
		return sharedReadyTime(patch -> true);
	}

	public HerbReadyTime sharedReadyTime(Predicate<AllotmentPatch> include)
	{
		Predicate<AllotmentPatch> visible = include == null ? patch -> true : include;
		long now = Instant.now().getEpochSecond();
		Long earliest = null;
		int earliestTicks = 0;
		int growing = 0;
		int matching = 0;
		int totalTicks = 8;
		for (Map.Entry<AllotmentPatch, Integer> entry : values.entrySet())
		{
			if (entry.getValue() == null || !visible.test(entry.getKey()))
			{
				continue;
			}
			AllotmentCrops.Decoded decoded = AllotmentCrops.decode(entry.getValue());
			if (!"Growing".equals(decoded.state) && !"Diseased".equals(decoded.state))
			{
				continue;
			}
			int ticks = predictedRemaining(entry.getKey(), entry.getValue());
			if (ticks <= 0)
			{
				continue;
			}
			long done = doneEstimate(entry.getKey(), entry.getValue());
			if (done <= now)
			{
				continue;
			}
			growing++;
			int cropTotal = Math.max(decoded.totalTicks, ticks);
			if (earliest == null || done < earliest)
			{
				earliest = done;
				earliestTicks = ticks;
				matching = 1;
				totalTicks = cropTotal;
			}
			else if (done == earliest)
			{
				matching++;
				totalTicks = Math.max(totalTicks, cropTotal);
			}
		}
		if (earliest == null)
		{
			if (hasVisibleReady(visible))
			{
				if (cycleCompleteEpoch == null)
				{
					cycleCompleteEpoch = Instant.now().getEpochSecond();
				}
				String clock = formatClock(cycleCompleteEpoch);
				return new HerbReadyTime(clock, "All allotment plots ready at " + clock, 0, Math.max(totalTicks, 8));
			}
			cycleCompleteEpoch = null;
			return HerbReadyTime.none();
		}
		cycleCompleteEpoch = earliest;
		String clock = formatClock(earliest);
		String tooltip = matching == growing
			? "All allotment plots ready at " + clock
			: "Earliest allotment plots ready at " + clock;
		return new HerbReadyTime(clock, tooltip, earliestTicks, Math.max(totalTicks, earliestTicks));
	}

	private String formatClock(long epoch)
	{
		return Instant.ofEpochSecond(epoch).atZone(ZoneId.systemDefault()).format(CLOCK);
	}

	public boolean harvestCycleFinished(Predicate<AllotmentPatch> include)
	{
		if (!harvestCycleReady)
		{
			return false;
		}
		Predicate<AllotmentPatch> visible = include == null ? patch -> true : include;
		boolean known = false;
		for (AllotmentPatch patch : AllotmentPatch.values())
		{
			if (!visible.test(patch))
			{
				continue;
			}
			Integer value = values.get(patch);
			if (value == null)
			{
				continue;
			}
			known = true;
			AllotmentCrops.Decoded decoded = AllotmentCrops.decode(value);
			String state = decoded.state;
			if ("Growing".equals(state) && predictedRemaining(patch, value) == 0 && growthTimeElapsed(patch, value))
			{
				state = "Ready";
			}
			if ("Ready".equals(state))
			{
				return false;
			}
		}
		return known;
	}

	public void noteHarvestCycleClosed()
	{
		if (!harvestCycleReady)
		{
			return;
		}
		harvestCycleReady = false;
		save();
	}

	private void save()
	{
		StoredState state = new StoredState();
		state.values = new java.util.HashMap<>();
		state.compost = new java.util.HashMap<>();
		state.observedAt = new java.util.HashMap<>();
		state.farmTickOffset = farmTickOffset;
		state.farmTickOffsetPrecision = farmTickOffsetPrecision;
		state.harvestCycleReady = harvestCycleReady;
		state.cycleCompleteEpoch = cycleCompleteEpoch;
		state.cycleReadyEpoch = cycleCompleteEpoch;
		for (Map.Entry<AllotmentPatch, Integer> entry : values.entrySet())
		{
			state.values.put(entry.getKey().name(), entry.getValue());
		}
		for (Map.Entry<AllotmentPatch, String> entry : compost.entrySet())
		{
			state.compost.put(entry.getKey().name(), entry.getValue());
		}
		for (Map.Entry<AllotmentPatch, Long> entry : observedAt.entrySet())
		{
			state.observedAt.put(entry.getKey().name(), entry.getValue());
		}
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY, gson.toJson(state));
	}

	private boolean isPrematureReady(AllotmentPatch patch, Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		String from = AllotmentCrops.decode(previous).state;
		if (!"Growing".equals(from) && !"Diseased".equals(from))
		{
			return false;
		}
		return "Ready".equals(AllotmentCrops.decode(value).state) && !growthTimeElapsed(patch, previous);
	}

	private static boolean isHarvestFinish(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		String from = AllotmentCrops.decode(previous).state;
		if (!"Ready".equals(from) && !"Diseased".equals(from))
		{
			return false;
		}
		String to = AllotmentCrops.decode(value).state;
		return "Empty".equals(to) || "Dead".equals(to);
	}

	private static boolean isEmptyToReady(Integer previous, int value)
	{
		return previous != null
			&& AllotmentCrops.isEmpty(previous)
			&& "Ready".equals(AllotmentCrops.decode(value).state);
	}

	private static boolean isLiveVarbitUpdate(Integer previous, int value)
	{
		if (previous == null || previous == value)
		{
			return true;
		}
		if (isHarvestLifeDrop(previous, value) || isGrowthTick(previous, value) || isHarvestFinish(previous, value))
		{
			return true;
		}
		AllotmentCrops.Decoded previousCrop = AllotmentCrops.decode(previous);
		AllotmentCrops.Decoded nextCrop = AllotmentCrops.decode(value);
		if (!previousCrop.crop.equals(nextCrop.crop)
			&& !"Unknown".equals(nextCrop.crop)
			&& !"Empty".equals(nextCrop.crop)
			&& !"Ready".equals(nextCrop.state))
		{
			return true;
		}
		String from = previousCrop.state;
		if (!"Empty".equals(from) && !"Dead".equals(from))
		{
			return false;
		}
		String to = nextCrop.state;
		return "Growing".equals(to) || "Empty".equals(to) || "Dead".equals(to) || "Diseased".equals(to);
	}

	private boolean applyObserved(AllotmentPatch patch, int value)
	{
		if (AllotmentCrops.isUnknown(value))
		{
			return false;
		}
		Integer previous = values.get(patch);
		if (isHarvestLifeRevert(previous, value) || isEmptyToReady(previous, value))
		{
			return false;
		}
		if (isPrematureReady(patch, previous, value))
		{
			int confirms = resetConfirm.getOrDefault(patch, 0) + 1;
			resetConfirm.put(patch, confirms);
			if (confirms < 2)
			{
				return false;
			}
		}
		else
		{
			resetConfirm.remove(patch);
		}
		if (previous != null && previous == value)
		{
			return false;
		}
		values.put(patch, value);
		observedAt.put(patch, Instant.now().getEpochSecond());
		if (previous != null && AllotmentCrops.isEmpty(previous) && !AllotmentCrops.isEmpty(value))
		{
			harvestCycleReady = false;
			cycleCompleteEpoch = null;
		}
		if (previous != null && !AllotmentCrops.isEmpty(previous) && AllotmentCrops.isEmpty(value))
		{
			compost.remove(patch);
			visibleCrop.remove(patch);
		}
		if ("Ready".equals(AllotmentCrops.decode(value).state))
		{
			harvestCycleReady = true;
		}
		if (previous != null && isGrowthTick(previous, value))
		{
			observeFarmTick();
		}
		return true;
	}

	private static int harvestLives(int value)
	{
		AllotmentCrops.Decoded decoded = AllotmentCrops.decode(value);
		if (!"Ready".equals(decoded.state) || decoded.harvestStart <= 0)
		{
			return -1;
		}
		return Math.max(0, decoded.harvestStart + HARVEST_LIVES - value);
	}

	private static boolean isHarvestLifeDrop(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		AllotmentCrops.Decoded prev = AllotmentCrops.decode(previous);
		AllotmentCrops.Decoded next = AllotmentCrops.decode(value);
		if (!"Ready".equals(prev.state) || !"Ready".equals(next.state) || !prev.crop.equals(next.crop))
		{
			return false;
		}
		int prevLives = harvestLives(previous);
		int nextLives = harvestLives(value);
		return nextLives >= 0 && prevLives >= 0 && nextLives < prevLives;
	}

	private static boolean isHarvestLifeRevert(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		AllotmentCrops.Decoded prev = AllotmentCrops.decode(previous);
		AllotmentCrops.Decoded next = AllotmentCrops.decode(value);
		if (!"Ready".equals(prev.state) || !"Ready".equals(next.state) || !prev.crop.equals(next.crop))
		{
			return false;
		}
		return harvestLives(value) > harvestLives(previous);
	}

	private static boolean isGrowthTick(int previous, int current)
	{
		int from = AllotmentCrops.decode(previous).remainingTicks;
		int to = AllotmentCrops.decode(current).remainingTicks;
		return from > 0 && to == from - 1;
	}

	private void observeFarmTick()
	{
		int offsetMins = (int) Math.abs(((Instant.now().getEpochSecond() / 60) % AllotmentCrops.TICK_MINUTES)
			- AllotmentCrops.TICK_MINUTES);
		if (farmTickOffsetPrecision == null || AllotmentCrops.TICK_MINUTES >= farmTickOffsetPrecision)
		{
			farmTickOffset = offsetMins;
			farmTickOffsetPrecision = AllotmentCrops.TICK_MINUTES;
		}
	}

	private long doneEstimate(AllotmentPatch patch, int value)
	{
		int stored = AllotmentCrops.decode(value).remainingTicks;
		if (stored <= 0)
		{
			return Instant.now().getEpochSecond();
		}
		Long observed = observedAt.get(patch);
		long from = observed == null ? Instant.now().getEpochSecond() : observed;
		return tickTime(from, stored);
	}

	private long tickTime(long requestedTime, int ticks)
	{
		Integer trackingPrecision = configManager.getRSProfileConfiguration(
			"timetracking", "farmTickOffsetPrecision", int.class);
		Integer trackingOffset = configManager.getRSProfileConfiguration(
			"timetracking", "farmTickOffset", int.class);
		Integer precision = trackingPrecision;
		Integer offsetMins = trackingOffset;
		if (precision == null || offsetMins == null || !usableOffset(precision))
		{
			precision = farmTickOffsetPrecision;
			offsetMins = farmTickOffset;
		}

		long calculatedOffset = 0L;
		if (precision != null && offsetMins != null && usableOffset(precision))
		{
			calculatedOffset = (offsetMins % AllotmentCrops.TICK_MINUTES) * 60L;
		}
		long unixNow = requestedTime + calculatedOffset;
		long tickLength = AllotmentCrops.TICK_MINUTES * 60L;
		long currentTick = unixNow - (unixNow % tickLength);
		return currentTick + (ticks * tickLength) - calculatedOffset;
	}

	private static boolean usableOffset(int precision)
	{
		return precision >= AllotmentCrops.TICK_MINUTES || precision >= 40;
	}

	private int predictedRemaining(AllotmentPatch patch, int value)
	{
		int stored = AllotmentCrops.decode(value).remainingTicks;
		if (stored < 0)
		{
			return stored;
		}
		if (stored == 0)
		{
			return 0;
		}
		Long observed = observedAt.get(patch);
		if (observed == null)
		{
			return stored;
		}
		long done = doneEstimate(patch, value);
		long now = Instant.now().getEpochSecond();
		if (now >= done)
		{
			return 0;
		}
		long tick = AllotmentCrops.TICK_MINUTES * 60L;
		return Math.max(1, (int) Math.ceil((done - now) / (double) tick));
	}

	private boolean growthTimeElapsed(AllotmentPatch patch, int value)
	{
		AllotmentCrops.Decoded decoded = AllotmentCrops.decode(value);
		if (!"Growing".equals(decoded.state) || decoded.remainingTicks <= 0)
		{
			return false;
		}
		Long observed = observedAt.get(patch);
		if (observed == null)
		{
			return false;
		}
		long minWait = (long) (decoded.remainingTicks - 1) * AllotmentCrops.TICK_MINUTES * 60L;
		return Instant.now().getEpochSecond() - observed >= minWait;
	}

	private boolean persistMaturePatches()
	{
		boolean changed = false;
		for (Map.Entry<AllotmentPatch, Integer> entry : new ArrayList<>(values.entrySet()))
		{
			Integer value = entry.getValue();
			if (value == null || !"Growing".equals(AllotmentCrops.decode(value).state))
			{
				continue;
			}
			if (predictedRemaining(entry.getKey(), value) != 0 || !growthTimeElapsed(entry.getKey(), value))
			{
				continue;
			}
			int ready = AllotmentCrops.harvestValue(value);
			if (ready == value)
			{
				continue;
			}
			values.put(entry.getKey(), ready);
			harvestCycleReady = true;
			if (cycleCompleteEpoch == null)
			{
				cycleCompleteEpoch = Instant.now().getEpochSecond();
			}
			changed = true;
		}
		return changed;
	}

	private boolean hasVisibleReady(Predicate<AllotmentPatch> visible)
	{
		for (Map.Entry<AllotmentPatch, Integer> entry : values.entrySet())
		{
			if (entry.getValue() == null || !visible.test(entry.getKey()))
			{
				continue;
			}
			AllotmentCrops.Decoded decoded = AllotmentCrops.decode(entry.getValue());
			String state = decoded.state;
			if ("Growing".equals(state) && predictedRemaining(entry.getKey(), entry.getValue()) == 0
				&& growthTimeElapsed(entry.getKey(), entry.getValue()))
			{
				state = "Ready";
			}
			if ("Ready".equals(state))
			{
				return true;
			}
		}
		return false;
	}

	private static final class StoredState
	{
		private Map<String, Integer> values;
		private Map<String, String> compost;
		private Map<String, Long> observedAt;
		private Integer farmTickOffset;
		private Integer farmTickOffsetPrecision;
		private Long cycleReadyEpoch;
		private Long cycleCompleteEpoch;
		private Boolean harvestCycleReady;
	}
}

