package com.potionprofitpro.stats;

import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Setter;

@Singleton
public class CompostTracker
{
	private int harvestedWatermelons;
	private int binWatermelons;
	@Getter
	@Setter
	private boolean ultra;
	@Getter
	@Setter
	private boolean fillWithBottomless;
	private int valuedInBin;

	@Inject
	private CompostTracker()
	{
	}

	public void harvested(int quantity)
	{
		if (quantity > 0)
		{
			harvestedWatermelons += quantity;
		}
	}

	public void addedToBin(int quantity)
	{
		if (quantity > 0)
		{
			binWatermelons += quantity;
			valuedInBin += quantity;
		}
	}

	public int consumeValued(int quantity)
	{
		int used = Math.min(Math.max(quantity, 0), valuedInBin);
		valuedInBin -= used;
		return used;
	}

	public int consumeBin(int quantity)
	{
		int used = Math.min(Math.max(quantity, 0), binWatermelons);
		binWatermelons -= used;
		if (binWatermelons == 0)
		{
			ultra = false;
		}
		return used;
	}

	public int consumeHarvested(int quantity)
	{
		int used = Math.min(Math.max(quantity, 0), harvestedWatermelons);
		harvestedWatermelons -= used;
		return used;
	}

	public int pendingBinWatermelons()
	{
		return binWatermelons;
	}
}

