@Singleton
public class HerbPatchTracker
{
	private static final String KEY = "herbPatchState";
	private static final int HERB_TICK_MINUTES = 20;
	private static final int HERB_GROWTH_TICKS = 4;
	private static final int HERB_HARVEST_LIVES = 2;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("h:mm a", Locale.US);

	private final Map<HerbPatch, Integer> values = new EnumMap<>(HerbPatch.class);
	private final Map<HerbPatch, String> compost = new EnumMap<>(HerbPatch.class);
	private final Map<HerbPatch, Long> observedAt = new EnumMap<>(HerbPatch.class);
	private Integer farmTickOffset;
	private Integer farmTickOffsetPrecision;
	private boolean harvestCycleReady;
	private Long cycleCompleteEpoch;
	private int lockedRegion = -1;
	private int freezeTicks;
	private WorldPoint lastPoint;
	private final Map<HerbPatch, Integer> resetConfirm = new EnumMap<>(HerbPatch.class);

	@Inject
	private PotionProfitProConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	public void load()
	{
		values.clear();
		compost.clear();
		observedAt.clear();
		resetConfirm.clear();
		String json = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		StoredState state = gson.fromJson(json, StoredState.class);
		if (state == null || state.values == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> entry : state.values.entrySet())
		{
			try
			{
				if (isUnknownValue(entry.getValue()))
				{
					continue;
				}
				values.put(HerbPatch.valueOf(entry.getKey()), entry.getValue());
			}
			catch (IllegalArgumentException ignored)
			{
			}
		}
		if (state.compost != null)
		{
			for (Map.Entry<String, String> entry : state.compost.entrySet())
			{
				try
				{
					compost.put(HerbPatch.valueOf(entry.getKey()), entry.getValue());
				}
				catch (IllegalArgumentException ignored)
				{
				}
			}
		}
		if (state.observedAt != null)
		{
			for (Map.Entry<String, Long> entry : state.observedAt.entrySet())
			{
				try
				{
					HerbPatch patch = HerbPatch.valueOf(entry.getKey());
					if (values.containsKey(patch) && entry.getValue() != null)
					{
						observedAt.put(patch, entry.getValue());
					}
				}
				catch (IllegalArgumentException ignored)
				{
				}
			}
		}
		farmTickOffset = state.farmTickOffset;
		farmTickOffsetPrecision = state.farmTickOffsetPrecision;
		harvestCycleReady = Boolean.TRUE.equals(state.harvestCycleReady)
			|| (state.cycleReadyEpoch != null && state.cycleReadyEpoch <= Instant.now().getEpochSecond());
		cycleCompleteEpoch = state.cycleCompleteEpoch != null ? state.cycleCompleteEpoch : state.cycleReadyEpoch;
	}

	public void tick(Client client)
	{
		if (persistMaturePatches())
		{
			save();
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return;
		}

		if (client.isInInstancedRegion())
		{
			return;
		}
		WorldPoint location = player.getWorldLocation();
		int regionId = location.getRegionID();
		if (lastPoint != null && location.distanceTo(lastPoint) > 16)
		{
			freeze(4);
		}
		lastPoint = location;
		if (regionId != lockedRegion)
		{
			lockedRegion = regionId;
			freeze(4);
			return;
		}
		if (freezeTicks > 0)
		{
			freezeTicks--;
			return;
		}
		boolean changed = false;
		for (HerbPatch patch : HerbPatch.values())
		{
			if (!patch.containsRegion(regionId))
			{
				continue;
			}
			if (applyObserved(patch, client.getVarbitValue(patch.getVarbit())))
			{
				changed = true;
			}
		}
		if (persistMaturePatches())
		{
			changed = true;
		}
		if (changed)
		{
			save();
		}
	}

	public void advancePredictions()
	{
		if (persistMaturePatches())
		{
			save();
		}
	}

	public void freeze(int ticks)
	{
		freezeTicks = Math.max(freezeTicks, ticks);
		resetConfirm.clear();
	}

	public boolean isHerbVarbit(int varbitId)
	{
		for (HerbPatch patch : HerbPatch.values())
		{
			if (patch.getVarbit() == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	public boolean applyVarbit(Client client, int varbitId)
	{
		if (client.getGameState() != GameState.LOGGED_IN || !isHerbVarbit(varbitId))
		{
			return false;
		}
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null || client.isInInstancedRegion())
		{
			return false;
		}
		int regionId = player.getWorldLocation().getRegionID();
		int value = client.getVarbitValue(varbitId);
		boolean changed = false;
		for (HerbPatch patch : HerbPatch.values())
		{
			if (patch.getVarbit() != varbitId || !patch.containsRegion(regionId))
			{
				continue;
			}
			Integer previous = values.get(patch);
			if (!isLiveVarbitUpdate(previous, value) || isPrematureReady(patch, previous, value))
			{
				freeze(8);
				continue;
			}
			if (freezeTicks > 0 && !isHarvestLifeDrop(previous, value) && !isHarvestFinish(previous, value))
			{
				continue;
			}
			if (applyObserved(patch, value))
			{
				changed = true;
			}
		}
		if (changed)
		{
			save();
		}
		return changed;
	}

	public void setCompost(WorldPoint location, String compostName)
	{
		HerbPatch patch = patchAt(location);
		if (patch == null || compostName == null || compostName.isEmpty())
		{
			return;
		}
		if (compostName.equals(compost.get(patch)))
		{
			return;
		}
		compost.put(patch, compostName);
		save();
	}

	public void clearCompost(WorldPoint location)
	{
		HerbPatch patch = patchAt(location);
		if (patch == null || compost.remove(patch) == null)
		{
			return;
		}
		save();
	}

	public void observeReadyAt(WorldPoint location, int playerRegion, Client client)
	{
		HerbPatch patch = patchAt(location);
		if (patch == null || !patch.containsRegion(playerRegion) || client == null)
		{
			return;
		}
		int value = client.getVarbitValue(patch.getVarbit());
		Integer current = values.get(patch);
		if (freezeTicks > 0 && !isHarvestLifeDrop(current, value) && !isHarvestFinish(current, value))
		{
			return;
		}
		if (applyObserved(patch, value))
		{
			save();
		}
	}

	public void markPlanted(WorldPoint location)
	{
		markPlanted(location, config.profitPotion().getHerbGrowStart());
	}

	public void markPlanted(WorldPoint location, int growStart)
	{
		HerbPatch patch = patchAt(location);
		if (patch == null)
		{
			return;
		}
		values.put(patch, growingValue(growStart, HERB_GROWTH_TICKS));
		observedAt.put(patch, Instant.now().getEpochSecond());
		harvestCycleReady = false;
		cycleCompleteEpoch = null;
		save();
	}

	public List<HerbPatchView> snapshot()
	{
		return snapshot(patch -> true);
	}

	public List<HerbPatchView> snapshot(Predicate<HerbPatch> include)
	{
		if (persistMaturePatches())
		{
			save();
		}
		Predicate<HerbPatch> visible = include == null ? patch -> true : include;
		List<HerbPatchView> views = new ArrayList<>();
		for (HerbPatch patch : HerbPatch.values())
		{
			if (!visible.test(patch))
			{
				continue;
			}
			Integer value = values.get(patch);
			if (value == null)
			{
				views.add(new HerbPatchView(patch.getLocation(), "Unknown", 0, "Visit to update", null, false,
					HerbPatchView.noTeleportIcons(), "No teleport ready", false, -1, -1, true));
				continue;
			}
			Decoded decoded = decode(value);
			int remaining = predictedRemaining(patch, value);
			String state = decoded.state;
			int harvestLives = decoded.harvestLives;
			if ("Growing".equals(state) && remaining == 0 && growthTimeElapsed(patch, value))
			{
				state = "Ready";
				harvestLives = HERB_HARVEST_LIVES;
			}
			else if ("Growing".equals(state) && remaining == 0)
			{
				remaining = Math.max(1, decoded.remainingTicks);
			}
			views.add(new HerbPatchView(
				patch.getLocation(),
				decoded.crop,
				decoded.itemId,
				state,
				compost.get(patch),
				true,
				HerbPatchView.noTeleportIcons(),
				"No teleport ready",
				false,
				remaining,
				harvestLives,
				true));
		}
		return views;
	}

	public HerbReadyTime sharedReadyTime()
	{
		return sharedReadyTime(patch -> true);
	}

	public HerbReadyTime sharedReadyTime(Predicate<HerbPatch> include)
	{
		Predicate<HerbPatch> visible = include == null ? patch -> true : include;
		long now = Instant.now().getEpochSecond();
		Long earliest = null;
		int earliestTicks = 0;
		int growing = 0;
		int matching = 0;
		int totalTicks = HERB_GROWTH_TICKS;
		for (Map.Entry<HerbPatch, Integer> entry : values.entrySet())
		{
			if (entry.getValue() == null || !visible.test(entry.getKey()))
			{
				continue;
			}
			Decoded decoded = decode(entry.getValue());
			if (!"Growing".equals(decoded.state) && !"Diseased".equals(decoded.state))
			{
				continue;
			}
			int ticks = predictedRemaining(entry.getKey(), entry.getValue());
			if (ticks <= 0)
			{
				continue;
			}
			long done = doneEstimate(entry.getKey(), entry.getValue());
			if (done <= now)
			{
				continue;
			}
			growing++;
			if (earliest == null || done < earliest)
			{
				earliest = done;
				earliestTicks = ticks;
				matching = 1;
				totalTicks = Math.max(HERB_GROWTH_TICKS, ticks);
			}
			else if (done == earliest)
			{
				matching++;
			}
		}
		if (earliest == null)
		{
			if (hasVisibleReady(visible))
			{
				if (cycleCompleteEpoch == null)
				{
					cycleCompleteEpoch = Instant.now().getEpochSecond();
				}
				String clock = formatClock(cycleCompleteEpoch);
				return new HerbReadyTime(clock, "All herb plots ready at " + clock, 0, HERB_GROWTH_TICKS);
			}
			cycleCompleteEpoch = null;
			return HerbReadyTime.none();
		}
		cycleCompleteEpoch = earliest;
		String clock = formatClock(earliest);
		String tooltip = matching == growing
			? "All herb plots ready at " + clock
			: "Earliest herb plots ready at " + clock;
		return new HerbReadyTime(clock, tooltip, earliestTicks, totalTicks);
	}

	private String formatClock(long epoch)
	{
		return Instant.ofEpochSecond(epoch).atZone(ZoneId.systemDefault()).format(CLOCK);
	}

	public boolean harvestCycleFinished(Predicate<HerbPatch> include)
	{
		if (!harvestCycleReady)
		{
			return false;
		}
		Predicate<HerbPatch> visible = include == null ? patch -> true : include;
		boolean known = false;
		for (HerbPatch patch : HerbPatch.values())
		{
			if (!visible.test(patch))
			{
				continue;
			}
			Integer value = values.get(patch);
			if (value == null)
			{
				continue;
			}
			known = true;
			Decoded decoded = decode(value);
			String state = decoded.state;
			if ("Growing".equals(state) && predictedRemaining(patch, value) == 0 && growthTimeElapsed(patch, value))
			{
				state = "Ready";
			}
			if ("Ready".equals(state))
			{
				return false;
			}
		}
		return known;
	}

	public void noteHarvestCycleClosed()
	{
		if (!harvestCycleReady)
		{
			return;
		}
		harvestCycleReady = false;
		save();
	}

	private static int growingValue(int growStart, int remainingTicks)
	{
		int remaining = Math.max(1, Math.min(HERB_GROWTH_TICKS, remainingTicks));
		return growStart + (HERB_GROWTH_TICKS - remaining);
	}

	private static HerbPatch patchAt(WorldPoint location)
	{
		return location == null ? null : HerbPatch.forRegion(location.getRegionID());
	}

	private boolean applyObserved(HerbPatch patch, int value)
	{
		if (isUnknownValue(value))
		{
			return false;
		}
		Integer previous = values.get(patch);
		if (isForeignHerb(value) || isHarvestLifeRevert(previous, value) || isEmptyToReady(previous, value))
		{
			return false;
		}
		if (isPrematureReady(patch, previous, value))
		{
			int confirms = resetConfirm.getOrDefault(patch, 0) + 1;
			resetConfirm.put(patch, confirms);
			if (confirms < 2)
			{
				return false;
			}
		}
		else
		{
			resetConfirm.remove(patch);
		}
		if (previous != null && previous == value)
		{
			return false;
		}
		values.put(patch, value);
		observedAt.put(patch, Instant.now().getEpochSecond());
		if (previous != null && isEmpty(previous) && !isEmpty(value))
		{
			harvestCycleReady = false;
			cycleCompleteEpoch = null;
		}
		if (previous != null && !isEmpty(previous) && isEmpty(value))
		{
			compost.remove(patch);
		}
		if ("Ready".equals(decode(value).state))
		{
			harvestCycleReady = true;
		}
		if (previous != null && isGrowthTick(previous, value))
		{
			observeFarmTick();
		}
		return true;
	}

	private static boolean isHarvestLifeDrop(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		Decoded prev = decode(previous);
		Decoded next = decode(value);
		if (!"Ready".equals(prev.state) || !"Ready".equals(next.state) || !prev.crop.equals(next.crop))
		{
			return false;
		}
		return next.harvestLives >= 0 && prev.harvestLives >= 0 && next.harvestLives < prev.harvestLives;
	}

	private static boolean isHarvestLifeRevert(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		Decoded prev = decode(previous);
		Decoded next = decode(value);
		if (!"Ready".equals(prev.state) || !"Ready".equals(next.state) || !prev.crop.equals(next.crop))
		{
			return false;
		}
		return next.harvestLives > prev.harvestLives;
	}

	private void save()
	{
		StoredState state = new StoredState();
		state.values = new java.util.HashMap<>();
		state.compost = new java.util.HashMap<>();
		state.observedAt = new java.util.HashMap<>();
		state.farmTickOffset = farmTickOffset;
		state.farmTickOffsetPrecision = farmTickOffsetPrecision;
		state.harvestCycleReady = harvestCycleReady;
		state.cycleCompleteEpoch = cycleCompleteEpoch;
		state.cycleReadyEpoch = cycleCompleteEpoch;
		for (Map.Entry<HerbPatch, Integer> entry : values.entrySet())
		{
			state.values.put(entry.getKey().name(), entry.getValue());
		}
		for (Map.Entry<HerbPatch, String> entry : compost.entrySet())
		{
			state.compost.put(entry.getKey().name(), entry.getValue());
		}
		for (Map.Entry<HerbPatch, Long> entry : observedAt.entrySet())
		{
			state.observedAt.put(entry.getKey().name(), entry.getValue());
		}
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY, gson.toJson(state));
	}

	private static boolean isForeignHerb(int value)
	{
		if (isEmpty(value) || isUnknownValue(value))
		{
			return false;
		}
		Decoded decoded = decode(value);
		return !"Empty".equals(decoded.state)
			&& !"Dead".equals(decoded.state)
			&& decoded.itemId != 0
			&& decoded.itemId != ItemID.UNIDENTIFIED_RANARR
			&& decoded.itemId != ItemID.UNIDENTIFIED_SNAPDRAGON
			&& decoded.itemId != ItemID.UNIDENTIFIED_TOADFLAX;
	}

	private boolean isPrematureReady(HerbPatch patch, Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		String from = decode(previous).state;
		if (!"Growing".equals(from) && !"Diseased".equals(from))
		{
			return false;
		}
		return "Ready".equals(decode(value).state) && !growthTimeElapsed(patch, previous);
	}

	private static boolean isHarvestFinish(Integer previous, int value)
	{
		if (previous == null)
		{
			return false;
		}
		String from = decode(previous).state;
		if (!"Ready".equals(from) && !"Diseased".equals(from))
		{
			return false;
		}
		String to = decode(value).state;
		return "Empty".equals(to) || "Dead".equals(to);
	}

	private static boolean isEmptyToReady(Integer previous, int value)
	{
		return previous != null && isEmpty(previous) && "Ready".equals(decode(value).state);
	}

	private static boolean isLiveVarbitUpdate(Integer previous, int value)
	{
		if (previous == null || previous == value)
		{
			return true;
		}
		if (isHarvestLifeDrop(previous, value) || isGrowthTick(previous, value) || isHarvestFinish(previous, value))
		{
			return true;
		}
		String from = decode(previous).state;
		if (!"Empty".equals(from) && !"Dead".equals(from))
		{
			return false;
		}
		String to = decode(value).state;
		return "Growing".equals(to) || "Empty".equals(to) || "Dead".equals(to) || "Diseased".equals(to);
	}

	private static boolean isUnknownValue(int value)
	{
		Decoded decoded = decode(value);
		return "Herbs".equals(decoded.crop) && decoded.itemId == 0
			&& "Growing".equals(decoded.state) && decoded.remainingTicks < 0;
	}

	private static boolean isEmpty(int value)
	{
		return value <= 3 || value == 67 || (value >= 176 && value <= 191);
	}

	private static Decoded decode(int value)
	{
		if (isEmpty(value))
		{
			return new Decoded("Empty", 0, "Empty", -1);
		}
		if (value >= 170 && value <= 172)
		{
			return new Decoded("Herbs", 0, "Dead", -1);
		}

		Decoded healthy = healthy(value);
		if (healthy != null)
		{
			return withRemaining(healthy, value);
		}
		Decoded diseased = diseased(value);
		if (diseased != null)
		{
			return new Decoded(diseased.crop, diseased.itemId, diseased.state, -1);
		}
		if (value >= 192 && value <= 195)
		{
			return withRemaining(new Decoded("Goutweed", ItemID.EADGAR_GOUTWEED_HERB, "Growing", -1), value);
		}
		return new Decoded("Herbs", 0, "Growing", -1);
	}

	private static Decoded withRemaining(Decoded decoded, int value)
	{
		int remaining = -1;
		int harvestLives = -1;
		if ("Ready".equals(decoded.state))
		{
			remaining = 0;
			harvestLives = harvestLives(value);
		}
		else if ("Growing".equals(decoded.state))
		{
			remaining = growingRemaining(value);
		}
		return new Decoded(decoded.crop, decoded.itemId, decoded.state, remaining, harvestLives);
	}

	private static int harvestLives(int value)
	{
		int[] starts = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103};
		for (int start : starts)
		{
			int readyStart = start + 4;
			int readyEnd = start + 6;
			if (between(value, readyStart, readyEnd))
			{
				return readyEnd - value;
			}
		}
		if (between(value, 196, 197))
		{
			return 197 - value;
		}
		return HERB_HARVEST_LIVES;
	}

