	private static int harvestValue(Integer current)
	{
		if (current == null)
		{
			return 36;
		}
		int[] starts = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103};
		for (int start : starts)
		{
			if (between(current, start, start + 6))
			{
				return Math.max(current, start + 4);
			}
		}
		return 36;
	}

	private static int growingRemaining(int value)
	{
		int[] starts = {4, 11, 18, 25, 32, 39, 46, 53, 60, 68, 75, 82, 89, 96, 103, 192};
		for (int start : starts)
		{
			if (between(value, start, start + 3))
			{
				return start + 4 - value;
			}
		}
		return -1;
	}

	private static boolean isGrowthTick(int previous, int current)
	{
		int from = decode(previous).remainingTicks;
		int to = decode(current).remainingTicks;
		return from > 0 && to == from - 1;
	}

	private void observeFarmTick()
	{
		int offsetMins = (int) Math.abs(((Instant.now().getEpochSecond() / 60) % HERB_TICK_MINUTES) - HERB_TICK_MINUTES);
		if (farmTickOffsetPrecision == null || HERB_TICK_MINUTES >= farmTickOffsetPrecision)
		{
			farmTickOffset = offsetMins;
			farmTickOffsetPrecision = HERB_TICK_MINUTES;
		}
	}

	private long doneEstimate(HerbPatch patch, int value)
	{
		int stored = decode(value).remainingTicks;
		if (stored <= 0)
		{
			return Instant.now().getEpochSecond();
		}
		Long observed = observedAt.get(patch);
		long from = observed == null ? Instant.now().getEpochSecond() : observed;
		return tickTime(from, stored);
	}

	private long tickTime(long requestedTime, int ticks)
	{
		Integer trackingPrecision = configManager.getRSProfileConfiguration(
			"timetracking", "farmTickOffsetPrecision", int.class);
		Integer trackingOffset = configManager.getRSProfileConfiguration(
			"timetracking", "farmTickOffset", int.class);
		Integer precision = trackingPrecision;
		Integer offsetMins = trackingOffset;
		if (precision == null || offsetMins == null || !usableOffset(precision))
		{
			precision = farmTickOffsetPrecision;
			offsetMins = farmTickOffset;
		}

		long calculatedOffset = 0L;
		if (precision != null && offsetMins != null && usableOffset(precision))
		{
			calculatedOffset = (offsetMins % HERB_TICK_MINUTES) * 60L;
		}
		long unixNow = requestedTime + calculatedOffset;
		long tickLength = HERB_TICK_MINUTES * 60L;
		long currentTick = unixNow - (unixNow % tickLength);
		return currentTick + (ticks * tickLength) - calculatedOffset;
	}

	private static boolean usableOffset(int precision)
	{
		return precision >= HERB_TICK_MINUTES || precision >= 40;
	}

	private int predictedRemaining(HerbPatch patch, int value)
	{
		int stored = decode(value).remainingTicks;
		if (stored < 0)
		{
			return stored;
		}
		if (stored == 0)
		{
			return 0;
		}
		Long observed = observedAt.get(patch);
		if (observed == null)
		{
			return stored;
		}
		long done = doneEstimate(patch, value);
		long now = Instant.now().getEpochSecond();
		if (now >= done)
		{
			return 0;
		}
		long tick = HERB_TICK_MINUTES * 60L;
		return Math.max(1, (int) Math.ceil((done - now) / (double) tick));
	}

	private boolean growthTimeElapsed(HerbPatch patch, int value)
	{
		Decoded decoded = decode(value);
		if (!"Growing".equals(decoded.state) || decoded.remainingTicks <= 0)
		{
			return false;
		}
		Long observed = observedAt.get(patch);
		if (observed == null)
		{
			return false;
		}
		long minWait = (long) (decoded.remainingTicks - 1) * HERB_TICK_MINUTES * 60L;
		return Instant.now().getEpochSecond() - observed >= minWait;
	}

	private boolean persistMaturePatches()
	{
		boolean changed = false;
		for (Map.Entry<HerbPatch, Integer> entry : new java.util.ArrayList<>(values.entrySet()))
		{
			Integer value = entry.getValue();
			if (value == null || !"Growing".equals(decode(value).state))
			{
				continue;
			}
			if (predictedRemaining(entry.getKey(), value) != 0 || !growthTimeElapsed(entry.getKey(), value))
			{
				continue;
			}
			int ready = harvestValue(value);
			if (ready == value)
			{
				continue;
			}
			values.put(entry.getKey(), ready);
			harvestCycleReady = true;
			if (cycleCompleteEpoch == null)
			{
				cycleCompleteEpoch = Instant.now().getEpochSecond();
			}
			changed = true;
		}
		return changed;
	}

	private boolean hasVisibleReady(Predicate<HerbPatch> visible)
	{
		for (Map.Entry<HerbPatch, Integer> entry : values.entrySet())
		{
			if (entry.getValue() == null || !visible.test(entry.getKey()))
			{
				continue;
			}
			Decoded decoded = decode(entry.getValue());
			String state = decoded.state;
			if ("Growing".equals(state) && predictedRemaining(entry.getKey(), entry.getValue()) == 0
				&& growthTimeElapsed(entry.getKey(), entry.getValue()))
			{
				state = "Ready";
			}
			if ("Ready".equals(state))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean between(int value, int min, int max)
	{
		return value >= min && value <= max;
	}

