		{
			this(crop, itemId, state, remainingTicks, -1);
		}

		private Decoded(String crop, int itemId, String state, int remainingTicks, int harvestLives)
		{
			this.crop = crop;
			this.itemId = itemId;
			this.state = state;
			this.remainingTicks = remainingTicks;
			this.harvestLives = harvestLives;
		}
	}

	private static final class StoredState
	{
		private Map<String, Integer> values;
		private Map<String, String> compost;
		private Map<String, Long> observedAt;
		private Integer farmTickOffset;
		private Integer farmTickOffsetPrecision;
		private Long cycleReadyEpoch;
