	private boolean treeGnomeVillageFinished;
	private int houseLocation;
	private final Set<String> nexusDests = new HashSet<>();
	private boolean pendingHouseTeleport;
	private int pendingHouseTicks;
	private int leftInstanceTicks;
	private Set<Integer> readyTeleportItems = new HashSet<>();
	private Set<Integer> readyTeleportSprites = new HashSet<>();
	private Set<Integer> readyTeleportSpells = new HashSet<>();

	@Inject
	private HerbTeleportTracker(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
	}

	public void load()
	{
		guildSpiritTreeReady = Boolean.parseBoolean(
			configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, SPIRIT_KEY));
		nexusDests.clear();
		String savedDests = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, NEXUS_KEY);
		if (savedDests != null && !savedDests.isEmpty())
		{
			nexusDests.addAll(Arrays.asList(savedDests.split(",")));
		}
		Integer savedHouse = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, HOUSE_KEY, int.class);
		houseLocation = savedHouse == null ? 0 : savedHouse;
	}

	public void resetLive()
	{
	}

	public void tick()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		treeGnomeVillageFinished = Quest.TREE_GNOME_VILLAGE.getState(client) == QuestState.FINISHED;
		Player player = client.getLocalPlayer();
		if (player == null || player.getWorldLocation() == null)
		{
			return;
		}
		scanNexus();
		WorldPoint location = player.getWorldLocation();
		int regionId = location.getRegionID();
		boolean instanced = client.isInInstancedRegion();
		WorldPoint converted = WorldPoint.fromLocalInstance(client, player.getLocalLocation());
		int convertedRegion = converted == null ? regionId : converted.getRegionID();
		if (instanced)
		{
			leftInstanceTicks = 30;
			pendingHouseTicks = 0;
			if (isHosidiusArrival(convertedRegion))
			{
				setHouseLocation(HOUSE_HOSIDIUS);
			}
		}
		else
		{
			if (leftInstanceTicks > 0)
			{
				observeArrival(regionId);
				if (convertedRegion != regionId)
				{
					observeArrival(convertedRegion);
				}
				leftInstanceTicks--;
			}
			if (pendingHouseTeleport)
			{
				pendingHouseTicks++;
				if (isHosidiusArrival(regionId) || isHosidiusArrival(convertedRegion))
				{
					observeArrival(regionId);
					pendingHouseTeleport = false;
					pendingHouseTicks = 0;
				}
				else if (pendingHouseTicks > 40)
				{
					pendingHouseTeleport = false;
					pendingHouseTicks = 0;
				}
			}
			if (regionId == 6966 || convertedRegion == 6966)
			{
				setHouseLocation(HOUSE_HOSIDIUS);
			}
		}
		if (instanced)
		{
			scanWidgets();
		}
		observeHouseLocation(regionId, convertedRegion, instanced);
		if (!HerbPatch.FARMING_GUILD.containsRegion(regionId))
		{
			return;
		}
		boolean grown = client.getVarbitValue(VarbitID.FARMING_TRANSMIT_A) == SPIRIT_TREE_GROWN;
		if (grown != guildSpiritTreeReady)
		{
			guildSpiritTreeReady = grown;
			configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, SPIRIT_KEY, Boolean.toString(grown));
		}
	}

	public void observeMenu(String option, String target)
	{
		String text = ((option == null ? "" : option) + " " + (target == null ? "" : target)).toLowerCase(Locale.ROOT);
		observeNexusText(text);
		if (isHouseTeleportMenu(text))
		{
			pendingHouseTeleport = true;
		}
	}

	private static boolean isHouseTeleportMenu(String text)
	{
		if (text.contains("nexus") || text.contains("jewellery"))
		{
			return false;
		}
		return text.contains("house")
			&& (text.contains("teleport") || text.contains("outside") || text.contains("break"));
	}

	private void observeNexusText(String text)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		String lower = Text.removeTags(text).toLowerCase(Locale.ROOT);
		if (lower.contains("weiss") || lower.contains("icy basalt"))
		{
			rememberNexus("weiss");
		}
		if (lower.contains("troll stronghold") || lower.contains("stony basalt"))
		{
			rememberNexus("troll stronghold");
		}
		if (lower.contains("camelot") || lower.contains("seers"))
		{
			rememberNexus("camelot");
		}
		if (lower.contains("ardougne"))
		{
			rememberNexus("ardougne");
		}
		if (lower.contains("fortis") || lower.contains("civitas"))
		{
			rememberNexus("fortis");
		}
		if (lower.contains("catherby"))
		{
			rememberNexus("catherby");
		}
		if (lower.contains("harmony"))
		{
			rememberNexus("harmony");
		}
	}

	public List<HerbPatchView> apply(List<HerbPatchView> views)
	{
		List<HerbPatchView> next = new ArrayList<>(views.size());
		Set<Integer> items = new HashSet<>();
		Set<Integer> sprites = new HashSet<>();
		Set<Integer> spells = new HashSet<>();
		boolean canCheck = client.isClientThread() && client.getGameState() == GameState.LOGGED_IN;
		for (HerbPatchView view : views)
		{
			HerbPatch patch = HerbPatch.byLocation(view.getLocation());
			HerbTeleport teleport = HerbTeleport.missing();
			try
			{
				if (canCheck && patch != null)
				{
					teleport = forPatch(patch);
				}
			}
			catch (Exception ignored)
			{
			}
			if ("Ready".equals(view.getState()) && teleport.isReady())
			{
				rememberReadyIcons(teleport, items, sprites, spells);
			}
			next.add(view.withTeleport(teleport));
		}
		readyTeleportItems = items;
		readyTeleportSprites = sprites;
		readyTeleportSpells = spells;
		return next;
	}

	public List<HerbPatchView> applyAllotments(List<HerbPatchView> views)
	{
		List<HerbPatchView> next = new ArrayList<>(views.size());
		boolean canCheck = client.isClientThread() && client.getGameState() == GameState.LOGGED_IN;
		for (HerbPatchView view : views)
		{
			AllotmentPatch patch = AllotmentPatch.byLocation(view.getLocation());
			HerbTeleport teleport = HerbTeleport.missing();
			try
			{
				if (canCheck && patch != null)
				{
					teleport = forAllotment(patch);
				}
			}
			catch (Exception ignored)
			{
			}
			next.add(view.withTeleport(teleport));
		}
		return next;
	}

	public boolean isReadyTeleportItem(int itemId)
	{
		return readyTeleportItems.contains(itemId);
	}

	public boolean isReadyTeleportSprite(int spriteId)
	{
		return readyTeleportSprites.contains(spriteId);
	}

	public boolean isReadyTeleportSpell(int widgetId)
	{
		return readyTeleportSpells.contains(widgetId);
	}

	private static void rememberReadyIcons(HerbTeleport teleport, Set<Integer> items, Set<Integer> sprites,
		Set<Integer> spells)
	{
		for (HerbTeleport.Icon icon : teleport.getIcons())
		{
			if (icon == null || icon.getId() <= 0)
			{
				continue;
			}
			if (icon.isSprite())
			{
				sprites.add(icon.getId());
				rememberSpell(icon.getId(), spells);
			}
			else
			{
				items.add(icon.getId());
				if (icon.getId() == ItemID.ASTRALRUNE)
				{
					spells.add(InterfaceID.MagicSpellbook.TELEPORT_HARMONY_ISLAND);
				}
			}
		}
	}

	private static void rememberSpell(int spriteId, Set<Integer> spells)
	{
		if (spriteId == SPRITE_VARROCK)
		{
			spells.add(InterfaceID.MagicSpellbook.VARROCK_TELEPORT);
		}
		else if (spriteId == SPRITE_CAMELOT)
		{
			spells.add(InterfaceID.MagicSpellbook.CAMELOT_TELEPORT);
			spells.add(InterfaceID.MagicSpellbook.TELE_CATHER);
			spells.add(InterfaceID.MagicSpellbook.TELE_GROUP_CATHERBY);
		}
		else if (spriteId == SPRITE_ARDOUGNE)
		{
			spells.add(InterfaceID.MagicSpellbook.ARDOUGNE_TELEPORT);
		}
		else if (spriteId == SPRITE_TROLLHEIM)
		{
			spells.add(InterfaceID.MagicSpellbook.TROLLHEIM_TELEPORT);
		}
		else if (spriteId == SPRITE_HOUSE)
		{
			spells.add(InterfaceID.MagicSpellbook.TELEPORT_TO_YOUR_HOUSE);
		}
		else if (spriteId == SPRITE_FORTIS)
		{
			spells.add(InterfaceID.MagicSpellbook.FORTIS_TELEPORT);
		}
	}

	public HerbTeleport forAllotment(AllotmentPatch patch)
	{
		if (patch == null)
		{
			return HerbTeleport.missing();
		}
		switch (patch.getTeleportGroup())
		{
			case FARMING_GUILD:
				return farmingGuild();
			case ARDOUGNE:
				return ardougne();
			case CATHERBY:
				return catherby();
			case FALADOR:
				return falador();
			case HOSIDIUS:
				return hosidius();
			case MORYTANIA:
				return morytania();
			case FORTIS:
				return fortis();
			case PRIF:
				return prif();
			case HARMONY:
				return harmony();
			default:
				return HerbTeleport.missing();
		}
	}

	public HerbTeleport forPatch(HerbPatch patch)
	{
		switch (patch)
		{
			case FARMING_GUILD:
				return farmingGuild();
			case ARDOUGNE:
				return ardougne();
			case CATHERBY:
				return catherby();
			case FALADOR:
				return falador();
			case HOSIDIUS:
				return hosidius();
			case MORYTANIA:
				return morytania();
			case TROLL_STRONGHOLD:
				return trollStronghold();
			case WEISS:
				return weiss();
			case HARMONY:
				return harmony();
			case FORTIS:
				return fortis();
			default:
				return HerbTeleport.missing();
		}
	}

	private HerbTeleport farmingGuild()
	{
		int cape = firstOwned(FARM_CAPES);
		if (cape != 0)
		{
			return HerbTeleport.direct(cape, cape == ItemID.SKILLCAPE_MAX
				? "Max cape to Farming Guild"
				: "Farming cape");
		}
		int necklace = firstOwned(SKILLS_NECKLACES);
		if (necklace != 0)
		{
			return HerbTeleport.direct(necklace, "Skills necklace");
		}
		HerbTeleport.Icon poh = pohMethod();
		if (poh != null && jewelleryBoxHasSkills())
		{
			return HerbTeleport.chain(poh, ItemID.JEWL_NECKLACE_OF_SKILLS_4,
				pohLabel(poh) + " → Jewellery box (Farming Guild)");
		}
		if (guildSpiritTreeReady && finished(Quest.TREE_GNOME_VILLAGE))
		{
			if (has(ItemID.MM2_ROYAL_SEED_POD))
			{
				return HerbTeleport.direct(ItemID.MM2_ROYAL_SEED_POD, "Royal seed pod → Farming Guild spirit tree");
			}
			HerbTeleport varrock = varrockTeleport();
			if (varrock != null && !varrock.getIcons().isEmpty())
			{
				return HerbTeleport.chain(varrock.getIcons().get(0), ItemID.FGUILD_DUMMY_SPIRIT_TREE,
					varrock.getTooltip() + " → Farming Guild spirit tree");
			}
		}
		return HerbTeleport.missing();
	}

	private HerbTeleport ardougne()
	{
		int cloak = firstOwned(ARDY_CLOAKS);
		if (cloak != 0)
		{
			return HerbTeleport.direct(cloak, "Ardougne cloak");
