	private boolean nexusHas(String needle)
	{
		scanNexus();
		return matchesSavedNexus(needle.toLowerCase(Locale.ROOT));
	}

	private void scanNexus()
	{
		try
		{
			EnumComposition dests = client.getEnum(PORTAL_NEXUS_ENUM);
			if (dests == null)
			{
				return;
			}
			Set<String> found = new HashSet<>();
			collectNexusSlots(dests, NEXUS_SLOTS, found);
			collectNexusSlots(dests, NEXUS_TEMP_SLOTS, found);
			boolean changed = nexusDests.addAll(found);
			if (!found.isEmpty())
			{
				changed |= forgetUnconfirmedPrif(found);
			}
			if (changed)
			{
				saveNexus();
			}
		}
		catch (Exception ignored)
		{
		}
	}

	private void collectNexusSlots(EnumComposition dests, int[] slots, Set<String> found)
	{
		for (int slot : slots)
		{
			int value = client.getVarbitValue(slot);
			if (value <= 0)
			{
				continue;
			}
			String name = nexusName(dests, value).toLowerCase(Locale.ROOT);
			if (!name.isEmpty())
			{
				found.add(name);
			}
		}
	}

	private boolean forgetUnconfirmedPrif(Set<String> found)
	{
		for (String name : found)
		{
			if (matchesNexus("prifddinas", name))
			{
				return false;
			}
		}
		return nexusDests.removeIf(name -> matchesNexus("prifddinas", name));
	}

	private void rememberNexus(String destination)
	{
		if (destination == null || destination.isEmpty())
		{
			return;
		}
		String name = destination.toLowerCase(Locale.ROOT);
		if (matchesNexus("prifddinas", name))
		{
			return;
		}
		if (nexusDests.add(name))
		{
			saveNexus();
		}
	}

	private void saveNexus()
	{
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, NEXUS_KEY,
			String.join(",", nexusDests));
	}

	private boolean matchesSavedNexus(String want)
	{
		for (String name : nexusDests)
		{
			if (matchesNexus(want, name))
			{
				return true;
			}
		}
		return false;
	}

	private void observeHouseLocation(int regionId, int convertedRegion, boolean instanced)
	{
		if (!instanced && (regionId == 6966 || convertedRegion == 6966))
		{
			setHouseLocation(HOUSE_HOSIDIUS);
			return;
		}
		int loc = client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION);
		if (loc == HOUSE_HOSIDIUS)
		{
			setHouseLocation(HOUSE_HOSIDIUS);
		}
	}

	private void observeArrival(int regionId)
	{
		if (isHosidiusArrival(regionId))
		{
			setHouseLocation(HOUSE_HOSIDIUS);
		}
	}

	private boolean isHosidiusArrival(int regionId)
	{
		for (int portalRegion : HOSIDIUS_HOUSE_PORTAL_REGIONS)
		{
			if (regionId == portalRegion)
			{
				return true;
			}
		}
		return HerbPatch.HOSIDIUS.containsRegion(regionId);
	}

	private void setHouseLocation(int location)
	{
		if (houseLocation == location)
		{
			return;
		}
		houseLocation = location;
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, HOUSE_KEY, location);
	}

	private boolean houseInHosidius()
	{
		if (houseLocation == HOUSE_HOSIDIUS)
		{
			return true;
		}
		Player player = client.getLocalPlayer();
		if (player != null && player.getWorldLocation() != null && !client.isInInstancedRegion()
			&& player.getWorldLocation().getRegionID() == 6966)
		{
			return true;
		}
		return client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION) == HOUSE_HOSIDIUS;
	}

	private void scanWidgets()
	{
		try
		{
			for (WidgetNode node : client.getComponentTable())
			{
				Widget widget = client.getWidget(node.getId(), 0);
				scanWidgetTree(widget);
			}
		}
		catch (Exception ignored)
		{
		}
	}

	private void scanWidgetTree(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return;
		}
		observeNexusText(widget.getText());
		observeNexusText(widget.getName());
		Widget[][] groups = {
			widget.getDynamicChildren(),
			widget.getStaticChildren(),
			widget.getNestedChildren()
		};
		for (Widget[] children : groups)
		{
			if (children == null)
			{
				continue;
			}
			for (Widget child : children)
			{
				scanWidgetTree(child);
			}
		}
	}

	private String nexusName(EnumComposition dests, int value)
	{
		try
		{
			String name = dests.getStringValue(value);
			if (name != null && !name.isEmpty())
			{
				return name;
			}
			int structId = dests.getIntValue(value);
			if (structId <= 0)
			{
				structId = value;
			}
			String fromStruct = structName(structId);
			if (!fromStruct.isEmpty())
			{
				return fromStruct;
			}
			return structName(value);
		}
		catch (Exception ignored)
		{
			return structName(value);
		}
	}

	private String structName(int structId)
	{
		if (structId <= 0)
		{
			return "";
		}
		try
		{
			StructComposition struct = client.getStructComposition(structId);
			if (struct == null)
			{
				return "";
			}
			String name = struct.getStringValue(ParamID.SPELL_NAME);
			return name == null ? "" : name;
		}
		catch (Exception ignored)
		{
			return "";
		}
	}

	private static boolean matchesNexus(String want, String name)
	{
		if (name == null || name.isEmpty())
		{
			return false;
		}
		String lower = name.toLowerCase();
		if ("ardougne".equals(want))
		{
			return (lower.contains("ardougne") && !lower.contains("west")) || lower.contains("east ardougne");
		}
		if ("weiss".equals(want))
		{
			return lower.contains("weiss") || lower.contains("icy basalt");
		}
		if ("troll stronghold".equals(want))
		{
			return lower.contains("troll stronghold") || lower.contains("stony basalt");
		}
		if ("prifddinas".equals(want))
		{
			return lower.contains("prifddinas");
		}
		return lower.contains(want);
	}

	private boolean canCast(int level, boolean unlocked, int law, int water, int earth, int fire, int air, int astral)
	{
		if (!unlocked)
		{
			return false;
		}
		if (client.getBoostedSkillLevel(Skill.MAGIC) < level)
		{
			return false;
		}
		return runeCount(ItemID.LAWRUNE, false) >= law
			&& runeCount(ItemID.WATERRUNE, true) >= water
			&& runeCount(ItemID.EARTHRUNE, true) >= earth
			&& runeCount(ItemID.FIRERUNE, true) >= fire
			&& runeCount(ItemID.AIRRUNE, true) >= air
			&& runeCount(ItemID.ASTRALRUNE, false) >= astral;
	}

	private int runeCount(int runeId, boolean elemental)
	{
		if (elemental && providesElement(runeId))
		{
			return 1000;
		}
		int total = count(runeId);
		if (runeId == ItemID.AIRRUNE)
		{
			total += count(ItemID.MISTRUNE) + count(ItemID.DUSTRUNE) + count(ItemID.SMOKERUNE);
		}
		else if (runeId == ItemID.WATERRUNE)
		{
			total += count(ItemID.MISTRUNE) + count(ItemID.MUDRUNE) + count(ItemID.STEAMRUNE);
		}
		else if (runeId == ItemID.EARTHRUNE)
		{
			total += count(ItemID.DUSTRUNE) + count(ItemID.MUDRUNE) + count(ItemID.LAVARUNE);
		}
		else if (runeId == ItemID.FIRERUNE)
		{
			total += count(ItemID.LAVARUNE) + count(ItemID.STEAMRUNE) + count(ItemID.SMOKERUNE) + count(ItemID.SUNFIRERUNE);
		}
		total += pouchCount(runeId, elemental);
		return total;
	}

	private int pouchCount(int runeId, boolean elemental)
	{
		if (!carryingRunePouch())
		{
			return 0;
		}
		int total = 0;
		for (int i = 0; i < POUCH_TYPES.length; i++)
		{
			int type = client.getVarbitValue(POUCH_TYPES[i]);
			int amount = client.getVarbitValue(POUCH_QTY[i]);
			if (type <= 0 || amount <= 0)
			{
				continue;
			}
			int itemId = pouchRuneItemId(type);
			if (itemId == runeId || (elemental && combinationProvides(itemId, runeId)))
			{
				total += amount;
			}
		}
		return total;
	}

	private int pouchRuneItemId(int type)
	{
		if (type > 0 && type < POUCH_RUNE_BY_TYPE.length && POUCH_RUNE_BY_TYPE[type] != 0)
		{
			return POUCH_RUNE_BY_TYPE[type];
		}
		try
		{
			EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
			if (runes != null)
			{
				int itemId = runes.getIntValue(type);
				if (itemId > 0)
				{
					return itemId;
				}
			}
		}
		catch (Exception ignored)
		{
		}
		return type > POUCH_RUNE_BY_TYPE.length ? type : 0;
	}

	private static boolean combinationProvides(int itemId, int runeId)
	{
		if (runeId == ItemID.AIRRUNE)
		{
			return itemId == ItemID.MISTRUNE || itemId == ItemID.DUSTRUNE || itemId == ItemID.SMOKERUNE;
		}
		if (runeId == ItemID.WATERRUNE)
		{
			return itemId == ItemID.MISTRUNE || itemId == ItemID.MUDRUNE || itemId == ItemID.STEAMRUNE;
		}
		if (runeId == ItemID.EARTHRUNE)
		{
			return itemId == ItemID.DUSTRUNE || itemId == ItemID.MUDRUNE || itemId == ItemID.LAVARUNE;
		}
		if (runeId == ItemID.FIRERUNE)
		{
			return itemId == ItemID.LAVARUNE || itemId == ItemID.STEAMRUNE || itemId == ItemID.SMOKERUNE
				|| itemId == ItemID.SUNFIRERUNE;
		}
		return false;
	}

	private boolean providesElement(int runeId)
	{
		if (runeId == ItemID.AIRRUNE)
		{
			return hasAny(AIR_STAFFS);
		}
		if (runeId == ItemID.WATERRUNE)
		{
			return hasAny(WATER_STAFFS);
		}
		if (runeId == ItemID.EARTHRUNE)
		{
			return hasAny(EARTH_STAFFS);
		}
		if (runeId == ItemID.FIRERUNE)
		{
			return hasAny(FIRE_STAFFS);
		}
		return false;
	}

	private boolean finished(Quest quest)
	{
		return quest == Quest.TREE_GNOME_VILLAGE && treeGnomeVillageFinished;
	}

	private boolean carryingRunePouch()
	{
		return hasPouch(inv()) || hasPouch(worn());
	}

	private boolean hasPouch(ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return false;
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			if (item.getId() == ItemID.BH_RUNE_POUCH)
			{
				return true;
			}
			String name = client.getItemDefinition(item.getId()).getName();
			if (name != null && name.toLowerCase(Locale.ROOT).contains("rune pouch"))
			{
				return true;
			}
		}
		return false;
	}

	private boolean has(int itemId)
	{
		return count(itemId) > 0;
	}

	private boolean hasAny(Set<Integer> itemIds)
	{
		return firstOwned(itemIds) != 0;
	}

	private int firstOwned(Set<Integer> itemIds)
	{
		for (int itemId : itemIds)
		{
			if (count(itemId) > 0)
			{
				return itemId;
			}
		}
		return 0;
	}

	private int count(int itemId)
	{
		return owned(inv(), itemId) + owned(worn(), itemId);
	}

	private static int owned(ItemContainer container, int itemId)
	{
		if (container == null)
		{
			return 0;
		}
		Item[] items = container.getItems();
		if (items == null)
		{
			return 0;
		}
		int total = 0;
		for (Item item : items)
		{
			if (item != null && item.getId() == itemId)
			{
				total += Math.max(item.getQuantity(), 1);
			}
		}
		return total;
	}

	private ItemContainer inv()
	{
		return client.getItemContainer(InventoryID.INV);
	}

	private ItemContainer worn()
	{
		return client.getItemContainer(InventoryID.WORN);
	}
}

