package com.potionprofitpro.stats;

import com.potionprofitpro.data.PrayerPotionItems;
import java.util.function.IntToLongFunction;
import java.util.regex.Pattern;
import net.runelite.api.ItemContainer;

public final class JewelleryTracker
{
	private static final Pattern CUT_OPAL = Pattern.compile("(?i)you cut the opal");
	private static final Pattern CUT_JADE = Pattern.compile("(?i)you cut the jade");
	private static final Pattern SMELT_SILVER = Pattern.compile(
		"(?i)you (?:retrieve a bar of silver|smelt (?:the )?silver|superheat the ore)");
	private static final Pattern CRAFT_OPAL = Pattern.compile("(?i)you make an opal amulet");
	private static final Pattern CRAFT_JADE = Pattern.compile("(?i)you make a jade amulet");
	private static final Pattern STRING_AMULET = Pattern.compile(
		"(?i)you (?:add a string to the amulet|put some string on your amulet)");
	private static final Pattern ENCHANT_OPAL = Pattern.compile("(?i)you enchant the opal amulet");
	private static final Pattern ENCHANT_JADE = Pattern.compile("(?i)you enchant the jade amulet");

	private boolean ready;
	private boolean pendingCutOpal;
	private boolean pendingCutJade;
	private boolean pendingSmelt;
	private boolean pendingCraftOpal;
	private boolean pendingCraftJade;
	private boolean pendingString;
	private boolean pendingEnchantOpal;
	private boolean pendingEnchantJade;
	private int lastUncutOpal;
	private int lastOpal;
	private int lastUncutJade;
	private int lastJade;
	private int lastOre;
	private int lastBar;
	private int lastUnstrungOpal;
	private int lastStrungOpal;
	private int lastUnstrungJade;
	private int lastStrungJade;
	private int lastWool;
	private int lastBounty;
	private int lastChemistry;

	public static LedgerType geSpendType(int itemId)
	{
		if (PrayerPotionItems.BOUNTY_CRAFT_IDS.contains(itemId))
		{
			return LedgerType.BOUNTY_SPEND;
		}
		if (PrayerPotionItems.ALCH_CRAFT_IDS.contains(itemId))
		{
			return LedgerType.ALCH_SPEND;
		}
		if (PrayerPotionItems.SHARED_JEWELLERY_IDS.contains(itemId))
		{
			return LedgerType.SPEND;
		}
		return null;
	}

	public void onChat(String message)
	{
		if (CUT_OPAL.matcher(message).find())
		{
			pendingCutOpal = true;
		}
		else if (CUT_JADE.matcher(message).find())
		{
			pendingCutJade = true;
		}
		else if (SMELT_SILVER.matcher(message).find())
		{
			pendingSmelt = true;
		}
		else if (CRAFT_OPAL.matcher(message).find())
		{
			pendingCraftOpal = true;
		}
		else if (CRAFT_JADE.matcher(message).find())
		{
			pendingCraftJade = true;
		}
		else if (STRING_AMULET.matcher(message).find())
		{
			pendingString = true;
		}
		else if (ENCHANT_OPAL.matcher(message).find())
		{
			pendingEnchantOpal = true;
		}
		else if (ENCHANT_JADE.matcher(message).find())
		{
			pendingEnchantJade = true;
		}
	}

	public void snapshot(ItemContainer inventory)
	{
		read(inventory);
		ready = true;
	}

	public void record(ItemContainer inventory, boolean storageOpen, IntToLongFunction prices, Booker booker)
	{
		if (!ready || storageOpen)
		{
			read(inventory);
			return;
		}

		int uncutOpal = qty(inventory, PrayerPotionItems.UNCUT_OPAL);
		int opal = qty(inventory, PrayerPotionItems.OPAL);
		int uncutJade = qty(inventory, PrayerPotionItems.UNCUT_JADE);
		int jade = qty(inventory, PrayerPotionItems.JADE);
		int ore = qty(inventory, PrayerPotionItems.SILVER_ORE);
		int bar = qty(inventory, PrayerPotionItems.SILVER_BAR);
		int unstrungOpal = qty(inventory, PrayerPotionItems.UNSTRUNG_OPAL_AMULET);
		int strungOpal = qty(inventory, PrayerPotionItems.STRUNG_OPAL_AMULET);
		int unstrungJade = qty(inventory, PrayerPotionItems.UNSTRUNG_JADE_AMULET);
		int strungJade = qty(inventory, PrayerPotionItems.STRUNG_JADE_AMULET);
		int wool = qty(inventory, PrayerPotionItems.BALL_OF_WOOL);
		int bounty = qty(inventory, PrayerPotionItems.AMULET_OF_BOUNTY);
		int chemistry = qty(inventory, PrayerPotionItems.AMULET_OF_CHEMISTRY);

		cutSpread(pendingCutOpal || (uncutOpal < lastUncutOpal && opal > lastOpal),
			Math.min(Math.max(0, lastUncutOpal - uncutOpal), Math.max(0, opal - lastOpal)),
			PrayerPotionItems.OPAL, PrayerPotionItems.UNCUT_OPAL,
			LedgerType.BOUNTY_SPEND, LedgerType.BOUNTY_GAIN, prices, booker);
		pendingCutOpal = false;

		cutSpread(pendingCutJade || (uncutJade < lastUncutJade && jade > lastJade),
			Math.min(Math.max(0, lastUncutJade - uncutJade), Math.max(0, jade - lastJade)),
			PrayerPotionItems.JADE, PrayerPotionItems.UNCUT_JADE,
			LedgerType.ALCH_SPEND, LedgerType.ALCH_GAIN, prices, booker);
		pendingCutJade = false;

		int smelted = Math.min(Math.max(0, lastOre - ore), Math.max(0, bar - lastBar));
		if (smelted > 0 && (pendingSmelt || lastOre > ore))
		{
			bookSpread(smelted,
				prices.applyAsLong(PrayerPotionItems.SILVER_BAR) - prices.applyAsLong(PrayerPotionItems.SILVER_ORE),
				PrayerPotionItems.SILVER_BAR, LedgerType.SPEND, LedgerType.GAIN, booker);
		}
		pendingSmelt = false;

		int craftedOpal = Math.min(Math.max(0, unstrungOpal - lastUnstrungOpal),
			Math.min(Math.max(0, lastBar - bar), Math.max(0, lastOpal - opal)));
		if (craftedOpal > 0)
		{
			long spread = prices.applyAsLong(PrayerPotionItems.UNSTRUNG_OPAL_AMULET)
				- prices.applyAsLong(PrayerPotionItems.SILVER_BAR)
				- prices.applyAsLong(PrayerPotionItems.OPAL);
			bookSpread(craftedOpal, spread, PrayerPotionItems.UNSTRUNG_OPAL_AMULET,
				LedgerType.BOUNTY_SPEND, LedgerType.BOUNTY_GAIN, booker);
		}
		pendingCraftOpal = false;

		int craftedJade = Math.min(Math.max(0, unstrungJade - lastUnstrungJade),
			Math.min(Math.max(0, lastBar - bar), Math.max(0, lastJade - jade)));
		if (craftedJade > 0)
		{
			long spread = prices.applyAsLong(PrayerPotionItems.UNSTRUNG_JADE_AMULET)
				- prices.applyAsLong(PrayerPotionItems.SILVER_BAR)
				- prices.applyAsLong(PrayerPotionItems.JADE);
			bookSpread(craftedJade, spread, PrayerPotionItems.UNSTRUNG_JADE_AMULET,
				LedgerType.ALCH_SPEND, LedgerType.ALCH_GAIN, booker);
		}
		pendingCraftJade = false;

		stringSpread(pendingString || (wool < lastWool && unstrungOpal < lastUnstrungOpal && strungOpal > lastStrungOpal),
			Math.min(Math.max(0, lastUnstrungOpal - unstrungOpal), Math.max(0, strungOpal - lastStrungOpal)),
			PrayerPotionItems.STRUNG_OPAL_AMULET, PrayerPotionItems.UNSTRUNG_OPAL_AMULET,
			LedgerType.BOUNTY_SPEND, LedgerType.BOUNTY_GAIN, prices, booker);
		stringSpread(pendingString || (wool < lastWool && unstrungJade < lastUnstrungJade && strungJade > lastStrungJade),
			Math.min(Math.max(0, lastUnstrungJade - unstrungJade), Math.max(0, strungJade - lastStrungJade)),
			PrayerPotionItems.STRUNG_JADE_AMULET, PrayerPotionItems.UNSTRUNG_JADE_AMULET,
			LedgerType.ALCH_SPEND, LedgerType.ALCH_GAIN, prices, booker);
		pendingString = false;

		int madeBounty = Math.max(0, bounty - lastBounty);
		int usedStrungOpal = Math.max(0, lastStrungOpal - strungOpal);
		if (madeBounty > 0 && (pendingEnchantOpal || usedStrungOpal > 0))
		{
			enchant(madeBounty, PrayerPotionItems.AMULET_OF_BOUNTY, PrayerPotionItems.STRUNG_OPAL_AMULET,
				prices.applyAsLong(PrayerPotionItems.COSMIC_RUNE) + prices.applyAsLong(PrayerPotionItems.WATER_RUNE),
				LedgerType.BOUNTY_SPEND, LedgerType.BOUNTY_GAIN, prices, booker);
		}
		pendingEnchantOpal = false;

		int chemistryMade = Math.max(0, chemistry - lastChemistry);
		int usedStrungJade = Math.max(0, lastStrungJade - strungJade);
		if (chemistryMade > 0 && (pendingEnchantJade || usedStrungJade > 0))
		{
			enchant(chemistryMade, PrayerPotionItems.AMULET_OF_CHEMISTRY, PrayerPotionItems.STRUNG_JADE_AMULET,
				prices.applyAsLong(PrayerPotionItems.COSMIC_RUNE) + 3 * prices.applyAsLong(PrayerPotionItems.AIR_RUNE),
				LedgerType.ALCH_SPEND, LedgerType.ALCH_GAIN, prices, booker);
		}
		pendingEnchantJade = false;

		lastUncutOpal = uncutOpal;
		lastOpal = opal;
		lastUncutJade = uncutJade;
		lastJade = jade;
		lastOre = ore;
		lastBar = bar;
		lastUnstrungOpal = unstrungOpal;
		lastStrungOpal = strungOpal;
		lastUnstrungJade = unstrungJade;
		lastStrungJade = strungJade;
		lastWool = wool;
		lastBounty = bounty;
		lastChemistry = chemistry;
	}

	private void read(ItemContainer inventory)
	{
		lastUncutOpal = qty(inventory, PrayerPotionItems.UNCUT_OPAL);
		lastOpal = qty(inventory, PrayerPotionItems.OPAL);
		lastUncutJade = qty(inventory, PrayerPotionItems.UNCUT_JADE);
		lastJade = qty(inventory, PrayerPotionItems.JADE);
		lastOre = qty(inventory, PrayerPotionItems.SILVER_ORE);
		lastBar = qty(inventory, PrayerPotionItems.SILVER_BAR);
		lastUnstrungOpal = qty(inventory, PrayerPotionItems.UNSTRUNG_OPAL_AMULET);
		lastStrungOpal = qty(inventory, PrayerPotionItems.STRUNG_OPAL_AMULET);
		lastUnstrungJade = qty(inventory, PrayerPotionItems.UNSTRUNG_JADE_AMULET);
		lastStrungJade = qty(inventory, PrayerPotionItems.STRUNG_JADE_AMULET);
		lastWool = qty(inventory, PrayerPotionItems.BALL_OF_WOOL);
		lastBounty = qty(inventory, PrayerPotionItems.AMULET_OF_BOUNTY);
		lastChemistry = qty(inventory, PrayerPotionItems.AMULET_OF_CHEMISTRY);
	}

	private void cutSpread(boolean matched, int qty, int cutId, int uncutId,
		LedgerType spendType, LedgerType gainType, IntToLongFunction prices, Booker booker)
	{
		if (!matched || qty <= 0)
		{
			return;
		}
		bookSpread(qty, prices.applyAsLong(cutId) - prices.applyAsLong(uncutId), cutId, spendType, gainType, booker);
	}

	private void stringSpread(boolean matched, int qty, int strungId, int unstrungId,
		LedgerType spendType, LedgerType gainType, IntToLongFunction prices, Booker booker)
	{
		if (!matched || qty <= 0)
		{
			return;
		}
		long spread = prices.applyAsLong(strungId) - prices.applyAsLong(unstrungId)
			- prices.applyAsLong(PrayerPotionItems.BALL_OF_WOOL);
		bookSpread(qty, spread, strungId, spendType, gainType, booker);
	}

	private void enchant(int qty, int finishedId, int strungId, long runeCost,
		LedgerType spendType, LedgerType gainType, IntToLongFunction prices, Booker booker)
	{
		if (qty <= 0)
		{
			return;
		}
		long runes = Math.max(0L, runeCost) * qty;
		if (runes > 0)
		{
			booker.add(spendType, PrayerPotionItems.COSMIC_RUNE, qty, runes);
		}
		bookSpread(qty, prices.applyAsLong(finishedId) - prices.applyAsLong(strungId),
			finishedId, spendType, gainType, booker);
	}

	private static void bookSpread(int qty, long unitDiff, int itemId,
		LedgerType spendType, LedgerType gainType, Booker booker)
	{
		if (qty <= 0 || unitDiff == 0)
		{
			return;
		}
		long gp = Math.abs(unitDiff) * qty;
		if (unitDiff > 0)
		{
			booker.add(gainType, itemId, qty, gp);
		}
		else
		{
			booker.add(spendType, itemId, qty, gp);
		}
	}

	private static int qty(ItemContainer inventory, int itemId)
	{
		return PrayerPotionItems.quantityOf(inventory, itemId);
	}

	@FunctionalInterface
	public interface Booker
	{
		void add(LedgerType type, int itemId, int quantity, long gp);
	}
}

