@Slf4j
@Singleton
public class ProfitStore
{
	private static final String KEY = "prayerLedger";
	private static final String SYNC_KEY = "profitSync";
	private static final int MAX_RECENT = 400;
	private static final long DAY = 86_400_000L;
	private static final long WEEK = 7 * DAY;
	private static final long RUN_WINDOW = 40 * 60 * 1000L;
	private static final long SAVE_INTERVAL_MS = 2000L;
	public static final int MAX_HARVEST_DELTA = 8;
	private static final DateTimeFormatter CSV_TIME = DateTimeFormatter.ISO_OFFSET_DATE_TIME.withZone(ZoneOffset.UTC);

	@Inject
	private ConfigManager configManager;

	@Inject
	private Gson gson;

	@Inject
	private PotionProfitProPlugin plugin;

	private ProfitLedger ledger = new ProfitLedger();
	private String lastCloudJson;
	private boolean dirty;
	private long lastSaveAt;

	public void load()
	{
		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return;
		}

		ProfitLedger fromFile = null;
		try
		{
			fromFile = readLedger(ledgerFile(profile));
		}
		catch (IOException ex)
		{
			log.warn("Unable to open profit ledger", ex);
		}
		if (fromFile != null)
		{
			ledger = fromFile;
		}
		else
		{
			ProfitLedger fromLegacy = parseLedger(configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY));
			ledger = fromLegacy != null ? fromLegacy : new ProfitLedger();
			if (fromLegacy == null)
			{
				ledger.setBestsInitialized(true);
			}
		}

		mergeFrom(parseLedger(configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY)));
		mergeCloud(parseCloud(configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, SYNC_KEY)));
		seedBestsIfNeeded();
		reconcileHarvestRuns();
		save();
	}

	public void persist()
	{
		saveIfDue(true);
	}

	public void flushIfDue()
	{
		saveIfDue(false);
	}

	public boolean isGeTracked()
	{
		return ledger.isGeTracked();
	}

	public void copyGeSlots(int[] soldQty, long[] spent, int[] boughtQty, long[] boughtGp, int[] itemId)
	{
		copyGeArray(ledger.getGeSoldQty(), soldQty);
		copyGeArray(ledger.getGeSpent(), spent);
		copyGeArray(ledger.getGeBoughtQty(), boughtQty);
		copyGeArray(ledger.getGeBoughtGp(), boughtGp);
		copyGeArray(ledger.getGeItemId(), itemId);
	}

	public void saveGeSlots(int[] soldQty, long[] spent, int[] boughtQty, long[] boughtGp, int[] itemId)
	{
		ledger.setGeSoldQty(copyGeArray(soldQty));
		ledger.setGeSpent(copyGeArray(spent));
		ledger.setGeBoughtQty(copyGeArray(boughtQty));
		ledger.setGeBoughtGp(copyGeArray(boughtGp));
		ledger.setGeItemId(copyGeArray(itemId));
		save();
	}

	public void markGeTracked()
	{
		if (ledger.isGeTracked())
		{
			return;
		}
		ledger.setGeTracked(true);
		save();
	}

	private static void copyGeArray(int[] source, int[] dest)
	{
		if (dest == null)
		{
			return;
		}
		Arrays.fill(dest, 0);
		if (source == null)
		{
			return;
		}
		int length = Math.min(source.length, dest.length);
		System.arraycopy(source, 0, dest, 0, length);
	}

	private static int[] copyGeArray(int[] source)
	{
		int[] copy = new int[8];
		copyGeArray(source, copy);
		return copy;
	}

	private static void copyGeArray(long[] source, long[] dest)
	{
		if (dest == null)
		{
			return;
		}
		Arrays.fill(dest, 0L);
		if (source == null)
		{
			return;
		}
		int length = Math.min(source.length, dest.length);
		System.arraycopy(source, 0, dest, 0, length);
	}

	private static long[] copyGeArray(long[] source)
	{
		long[] copy = new long[8];
		copyGeArray(source, copy);
		return copy;
	}

	public void add(LedgerType type, int itemId, int quantity, long gp)
	{
		ledger.getEntries().add(new LedgerEntry(Instant.now().toEpochMilli(), type, itemId, quantity, gp));
		if (type == LedgerType.HARVEST)
		{
			if (quantity > MAX_HARVEST_DELTA)
			{
				save();
				return;
			}
			recordRunHarvest(itemId, quantity);
		}
		dirty = true;
		saveIfDue(false);
	}

	public void reset()
	{
		ledger = new ProfitLedger();
		ledger.setBestsInitialized(true);
		save();
	}

	public void resetSection(StatSection section)
	{
		long now = Instant.now().toEpochMilli();
		switch (section)
		{
			case DAY:
				ledger.setDayResetAt(now);
				ledger.setCloudLastDaySpent(0);
				ledger.setCloudLastDayGained(0);
				break;
			case WEEK:
				ledger.setWeekResetAt(now);
				ledger.setCloudLastWeekSpent(0);
				ledger.setCloudLastWeekGained(0);
				break;
			case ALL:
				ledger.setAllResetAt(now);
				ledger.setCloudAllSpent(0);
				ledger.setCloudAllGained(0);
				break;
			case AVERAGES:
				ledger.setAveragesResetAt(now);
				ledger.setCloudAveragesNet(0);
				ledger.setCloudAveragesStart(now);
				break;
			case BEST_RUN:
				ledger.setBestRanarr(0);
				ledger.setBestSnapdragon(0);
				ledger.setBestToadflax(0);
				ledger.setBestSnape(0);
				ledger.setRanarrRunStart(0);
				ledger.setRanarrRunCount(0);
				ledger.setSnapdragonRunStart(0);
				ledger.setSnapdragonRunCount(0);
				ledger.setToadflaxRunStart(0);
				ledger.setToadflaxRunCount(0);
				ledger.setSnapeRunStart(0);
				ledger.setSnapeRunCount(0);
				ledger.setBestResetAt(now);
				ledger.setBestsInitialized(true);
				break;
			case ALCH:
				ledger.setAlchResetAt(now);
				ledger.setAlchChargesUsed(0);
				ledger.setCloudAlchSpent(0);
				ledger.setCloudAlchGained(0);
				break;
			case BOUNTY:
				ledger.setBountyResetAt(now);
				ledger.setBountyChargesUsed(0);
				ledger.setCloudBountySpent(0);
				ledger.setCloudBountyGained(0);
				break;
		}
		save();
	}

