	public ProfitSummary summarize()
	{
		long now = Instant.now().toEpochMilli();
		long spentDay = 0;
		long gainedDay = 0;
		long spentWeek = 0;
		long gainedWeek = 0;
		long spentAll = 0;
		long gainedAll = 0;
		long alchSpent = 0;
		long alchGained = 0;
		long bountySpent = 0;
		long bountyGained = 0;
		long averagesSpent = 0;
		long averagesGained = 0;
		long averagesStart = 0;
		long dayFrom = Math.max(now - DAY, ledger.getDayResetAt());
		long weekFrom = Math.max(now - WEEK, ledger.getWeekResetAt());
		long allFrom = ledger.getAllResetAt();
		long averagesFrom = ledger.getAveragesResetAt();
		long alchFrom = ledger.getAlchResetAt();
		long bountyFrom = ledger.getBountyResetAt();

		for (LedgerEntry entry : ledger.getEntries())
		{
			LedgerType type = entry.getType();
			if (type == null)
			{
				continue;
			}

			long time = entry.getTime();
			boolean inDay = time > dayFrom;
			boolean inWeek = time > weekFrom;
			boolean inAll = time > allFrom;
			boolean inAverages = time > averagesFrom;

			boolean sharedJewellery = PrayerPotionItems.SHARED_JEWELLERY_IDS.contains(entry.getItemId());
			switch (type)
			{
				case SPEND:
					if (inAll)
					{
						spentAll += entry.getGp();
					}
					if (inWeek)
					{
						spentWeek += entry.getGp();
					}
					if (inDay)
					{
						spentDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesSpent += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					if (sharedJewellery)
					{
						if (time > alchFrom)
						{
							alchSpent += entry.getGp();
						}
						if (time > bountyFrom)
						{
							bountySpent += entry.getGp();
						}
					}
					break;
				case GAIN:
					if (inAll)
					{
						gainedAll += entry.getGp();
					}
					if (inWeek)
					{
						gainedWeek += entry.getGp();
					}
					if (inDay)
					{
						gainedDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesGained += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					if (sharedJewellery)
					{
						if (time > alchFrom)
						{
							alchGained += entry.getGp();
						}
						if (time > bountyFrom)
						{
							bountyGained += entry.getGp();
						}
					}
					break;
				case HARVEST:
					break;
				case ALCH_SPEND:
					if (time > alchFrom)
					{
						alchSpent += entry.getGp();
					}
					if (inAll)
					{
						spentAll += entry.getGp();
					}
					if (inWeek)
					{
						spentWeek += entry.getGp();
					}
					if (inDay)
					{
						spentDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesSpent += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					break;
				case ALCH_GAIN:
					if (time > alchFrom)
					{
						alchGained += entry.getGp();
					}
					if (inAll)
					{
						gainedAll += entry.getGp();
					}
					if (inWeek)
					{
						gainedWeek += entry.getGp();
					}
					if (inDay)
					{
						gainedDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesGained += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					break;
				case BOUNTY_SPEND:
					if (time > bountyFrom)
					{
						bountySpent += entry.getGp();
					}
					if (inAll)
					{
						spentAll += entry.getGp();
					}
					if (inWeek)
					{
						spentWeek += entry.getGp();
					}
					if (inDay)
					{
						spentDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesSpent += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					break;
				case BOUNTY_GAIN:
					if (time > bountyFrom)
					{
						bountyGained += entry.getGp();
					}
					if (inAll)
					{
						gainedAll += entry.getGp();
					}
					if (inWeek)
					{
						gainedWeek += entry.getGp();
					}
					if (inDay)
					{
						gainedDay += entry.getGp();
					}
					if (inAverages)
					{
						averagesGained += entry.getGp();
						if (averagesStart == 0 || time < averagesStart)
						{
							averagesStart = time;
						}
					}
					break;
				case SAVINGS:
					break;
			}
		}

		if (averagesFrom > 0)
		{
			averagesStart = Math.max(averagesStart, averagesFrom);
		}

		if (!hasDeepHistory(now) && ledger.getCloudSavedAt() > 0)
		{
			if (cloudCovers(allFrom))
			{
				spentAll = ledger.getCloudAllSpent();
				gainedAll = ledger.getCloudAllGained();
				for (LedgerEntry entry : ledger.getEntries())
				{
					if (entry.getTime() <= ledger.getCloudSavedAt() || entry.getType() == null)
					{
						continue;
					}
					if (entry.getTime() <= allFrom)
					{
						continue;
					}
					if (isSpend(entry.getType()))
					{
						spentAll += entry.getGp();
					}
					else if (isGain(entry.getType()))
					{
						gainedAll += entry.getGp();
					}
				}
			}
			if (cloudCovers(dayFrom) && !hasEntriesAfter(dayFrom))
			{
				spentDay = ledger.getCloudLastDaySpent();
				gainedDay = ledger.getCloudLastDayGained();
			}
			if (cloudCovers(weekFrom) && !hasEntriesAfter(weekFrom))
			{
				spentWeek = ledger.getCloudLastWeekSpent();
				gainedWeek = ledger.getCloudLastWeekGained();
			}
			if (cloudCovers(alchFrom) && alchSpent == 0 && alchGained == 0)
			{
				alchSpent = ledger.getCloudAlchSpent();
				alchGained = ledger.getCloudAlchGained();
			}
			if (cloudCovers(bountyFrom) && bountySpent == 0 && bountyGained == 0)
			{
				bountySpent = ledger.getCloudBountySpent();
				bountyGained = ledger.getCloudBountyGained();
			}
			if (cloudCovers(averagesFrom) && averagesStart == 0)
			{
				averagesStart = ledger.getCloudAveragesStart();
			}
			if (cloudCovers(averagesFrom) && averagesGained == 0 && averagesSpent == 0 && ledger.getCloudAveragesNet() != 0)
			{
				return new ProfitSummary(
					spentDay, gainedDay, spentWeek, gainedWeek, spentAll, gainedAll,
					ledger.getBestRanarr(), ledger.getBestSnapdragon(), ledger.getBestToadflax(), ledger.getBestSnape(),
					alchSpent, alchGained, bountySpent, bountyGained,
					ledger.getAlchChargesUsed(), ledger.getBountyChargesUsed(),
					ledger.getCloudAveragesNet(), averagesStart);
			}
		}

		return new ProfitSummary(
			spentDay, gainedDay, spentWeek, gainedWeek, spentAll, gainedAll,
			ledger.getBestRanarr(), ledger.getBestSnapdragon(), ledger.getBestToadflax(), ledger.getBestSnape(),
			alchSpent, alchGained, bountySpent, bountyGained,
			ledger.getAlchChargesUsed(), ledger.getBountyChargesUsed(),
			averagesGained - averagesSpent, averagesStart);
	}

	private static boolean isSpend(LedgerType type)
	{
		return type == LedgerType.SPEND || type == LedgerType.ALCH_SPEND || type == LedgerType.BOUNTY_SPEND;
	}

	private static boolean isGain(LedgerType type)
	{
		return type == LedgerType.GAIN || type == LedgerType.ALCH_GAIN || type == LedgerType.BOUNTY_GAIN;
	}

