	private void recordRunHarvest(int itemId, int quantity)
	{
		if (itemId == PrayerPotionItems.GRIMY_RANARR || itemId == PrayerPotionItems.CLEAN_RANARR)
		{
			int count = continueRun(ledger.getRanarrRunStart(), ledger.getRanarrRunCount(), quantity,
				start -> ledger.setRanarrRunStart(start),
				value -> ledger.setRanarrRunCount(value));
			ledger.setBestRanarr(Math.max(ledger.getBestRanarr(), count));
		}
		else if (itemId == PrayerPotionItems.GRIMY_SNAPDRAGON || itemId == PrayerPotionItems.CLEAN_SNAPDRAGON)
		{
			int count = continueRun(ledger.getSnapdragonRunStart(), ledger.getSnapdragonRunCount(), quantity,
				start -> ledger.setSnapdragonRunStart(start),
				value -> ledger.setSnapdragonRunCount(value));
			ledger.setBestSnapdragon(Math.max(ledger.getBestSnapdragon(), count));
		}
		else if (itemId == PrayerPotionItems.GRIMY_TOADFLAX || itemId == PrayerPotionItems.CLEAN_TOADFLAX)
		{
			int count = continueRun(ledger.getToadflaxRunStart(), ledger.getToadflaxRunCount(), quantity,
				start -> ledger.setToadflaxRunStart(start),
				value -> ledger.setToadflaxRunCount(value));
			ledger.setBestToadflax(Math.max(ledger.getBestToadflax(), count));
		}
		else if (itemId == PrayerPotionItems.SNAPE_GRASS)
		{
			int count = continueRun(ledger.getSnapeRunStart(), ledger.getSnapeRunCount(), quantity,
				start -> ledger.setSnapeRunStart(start),
				value -> ledger.setSnapeRunCount(value));
			ledger.setBestSnape(Math.max(ledger.getBestSnape(), count));
		}
	}

	private int continueRun(long runStart, int runCount, int quantity,
		java.util.function.LongConsumer setStart, java.util.function.IntConsumer setCount)
	{
		long now = Instant.now().toEpochMilli();
		if (!inRunWindow(runStart, now))
		{
			setStart.accept(now);
			setCount.accept(quantity);
			return quantity;
		}
		int next = runCount + quantity;
		setCount.accept(next);
		return next;
	}

	private static boolean inRunWindow(long runStart, long at)
	{
		return runStart > 0 && at - runStart < RUN_WINDOW;
	}

	private boolean expireOpenRuns()
	{
		long now = Instant.now().toEpochMilli();
		boolean changed = false;
		if (!inRunWindow(ledger.getRanarrRunStart(), now) && ledger.getRanarrRunStart() > 0)
		{
			ledger.setRanarrRunStart(0);
			ledger.setRanarrRunCount(0);
			changed = true;
		}
		if (!inRunWindow(ledger.getSnapdragonRunStart(), now) && ledger.getSnapdragonRunStart() > 0)
		{
			ledger.setSnapdragonRunStart(0);
			ledger.setSnapdragonRunCount(0);
			changed = true;
		}
		if (!inRunWindow(ledger.getToadflaxRunStart(), now) && ledger.getToadflaxRunStart() > 0)
		{
			ledger.setToadflaxRunStart(0);
			ledger.setToadflaxRunCount(0);
			changed = true;
		}
		if (!inRunWindow(ledger.getSnapeRunStart(), now) && ledger.getSnapeRunStart() > 0)
		{
			ledger.setSnapeRunStart(0);
			ledger.setSnapeRunCount(0);
			changed = true;
		}
		return changed;
	}

	private void reconcileHarvestRuns()
	{
		boolean expired = expireOpenRuns();
		int[] fromHistory = historicalBests();
		long now = Instant.now().toEpochMilli();
		int ranarr = Math.max(ledger.getBestRanarr(), Math.max(fromHistory[0],
			inRunWindow(ledger.getRanarrRunStart(), now) ? ledger.getRanarrRunCount() : 0));
		int snapdragon = Math.max(ledger.getBestSnapdragon(), Math.max(fromHistory[1],
			inRunWindow(ledger.getSnapdragonRunStart(), now) ? ledger.getSnapdragonRunCount() : 0));
		int snape = Math.max(ledger.getBestSnape(), Math.max(fromHistory[2],
			inRunWindow(ledger.getSnapeRunStart(), now) ? ledger.getSnapeRunCount() : 0));
		int toadflax = Math.max(ledger.getBestToadflax(), Math.max(fromHistory[3],
			inRunWindow(ledger.getToadflaxRunStart(), now) ? ledger.getToadflaxRunCount() : 0));
		boolean bestsChanged = ranarr != ledger.getBestRanarr()
			|| snapdragon != ledger.getBestSnapdragon()
			|| toadflax != ledger.getBestToadflax()
			|| snape != ledger.getBestSnape();
		if (bestsChanged)
		{
			ledger.setBestRanarr(ranarr);
			ledger.setBestSnapdragon(snapdragon);
			ledger.setBestToadflax(toadflax);
			ledger.setBestSnape(snape);
		}
		if (expired || bestsChanged)
		{
			save();
		}
	}

	private void seedBestsIfNeeded()
	{
		if (ledger.isBestsInitialized()
			|| ledger.getBestRanarr() > 0 || ledger.getBestSnapdragon() > 0
			|| ledger.getBestToadflax() > 0 || ledger.getBestSnape() > 0)
		{
			ledger.setBestsInitialized(true);
			return;
		}
		int[] seeded = historicalBests();
		if (seeded[0] == 0 && seeded[1] == 0 && seeded[2] == 0 && seeded[3] == 0)
		{
			return;
		}
		ledger.setBestRanarr(seeded[0]);
		ledger.setBestSnapdragon(seeded[1]);
		ledger.setBestSnape(seeded[2]);
		ledger.setBestToadflax(seeded[3]);
		ledger.setBestsInitialized(true);
		save();
	}

	private int[] historicalBests()
	{
		List<LedgerEntry> harvests = new ArrayList<>();
		long resetAt = ledger.getBestResetAt();
		for (LedgerEntry entry : ledger.getEntries())
		{
			if (entry.getType() == LedgerType.HARVEST && entry.getTime() > resetAt)
			{
				harvests.add(entry);
			}
		}
		harvests.sort(Comparator.comparingLong(LedgerEntry::getTime));
		int bestRanarr = 0;
		int bestSnapdragon = 0;
		int bestToadflax = 0;
		int bestSnape = 0;
		int runRanarr = 0;
		int runSnapdragon = 0;
		int runToadflax = 0;
		int runSnape = 0;
		long ranarrLast = -1;
		long snapdragonLast = -1;
		long toadflaxLast = -1;
		long snapeLast = -1;

		for (LedgerEntry entry : harvests)
		{
			int itemId = entry.getItemId();
			long time = entry.getTime();
			if (itemId == PrayerPotionItems.GRIMY_RANARR || itemId == PrayerPotionItems.CLEAN_RANARR)
			{
				if (entry.getQuantity() > MAX_HARVEST_DELTA)
				{
					continue;
				}
				if (!inRunWindow(ranarrLast, time))
				{
					bestRanarr = Math.max(bestRanarr, runRanarr);
					runRanarr = 0;
					ranarrLast = time;
				}
				runRanarr += entry.getQuantity();
			}
			else if (itemId == PrayerPotionItems.GRIMY_SNAPDRAGON || itemId == PrayerPotionItems.CLEAN_SNAPDRAGON)
			{
				if (entry.getQuantity() > MAX_HARVEST_DELTA)
				{
					continue;
				}
				if (!inRunWindow(snapdragonLast, time))
				{
					bestSnapdragon = Math.max(bestSnapdragon, runSnapdragon);
					runSnapdragon = 0;
					snapdragonLast = time;
				}
				runSnapdragon += entry.getQuantity();
			}
			else if (itemId == PrayerPotionItems.GRIMY_TOADFLAX || itemId == PrayerPotionItems.CLEAN_TOADFLAX)
			{
				if (entry.getQuantity() > MAX_HARVEST_DELTA)
				{
					continue;
				}
				if (!inRunWindow(toadflaxLast, time))
				{
					bestToadflax = Math.max(bestToadflax, runToadflax);
					runToadflax = 0;
					toadflaxLast = time;
				}
				runToadflax += entry.getQuantity();
			}
			else if (itemId == PrayerPotionItems.SNAPE_GRASS)
			{
				if (entry.getQuantity() > MAX_HARVEST_DELTA)
				{
					continue;
				}
				if (!inRunWindow(snapeLast, time))
				{
					bestSnape = Math.max(bestSnape, runSnape);
					runSnape = 0;
					snapeLast = time;
				}
				runSnape += entry.getQuantity();
			}
		}

		return new int[] {
			Math.max(bestRanarr, runRanarr),
			Math.max(bestSnapdragon, runSnapdragon),
			Math.max(bestSnape, runSnape),
			Math.max(bestToadflax, runToadflax)
		};
	}

	private void mergeFrom(ProfitLedger other)
	{
		if (other == null || other.getEntries() == null || other.getEntries().isEmpty())
		{
			return;
		}

		Set<String> seen = new HashSet<>();
		for (LedgerEntry entry : ledger.getEntries())
		{
			seen.add(entryKey(entry));
		}
		boolean added = false;
		for (LedgerEntry entry : other.getEntries())
		{
			if (seen.add(entryKey(entry)))
			{
				ledger.getEntries().add(entry);
				added = true;
			}
		}
		if (!added)
		{
			return;
		}

		ledger.getEntries().sort(Comparator.comparingLong(LedgerEntry::getTime));
		if (other.getRanarrRunStart() >= ledger.getRanarrRunStart())
		{
			ledger.setRanarrRunStart(other.getRanarrRunStart());
			ledger.setRanarrRunCount(other.getRanarrRunCount());
		}
		if (other.getSnapdragonRunStart() >= ledger.getSnapdragonRunStart())
		{
			ledger.setSnapdragonRunStart(other.getSnapdragonRunStart());
			ledger.setSnapdragonRunCount(other.getSnapdragonRunCount());
		}
		if (other.getToadflaxRunStart() >= ledger.getToadflaxRunStart())
		{
			ledger.setToadflaxRunStart(other.getToadflaxRunStart());
			ledger.setToadflaxRunCount(other.getToadflaxRunCount());
		}
		if (other.getSnapeRunStart() >= ledger.getSnapeRunStart())
		{
			ledger.setSnapeRunStart(other.getSnapeRunStart());
			ledger.setSnapeRunCount(other.getSnapeRunCount());
		}
		ledger.setBestRanarr(Math.max(ledger.getBestRanarr(), ledger.getRanarrRunCount()));
		ledger.setBestSnapdragon(Math.max(ledger.getBestSnapdragon(), ledger.getSnapdragonRunCount()));
		ledger.setBestToadflax(Math.max(ledger.getBestToadflax(), ledger.getToadflaxRunCount()));
		ledger.setBestSnape(Math.max(ledger.getBestSnape(), ledger.getSnapeRunCount()));
		ledger.setAlchChargesUsed(Math.max(ledger.getAlchChargesUsed(), other.getAlchChargesUsed()));
		ledger.setBountyChargesUsed(Math.max(ledger.getBountyChargesUsed(), other.getBountyChargesUsed()));
	}

	private static String entryKey(LedgerEntry entry)
	{
		return entry.getTime() + "|" + entry.getType() + "|" + entry.getItemId()
			+ "|" + entry.getQuantity() + "|" + entry.getGp();
	}

	private void save()
	{
		dirty = true;
		saveIfDue(true);
	}

	private void saveIfDue(boolean force)
	{
		if (!dirty)
		{
			return;
		}
		long now = Instant.now().toEpochMilli();
		if (!force && now - lastSaveAt < SAVE_INTERVAL_MS)
		{
			return;
		}

		String profile = configManager.getRSProfileKey();
		if (profile == null)
		{
			return;
		}

		Filepath file;
		Filepath tmp;
		try
		{
			file = ledgerFile(profile);
			Filepath dir = file.getParent();
			if (!dir.exists())
			{
				dir.createDirectories();
			}
			tmp = dir.join(file.getFileName() + ".tmp");
			tmp.write(gson.toJson(ledger));
			try
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			}
			catch (AtomicMoveNotSupportedException ex)
			{
				tmp.moveTo(file, StandardCopyOption.REPLACE_EXISTING);
			}
		}
		catch (IOException ex)
		{
			log.warn("Unable to save profit ledger", ex);
			return;
		}

		dirty = false;
		lastSaveAt = now;
		unsetConfigLedger();
		writeCloudSync();
	}

	private void writeCloudSync()
	{
		ProfitSummary summary = summarize();
		long now = Instant.now().toEpochMilli();
		ProfitCloudSync sync = new ProfitCloudSync();
		sync.setSavedAt(now);
		sync.setLastDaySpent(summary.getSpentDay());
		sync.setLastDayGained(summary.getGainedDay());
		sync.setLastWeekSpent(summary.getSpentWeek());
		sync.setLastWeekGained(summary.getGainedWeek());
		sync.setAllTimeSpent(summary.getSpentAll());
		sync.setAllTimeGained(summary.getGainedAll());
		sync.setAveragesNet(summary.getAveragesNet());
		sync.setAveragesStart(summary.getAveragesStart());
		sync.setAlchSpent(summary.getAlchSpent());
		sync.setAlchGained(summary.getAlchGained());
		sync.setAlchChargesUsed(summary.getAlchChargesUsed());
		sync.setBountySpent(summary.getBountySpent());
		sync.setBountyGained(summary.getBountyGained());
		sync.setBountyChargesUsed(summary.getBountyChargesUsed());
		sync.setBestRanarr(ledger.getBestRanarr());
		sync.setBestSnapdragon(ledger.getBestSnapdragon());
		sync.setBestToadflax(ledger.getBestToadflax());
		sync.setBestSnape(ledger.getBestSnape());
		sync.setRanarrRunStart(ledger.getRanarrRunStart());
		sync.setRanarrRunCount(ledger.getRanarrRunCount());
		sync.setSnapdragonRunStart(ledger.getSnapdragonRunStart());
		sync.setSnapdragonRunCount(ledger.getSnapdragonRunCount());
		sync.setToadflaxRunStart(ledger.getToadflaxRunStart());
		sync.setToadflaxRunCount(ledger.getToadflaxRunCount());
		sync.setSnapeRunStart(ledger.getSnapeRunStart());
		sync.setSnapeRunCount(ledger.getSnapeRunCount());
		sync.setDayResetAt(ledger.getDayResetAt());
		sync.setWeekResetAt(ledger.getWeekResetAt());
		sync.setAllResetAt(ledger.getAllResetAt());
		sync.setAveragesResetAt(ledger.getAveragesResetAt());
		sync.setAlchResetAt(ledger.getAlchResetAt());
		sync.setBountyResetAt(ledger.getBountyResetAt());
		sync.setBestResetAt(ledger.getBestResetAt());
		sync.setBestsInitialized(ledger.isBestsInitialized());
		sync.setGeSoldQty(copyGeArray(ledger.getGeSoldQty()));
		sync.setGeSpent(copyGeArray(ledger.getGeSpent()));
		sync.setGeBoughtQty(copyGeArray(ledger.getGeBoughtQty()));
		sync.setGeBoughtGp(copyGeArray(ledger.getGeBoughtGp()));
		sync.setGeItemId(copyGeArray(ledger.getGeItemId()));
		sync.setGeTracked(ledger.isGeTracked());
		sync.setRecent(recentEntries(now));
		applyCloudOverlay(sync);

		String json = gson.toJson(sync);
		if (json.equals(lastCloudJson))
		{
			return;
		}
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, SYNC_KEY, json);
		lastCloudJson = json;
	}

	private List<LedgerEntry> recentEntries(long now)
	{
		long from = now - WEEK;
		List<LedgerEntry> recent = new ArrayList<>();
		for (LedgerEntry entry : ledger.getEntries())
		{
			if (entry.getTime() <= from)
			{
				continue;
			}
			LedgerType type = entry.getType();
			if (type == LedgerType.HARVEST || type == LedgerType.SAVINGS)
			{
				continue;
			}
			recent.add(entry);
		}
		if (recent.size() > MAX_RECENT)
		{
			recent = new ArrayList<>(recent.subList(recent.size() - MAX_RECENT, recent.size()));
		}
		return recent;
	}

	private void mergeCloud(ProfitCloudSync cloud)
	{
		if (cloud == null)
		{
			return;
		}

		ProfitLedger recentLedger = new ProfitLedger();
		if (cloud.getRecent() != null)
		{
			recentLedger.setEntries(new ArrayList<>(cloud.getRecent()));
		}
		mergeFrom(recentLedger);

		long localBestReset = ledger.getBestResetAt();
		long localAlchReset = ledger.getAlchResetAt();
		long localBountyReset = ledger.getBountyResetAt();
		mergeResetLong(cloud.getDayResetAt(), ledger.getDayResetAt(), ledger::setDayResetAt);
		mergeResetLong(cloud.getWeekResetAt(), ledger.getWeekResetAt(), ledger::setWeekResetAt);
		mergeResetLong(cloud.getAllResetAt(), ledger.getAllResetAt(), ledger::setAllResetAt);
		mergeResetLong(cloud.getAveragesResetAt(), ledger.getAveragesResetAt(), ledger::setAveragesResetAt);
		mergeResetLong(cloud.getAlchResetAt(), localAlchReset, ledger::setAlchResetAt);
		mergeResetLong(cloud.getBountyResetAt(), localBountyReset, ledger::setBountyResetAt);
		mergeResetLong(cloud.getBestResetAt(), localBestReset, ledger::setBestResetAt);
		if (cloud.isBestsInitialized())
		{
			ledger.setBestsInitialized(true);
		}

		if (cloud.getBestResetAt() > localBestReset)
		{
			ledger.setRanarrRunStart(cloud.getRanarrRunStart());
			ledger.setRanarrRunCount(cloud.getRanarrRunCount());
			ledger.setSnapdragonRunStart(cloud.getSnapdragonRunStart());
			ledger.setSnapdragonRunCount(cloud.getSnapdragonRunCount());
			ledger.setToadflaxRunStart(cloud.getToadflaxRunStart());
			ledger.setToadflaxRunCount(cloud.getToadflaxRunCount());
			ledger.setSnapeRunStart(cloud.getSnapeRunStart());
			ledger.setSnapeRunCount(cloud.getSnapeRunCount());
			ledger.setBestRanarr(cloud.getBestRanarr());
			ledger.setBestSnapdragon(cloud.getBestSnapdragon());
			ledger.setBestToadflax(cloud.getBestToadflax());
			ledger.setBestSnape(cloud.getBestSnape());
		}
		else if (cloud.getBestResetAt() == localBestReset)
		{
			applyRun(cloud.getRanarrRunStart(), cloud.getRanarrRunCount(),
				ledger.getRanarrRunStart(), ledger.getRanarrRunCount(),
				ledger::setRanarrRunStart, ledger::setRanarrRunCount);
			applyRun(cloud.getSnapdragonRunStart(), cloud.getSnapdragonRunCount(),
				ledger.getSnapdragonRunStart(), ledger.getSnapdragonRunCount(),
				ledger::setSnapdragonRunStart, ledger::setSnapdragonRunCount);
			applyRun(cloud.getToadflaxRunStart(), cloud.getToadflaxRunCount(),
				ledger.getToadflaxRunStart(), ledger.getToadflaxRunCount(),
				ledger::setToadflaxRunStart, ledger::setToadflaxRunCount);
			applyRun(cloud.getSnapeRunStart(), cloud.getSnapeRunCount(),
				ledger.getSnapeRunStart(), ledger.getSnapeRunCount(),
				ledger::setSnapeRunStart, ledger::setSnapeRunCount);
			ledger.setBestRanarr(Math.max(ledger.getBestRanarr(), cloud.getBestRanarr()));
			ledger.setBestSnapdragon(Math.max(ledger.getBestSnapdragon(), cloud.getBestSnapdragon()));
			ledger.setBestToadflax(Math.max(ledger.getBestToadflax(), cloud.getBestToadflax()));
			ledger.setBestSnape(Math.max(ledger.getBestSnape(), cloud.getBestSnape()));
		}
		if (cloud.getAlchResetAt() > localAlchReset)
		{
			ledger.setAlchChargesUsed(cloud.getAlchChargesUsed());
		}
		else if (cloud.getAlchResetAt() == localAlchReset)
		{
			ledger.setAlchChargesUsed(Math.max(ledger.getAlchChargesUsed(), cloud.getAlchChargesUsed()));
		}
		if (cloud.getBountyResetAt() > localBountyReset)
		{
			ledger.setBountyChargesUsed(cloud.getBountyChargesUsed());
		}
		else if (cloud.getBountyResetAt() == localBountyReset)
		{
			ledger.setBountyChargesUsed(Math.max(ledger.getBountyChargesUsed(), cloud.getBountyChargesUsed()));
		}

		if (cloud.isGeTracked() && cloud.getSavedAt() >= ledger.getCloudSavedAt())
		{
			ledger.setGeSoldQty(copyGeArray(cloud.getGeSoldQty()));
			ledger.setGeSpent(copyGeArray(cloud.getGeSpent()));
			ledger.setGeBoughtQty(copyGeArray(cloud.getGeBoughtQty()));
			ledger.setGeBoughtGp(copyGeArray(cloud.getGeBoughtGp()));
			ledger.setGeItemId(copyGeArray(cloud.getGeItemId()));
			ledger.setGeTracked(true);
		}

		applyCloudOverlay(cloud);
	}

	private void applyCloudOverlay(ProfitCloudSync cloud)
	{
		ledger.setCloudSavedAt(cloud.getSavedAt());
		if (cloudCovers(ledger.getDayResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudLastDaySpent(cloud.getLastDaySpent());
			ledger.setCloudLastDayGained(cloud.getLastDayGained());
		}
		else
		{
			ledger.setCloudLastDaySpent(0);
			ledger.setCloudLastDayGained(0);
		}
		if (cloudCovers(ledger.getWeekResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudLastWeekSpent(cloud.getLastWeekSpent());
			ledger.setCloudLastWeekGained(cloud.getLastWeekGained());
		}
		else
		{
			ledger.setCloudLastWeekSpent(0);
			ledger.setCloudLastWeekGained(0);
		}
		if (cloudCovers(ledger.getAllResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudAllSpent(cloud.getAllTimeSpent());
			ledger.setCloudAllGained(cloud.getAllTimeGained());
		}
		else
		{
			ledger.setCloudAllSpent(0);
			ledger.setCloudAllGained(0);
		}
		if (cloudCovers(ledger.getAveragesResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudAveragesNet(cloud.getAveragesNet());
			ledger.setCloudAveragesStart(cloud.getAveragesStart());
		}
		else
		{
			ledger.setCloudAveragesNet(0);
			ledger.setCloudAveragesStart(ledger.getAveragesResetAt());
		}
		if (cloudCovers(ledger.getAlchResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudAlchSpent(cloud.getAlchSpent());
			ledger.setCloudAlchGained(cloud.getAlchGained());
		}
		else
		{
			ledger.setCloudAlchSpent(0);
			ledger.setCloudAlchGained(0);
		}
		if (cloudCovers(ledger.getBountyResetAt(), cloud.getSavedAt()))
		{
			ledger.setCloudBountySpent(cloud.getBountySpent());
			ledger.setCloudBountyGained(cloud.getBountyGained());
		}
		else
		{
			ledger.setCloudBountySpent(0);
			ledger.setCloudBountyGained(0);
		}
	}

	private boolean cloudCovers(long resetAt)
	{
		return cloudCovers(resetAt, ledger.getCloudSavedAt());
	}

	private static boolean cloudCovers(long resetAt, long savedAt)
	{
		return savedAt > 0 && savedAt >= resetAt;
	}

	private static void mergeResetLong(long cloudReset, long localReset, LongConsumer setReset)
	{
		if (cloudReset > localReset)
		{
			setReset.accept(cloudReset);
		}
	}

	private static void applyRun(long cloudStart, int cloudCount, long localStart, int localCount,
		LongConsumer setStart, IntConsumer setCount)
	{
		if (cloudStart > localStart)
		{
			setStart.accept(cloudStart);
			setCount.accept(cloudCount);
		}
		else if (cloudStart == localStart)
		{
			setCount.accept(Math.max(localCount, cloudCount));
		}
	}

	private boolean hasDeepHistory(long now)
	{
		long cutoff = now - WEEK;
		for (LedgerEntry entry : ledger.getEntries())
		{
			if (entry.getTime() < cutoff && entry.getTime() > ledger.getAllResetAt())
			{
				return true;
			}
		}
		return false;
	}

	private boolean hasEntriesAfter(long from)
	{
		for (LedgerEntry entry : ledger.getEntries())
		{
			if (entry.getTime() > from && entry.getType() != LedgerType.HARVEST && entry.getType() != LedgerType.SAVINGS)
			{
				return true;
			}
		}
		return false;
	}

	private void unsetConfigLedger()
	{
		if (configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY) != null)
		{
			configManager.unsetRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		}
	}

	private Filepath ledgerFile(String profile) throws IOException
	{
		String safe = profile.replaceAll("[^A-Za-z0-9._-]", "_");
		return plugin.pluginDataDirectory().join("ledger-" + safe + ".json");
	}

	private ProfitLedger readLedger(Filepath file)
	{
		if (!file.isFile())
		{
			return null;
		}
		try (InputStream in = file.openInputStream())
		{
			return parseLedger(new String(in.readAllBytes(), StandardCharsets.UTF_8));
		}
		catch (IOException ex)
		{
			log.warn("Unable to read profit ledger", ex);
			return null;
		}
	}

	private ProfitCloudSync parseCloud(String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			ProfitCloudSync loaded = gson.fromJson(json, ProfitCloudSync.class);
			if (loaded != null && loaded.getRecent() == null)
			{
				loaded.setRecent(new ArrayList<>());
			}
			return loaded;
		}
		catch (JsonParseException ex)
		{
			log.warn("Unable to parse profit sync", ex);
			return null;
		}
	}

	private ProfitLedger parseLedger(String json)
	{
		if (json == null || json.isEmpty())
		{
			return null;
		}
		try
		{
			ProfitLedger loaded = gson.fromJson(json, ProfitLedger.class);
			if (loaded == null)
			{
				return null;
			}
			if (loaded.getEntries() == null)
			{
				loaded.setEntries(new ArrayList<>());
			}
			return loaded;
		}
		catch (JsonParseException ex)
		{
			log.warn("Unable to parse profit ledger", ex);
			return null;
		}
	}

	private static void row(Writer writer, String section, String metric, long value) throws IOException
	{
		writer.write(csv(section));
		writer.write(',');
		writer.write(csv(metric));
		writer.write(',');
		writer.write(Long.toString(value));
		writer.write('\n');
	}

	private static String csv(String value)
	{
		if (value == null || value.isEmpty())
		{
			return "";
		}
		if (value.indexOf(',') >= 0 || value.indexOf('"') >= 0 || value.indexOf('\n') >= 0)
		{
			return '"' + value.replace("\"", "\"\"") + '"';
		}
		return value;
	}
}

