package com.potionprofitpro.stats;

import lombok.Value;

@Value
public class ProfitSummary
{
	long spentDay;
	long gainedDay;
	long spentWeek;
	long gainedWeek;
	long spentAll;
	long gainedAll;
	int bestRunRanarr;
	int bestRunSnapdragon;
	int bestRunToadflax;
	int bestRunSnape;
	long alchSpent;
	long alchGained;
	long bountySpent;
	long bountyGained;
	int alchChargesUsed;
	int bountyChargesUsed;
	long averagesNet;
	long averagesStart;

	public long alchNet()
	{
		return alchGained - alchSpent;
	}

	public long bountyNet()
	{
		return bountyGained - bountySpent;
	}

	public long netDay()
	{
		return gainedDay - spentDay;
	}

	public long netWeek()
	{
		return gainedWeek - spentWeek;
	}

	public long netAll()
	{
		return gainedAll - spentAll;
	}

	public long dailyAverage()
	{
		return average(1);
	}

	public long weeklyAverage()
	{
		return average(7);
	}

	private long average(int dayBucket)
	{
		if (averagesStart <= 0)
		{
			return 0;
		}
		long days = Math.max(1, (System.currentTimeMillis() - averagesStart) / 86_400_000L);
		if (dayBucket <= 1)
		{
			return averagesNet / days;
		}
		return averagesNet * dayBucket / Math.max(dayBucket, days);
	}
}

