public class StockTracker
{
	private static final String KEY = "supplySnapshot";

	private final ConfigManager configManager;
	private final ItemManager itemManager;
	private final Gson gson;

	private static final long PERSIST_INTERVAL_MS = 2000L;

	private final Map<Integer, Integer> invCounts = new HashMap<>();
	private final Map<Integer, Integer> bankCounts = new HashMap<>();
	private final Map<Integer, Integer> vaultCounts = new HashMap<>();
	private final Map<Integer, Integer> lastCombined = new HashMap<>();
	private final Map<Integer, Integer> lastVault = new HashMap<>();
	private boolean hasBaseline;
