	@Inject
	private StockTracker(ConfigManager configManager, ItemManager itemManager, Gson gson)
	{
		this.configManager = configManager;
		this.itemManager = itemManager;
		this.gson = gson;
	}

	public void load()
	{
		resetSession();
		lastCombined.clear();
		lastVault.clear();
		hasBaseline = false;
		String json = configManager.getRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}
		Stored stored = gson.fromJson(json, Stored.class);
		if (stored == null)
		{
			return;
		}
		copyInto(stored.combined, lastCombined);
		copyInto(stored.vault, lastVault);
		lastCoins = Math.max(0, stored.coins);
		hasBaseline = stored.complete && !lastCombined.isEmpty();
	}

	public void resetSession()
	{
		bankSeen = false;
		vaultSeen = false;
		ignoredUnloadedBank = false;
		invCounts.clear();
		bankCounts.clear();
		vaultCounts.clear();
		skipPotionSales = 0;
		lastPp4Decrease = 0;
	}

	public List<StockDelta> observe(int containerId, ItemContainer container, boolean storageOpen)
	{
		if (containerId == InventoryID.INV)
		{
			Map<Integer, Integer> previousInv = new HashMap<>(invCounts);
			replace(invCounts, counts(container));
			lastPp4Decrease = potion4Decrease(previousInv, invCounts);
			if (storageOpen || !bankSeen || !hasBaseline)
			{
				return Collections.emptyList();
			}
			persist(currentCombined(), vaultSeen ? vaultCounts : lastVault, true);
			return Collections.emptyList();
		}
		if (containerId == InventoryID.BANK)
		{
			replace(bankCounts, counts(container));
			int coins = coins(container);
			if (!bankSeen && !bankLooksLoaded())
			{
				return Collections.emptyList();
			}
			boolean first = !bankSeen;
			bankSeen = true;
			ignoredUnloadedBank = false;
			lastPp4Decrease = 0;
			if (!first)
			{
				lastCoins = coins;
				persist(currentCombined(), vaultSeen ? vaultCounts : lastVault, true);
				return Collections.emptyList();
			}
			int gpDelta = coins - lastCoins;
			lastCoins = coins;
			return reconcile(currentCombined(), true, gpDelta);
		}
		if (containerId == InventoryID.SEED_VAULT)
		{
			replace(vaultCounts, counts(container));
			vaultSeen = true;
			persistVault();
			return Collections.emptyList();
		}
		return Collections.emptyList();
	}

	private void persistVault()
	{
		if (bankSeen)
		{
			persist(currentCombined(), vaultCounts, true);
			return;
		}
		Map<Integer, Integer> now = new HashMap<>(lastCombined);
		for (int itemId : trackedIds())
		{
			int previousVault = lastVault.getOrDefault(itemId, 0);
			int currentVault = vaultCounts.getOrDefault(itemId, 0);
			now.put(itemId, now.getOrDefault(itemId, 0) - previousVault + currentVault);
		}
		persist(now, vaultCounts, hasBaseline);
	}

	public void adjust(int itemId, int delta)
	{
		if (delta == 0 || !hasBaseline)
		{
			return;
		}
		lastCombined.put(itemId, lastCombined.getOrDefault(itemId, 0) + delta);
		persist(lastCombined, vaultSeen ? vaultCounts : lastVault, true);
	}

	public void skipNextPotionSales(int quantity)
	{
		if (quantity > 0)
		{
			skipPotionSales += quantity;
		}
	}

	public void clearPotionSaleSkip()
	{
		skipPotionSales = 0;
	}

	private List<StockDelta> reconcile(Map<Integer, Integer> now, boolean complete, int gpDelta)
	{
		List<StockDelta> deltas = hasBaseline ? diffs(lastCombined, now, gpDelta) : Collections.emptyList();
		persist(now, vaultSeen ? vaultCounts : lastVault, complete || hasBaseline);
		return deltas;
	}

	private Map<Integer, Integer> currentCombined()
	{
		Map<Integer, Integer> now = new HashMap<>();
		addAll(now, invCounts);
		if (bankSeen)
		{
			addAll(now, bankCounts);
		}
		if (vaultSeen)
		{
			addAll(now, vaultCounts);
		}
		else
		{
			addAll(now, lastVault);
		}
		return now;
	}

	private List<StockDelta> diffs(Map<Integer, Integer> previous, Map<Integer, Integer> now, int gpDelta)
	{
		List<StockDelta> deltas = new ArrayList<>();
		addPotionSales(previous, now, deltas, gpDelta);
		return deltas;
	}

	private void addPotionSales(Map<Integer, Integer> previous, Map<Integer, Integer> now, List<StockDelta> deltas,
		int gpDelta)
	{
		List<StockDelta> sales = new ArrayList<>();
		int totalSold = 0;
		for (int itemId : PrayerPotionItems.TRACKED_POTION_4_IDS)
		{
			int sold = previous.getOrDefault(itemId, 0) - now.getOrDefault(itemId, 0);
			if (sold > 0)
			{
				sales.add(new StockDelta(LedgerType.GAIN, itemId, sold));
				totalSold += sold;
			}
		}
		int skip = Math.min(totalSold, skipPotionSales);
		skipPotionSales -= skip;
		if (gpDelta <= 0)
		{
			return;
		}
		for (StockDelta sale : sales)
		{
			int sold = sale.getQuantity();
			int useSkip = Math.min(sold, skip);
			skip -= useSkip;
			sold -= useSkip;
			if (sold > 0)
			{
				deltas.add(new StockDelta(LedgerType.GAIN, sale.getItemId(), sold));
			}
		}
	}

	private boolean bankLooksLoaded()
	{
		if (!hasBaseline)
		{
			return true;
		}
		int bankTracked = sum(bankCounts);
		if (bankTracked > 0)
		{
			return true;
		}
		int previousBank = sum(lastCombined) - sum(invCounts);
		if (vaultSeen)
		{
			previousBank -= sum(vaultCounts);
		}
		else
		{
			previousBank -= sum(lastVault);
		}
		if (previousBank <= 0)
		{
			return true;
		}
		if (ignoredUnloadedBank)
		{
			return true;
		}
		ignoredUnloadedBank = true;
		return false;
	}

	private static int sum(Map<Integer, Integer> counts)
	{
		int total = 0;
		for (int value : counts.values())
		{
			total += Math.max(value, 0);
		}
		return total;
	}

	private static int potion4Decrease(Map<Integer, Integer> previous, Map<Integer, Integer> now)
	{
		int decrease = 0;
		for (int itemId : PrayerPotionItems.TRACKED_POTION_4_IDS)
		{
			decrease += Math.max(0, previous.getOrDefault(itemId, 0) - now.getOrDefault(itemId, 0));
		}
		return decrease;
	}

	public boolean hasBankThisSession()
	{
		return bankSeen;
	}

	public int consumePp4Decrease()
	{
		int decrease = lastPp4Decrease;
		lastPp4Decrease = 0;
		return decrease;
	}

	public int peekPp4Decrease()
	{
		return lastPp4Decrease;
	}

	private void persist(Map<Integer, Integer> combined, Map<Integer, Integer> vault, boolean complete)
	{
		boolean completeNow = complete && !combined.isEmpty();
		if (hasBaseline == completeNow && lastCombined.equals(combined) && lastVault.equals(vault))
		{
			return;
		}
		replace(lastCombined, combined);
		replace(lastVault, vault);
		hasBaseline = completeNow;
		persistDirty = true;
		writePersist(false);
	}

	public void flush()
	{
		writePersist(true);
	}

	public void flushIfDue()
	{
		writePersist(false);
	}

	private void writePersist(boolean force)
	{
		if (!persistDirty)
		{
			return;
		}
		long now = System.currentTimeMillis();
		if (!force && now - lastPersistAt < PERSIST_INTERVAL_MS)
		{
			return;
		}
		Stored stored = new Stored();
		stored.combined = toStored(lastCombined);
		stored.vault = toStored(lastVault);
		stored.complete = hasBaseline;
		stored.coins = lastCoins;
		persistDirty = false;
		lastPersistAt = now;
		configManager.setRSProfileConfiguration(PotionProfitProConfig.GROUP, KEY, gson.toJson(stored));
	}

	private int coins(ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return 0;
		}
		int total = 0;
		for (Item item : container.getItems())
		{
			if (item != null && item.getId() == ItemID.COINS)
			{
				total += Math.max(item.getQuantity(), 0);
			}
		}
		return total;
	}

	private Map<Integer, Integer> counts(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null || container.getItems() == null)
		{
			return counts;
		}
		for (int itemId : trackedIds())
		{
			counts.put(itemId, 0);
		}
		for (Item item : container.getItems())
		{
			if (item == null || item.getId() < 0)
			{
				continue;
			}
			int id = itemManager.canonicalize(item.getId());
			if (!counts.containsKey(id))
			{
				continue;
			}
			counts.put(id, counts.get(id) + Math.max(item.getQuantity(), 0));
		}
		return counts;
	}

