	private static void addAll(Map<Integer, Integer> dest, Map<Integer, Integer> source)
	{
		for (Map.Entry<Integer, Integer> entry : source.entrySet())
		{
			dest.put(entry.getKey(), dest.getOrDefault(entry.getKey(), 0) + entry.getValue());
		}
	}

	private static void replace(Map<Integer, Integer> dest, Map<Integer, Integer> source)
	{
		dest.clear();
		dest.putAll(source);
	}

	private static void copyInto(Map<String, Integer> source, Map<Integer, Integer> dest)
	{
		if (source == null)
		{
			return;
		}
		for (Map.Entry<String, Integer> entry : source.entrySet())
		{
			try
			{
				dest.put(Integer.parseInt(entry.getKey()), entry.getValue() == null ? 0 : entry.getValue());
			}
			catch (NumberFormatException ignored)
			{
			}
		}
	}

	private static Map<String, Integer> toStored(Map<Integer, Integer> source)
	{
		Map<String, Integer> stored = new HashMap<>();
		for (Map.Entry<Integer, Integer> entry : source.entrySet())
		{
			stored.put(Integer.toString(entry.getKey()), entry.getValue());
		}
		return stored;
	}

	static final class Stored
	{
		Map<String, Integer> combined;
		Map<String, Integer> vault;
		boolean complete;
		int coins;
	}

	public static final class StockDelta
	{
		private final LedgerType type;
		private final int itemId;
		private final int quantity;

		private StockDelta(LedgerType type, int itemId, int quantity)
		{
			this.type = type;
			this.itemId = itemId;
			this.quantity = quantity;
		}

		public LedgerType getType()
		{
			return type;
		}

		public int getItemId()
		{
			return itemId;
		}

		public int getQuantity()
		{
			return quantity;
		}
	}
