	private void confirmReset()
	{
		JButton yes = optionButton("Yes", ColorScheme.PROGRESS_ERROR_COLOR);
		JButton no = optionButton("No", ColorScheme.LIGHT_GRAY_COLOR);

		JOptionPane pane = new JOptionPane(
			"Are you sure you want to reset your Potion Profit Pro statistics?\nThis cannot be undone.",
			JOptionPane.WARNING_MESSAGE,
			JOptionPane.YES_NO_OPTION,
			null,
			new Object[] {yes, no},
			no);
		yes.addActionListener(event -> pane.setValue(yes));
		no.addActionListener(event -> pane.setValue(no));

		JDialog dialog = pane.createDialog(this, "Reset statistics");
		dialog.getRootPane().setDefaultButton(no);
		no.requestFocusInWindow();
		dialog.setVisible(true);
		dialog.dispose();

		if (pane.getValue() == yes)
		{
			store.reset();
			update();
		}
	}

	public void setAchievements(List<FarmingAchievement> next)
	{
		List<FarmingAchievement> copy = next == null ? new ArrayList<>() : new ArrayList<>(next);
		if (copy.equals(achievements))
		{
			return;
		}
		achievements = copy;
		SwingUtilities.invokeLater(this::renderAchievements);
	}

	public void setHerbPatches(List<HerbPatchView> next, HerbReadyTime readyTime)
	{
		List<HerbPatchView> copy = next == null ? new ArrayList<>() : new ArrayList<>(next);
		HerbReadyTime ready = readyTime == null ? HerbReadyTime.none() : readyTime;
		if (copy.equals(herbPatches) && ready.equals(herbReadyTime))
		{
			return;
		}
		herbPatches = copy;
		herbReadyTime = ready;
		SwingUtilities.invokeLater(this::renderHerbPatches);
	}

	public void setAllotmentPatches(List<HerbPatchView> next, HerbReadyTime readyTime)
	{
		List<HerbPatchView> copy = next == null ? new ArrayList<>() : new ArrayList<>(next);
		HerbReadyTime ready = readyTime == null ? HerbReadyTime.none() : readyTime;
		if (copy.equals(allotmentPatches) && ready.equals(allotmentReadyTime))
		{
			return;
		}
		allotmentPatches = copy;
		allotmentReadyTime = ready;
		SwingUtilities.invokeLater(() ->
		{
			renderHerbPatches();
			renderAllotmentPatches();
		});
	}

	private void exportCsv()
	{
		List<Filepath> selected = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Export Potion Profit Pro statistics")
			.addExtensionFilter("CSV files", "csv")
			.setDefaultExtension("csv")
			.setFileName("potion-profit-pro-" + LocalDate.now() + ".csv")
			.showDialog(this);
		if (selected == null || selected.isEmpty())
		{
			return;
		}

		try (Writer writer = selected.get(0).openBufferedWriter())
		{
			store.writeCsv(writer);
			writer.write("\nAchievement,Benefit,Complete\n");
			for (FarmingAchievement achievement : achievements)
			{
				writer.write(csv(achievement.getName()));
				writer.write(',');
				writer.write(csv(achievement.getBenefit()));
				writer.write(',');
				writer.write(achievement.isComplete() ? "Yes" : "No");
				writer.write('\n');
			}
		}
		catch (IOException ex)
		{
			JOptionPane.showMessageDialog(this, "Could not export statistics.", "Export CSV", JOptionPane.ERROR_MESSAGE);
		}
	}

	public void update()
	{
		if (updateQueued)
		{
			return;
		}
		updateQueued = true;
		SwingUtilities.invokeLater(() ->
		{
			updateQueued = false;
			ProfitSummary summary = store.summarize();
			CompostType selected = config.compostType();
			if (compostBox.getSelectedItem() != selected)
			{
				compostBox.setSelectedItem(selected);
			}
			syncTrackedPotion();
			syncShowAllotments();
			ProfitPotion potion = config.profitPotion();
			spentDay.setText("Spent: " + gp(summary.getSpentDay()));
			gainedDay.setText("Gained: " + gp(summary.getGainedDay()));
			netDay.setText("Net: " + gp(summary.netDay()));
			spentWeek.setText("Spent: " + gp(summary.getSpentWeek()));
			gainedWeek.setText("Gained: " + gp(summary.getGainedWeek()));
			netWeek.setText("Net: " + gp(summary.netWeek()));
			spentAll.setText("Spent: " + gp(summary.getSpentAll()));
			gainedAll.setText("Gained: " + gp(summary.getGainedAll()));
			netAll.setText("Net: " + gp(summary.netAll()));
			dailyAvg.setText("Daily: " + gp(summary.dailyAverage()));
			weeklyAvg.setText("Weekly: " + gp(summary.weeklyAverage()));
			bestRanarr.setText(herbName(potion) + ": " + herbBestRun(summary, potion));
			bestSnape.setText("Snape grass: " + summary.getBestRunSnape());
			alchSpent.setText("Spent: " + gp(summary.getAlchSpent()));
			alchGained.setText("Gained: " + gp(summary.getAlchGained()));
			alchNet.setText("Net: " + gp(summary.alchNet()));
			alchCharges.setText("Charges used: " + summary.getAlchChargesUsed());
			bountySpent.setText("Spent: " + gp(summary.getBountySpent()));
			bountyGained.setText("Gained: " + gp(summary.getBountyGained()));
			bountyNet.setText("Net: " + gp(summary.bountyNet()));
			bountyCharges.setText("Charges used: " + summary.getBountyChargesUsed());
		});
	}

