	private static void addCropField(JPanel parent, JComponent field)
	{
		field.setAlignmentX(Component.LEFT_ALIGNMENT);
		int height = Math.max(field.getPreferredSize().height, 18);
		if (height > 28)
		{
			height = 24;
		}
		field.setMinimumSize(new Dimension(0, height));
		field.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		parent.add(field);
		parent.add(Box.createVerticalStrut(2));
	}

	private void syncTrackedPotion()
	{
		ProfitPotion selected = config.profitPotion();
		if (potionBox.getSelectedItem() != selected)
		{
			potionBox.setSelectedItem(selected);
		}
		herbToPlant.setText(selected.getHerbName());
