	private void syncShowAllotments()
	{
		boolean compacted = config.plotView() != PlotView.SEPARATED;
		boolean selected = config.showAllotmentPlots();
		PlotTextSize textSize = config.plotTextSize();
		if (plotViewBox.getSelectedItem() != config.plotView())
		{
			plotViewBox.setSelectedItem(config.plotView());
		}
		if (plotTextSizeBox.getSelectedItem() != textSize)
		{
			plotTextSizeBox.setSelectedItem(textSize);
		}
		if (showAllotmentsBox.isSelected() != selected)
		{
			showAllotmentsBox.setSelected(selected);
		}
		showAllotmentsBox.setEnabled(compacted);
		if (allotmentSectionPanel != null)
		{
			allotmentSectionPanel.setVisible(!compacted);
		}
		boolean nest = compacted && selected;
		if (compactedView != compacted || showingAllotments != nest || lastPlotTextSize != textSize)
		{
			compactedView = compacted;
			showingAllotments = nest;
			lastPlotTextSize = textSize;
			renderHerbPatches();
			renderAllotmentPatches();
		}
		revalidate();
		repaint();
	}

	private static String herbName(ProfitPotion potion)
	{
		return potion == null ? ProfitPotion.PRAYER_POTION.getHerbName() : potion.getHerbName();
	}

	private static int herbBestRun(ProfitSummary summary, ProfitPotion potion)
	{
		if (potion == ProfitPotion.PRAYER_POTION)
		{
			return summary.getBestRunRanarr();
		}
		if (potion == ProfitPotion.SARADOMIN_BREW)
		{
			return summary.getBestRunToadflax();
		}
		return summary.getBestRunSnapdragon();
	}

