	private void renderHerbPatches()
	{
		boolean showReady = herbReadyTime.isPresent();
		herbReadyClock.setText(herbReadyTime.getClock());
		herbReadyClock.setToolTipText(showReady ? herbReadyTime.getTooltip() : null);
		herbReadyProgress.setVisible(showReady);
		herbReadyProgress.setValue(herbReadyTime.percentComplete());
		herbReadyProgress.setForeground(showReady && herbReadyTime.getRemainingTicks() <= 0
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.BRAND_ORANGE);
		herbReadyProgress.setToolTipText(showReady ? herbReadyTime.getTooltip() : null);

		showingAllotments = compactedView && config.showAllotmentPlots();
		syncHerbPlotHeaderLayout();
		Map<String, List<HerbPatchView>> allotmentsBySite = showingAllotments
			? allotmentsBySite()
			: Collections.emptyMap();

		herbRows.removeAll();
		if (herbPatches.isEmpty() && allotmentsBySite.isEmpty())
		{
			JLabel empty = statLabel();
			empty.setFont(FontManager.getRunescapeFont());
			empty.setText("Log in to see herb plots");
			herbRows.add(empty);
		}
		else
		{
			List<String> seen = new ArrayList<>();
			for (HerbPatchView view : herbPatches)
			{
				String site = view.getLocation();
				seen.add(site);
				List<HerbPatchView> allotments = allotmentsBySite.getOrDefault(site, Collections.emptyList());
				try
				{
					herbRows.add(farmSiteRow(view, allotments));
				}
				catch (Exception ignored)
				{
					JLabel fallback = statLabel();
					fallback.setText(site);
					herbRows.add(fallback);
				}
			}
			for (Map.Entry<String, List<HerbPatchView>> entry : allotmentsBySite.entrySet())
			{
				if (seen.contains(entry.getKey()))
				{
					continue;
				}
				try
				{
					herbRows.add(farmSiteRow(null, entry.getValue()));
				}
				catch (Exception ignored)
				{
					JLabel fallback = statLabel();
					fallback.setText(entry.getKey());
					herbRows.add(fallback);
				}
			}
		}
		herbRows.revalidate();
		herbRows.repaint();
		revalidate();
		repaint();
	}

	private void renderAllotmentPatches()
	{
		boolean showReady = allotmentReadyTime.isPresent();
		allotmentReadyClock.setText(allotmentReadyTime.getClock());
		allotmentReadyClock.setToolTipText(showReady ? allotmentReadyTime.getTooltip() : null);
		allotmentReadyProgress.setVisible(showReady);
		allotmentReadyProgress.setValue(allotmentReadyTime.percentComplete());
		allotmentReadyProgress.setForeground(showReady && allotmentReadyTime.getRemainingTicks() <= 0
			? ColorScheme.PROGRESS_COMPLETE_COLOR
			: ColorScheme.BRAND_ORANGE);
		allotmentReadyProgress.setToolTipText(showReady ? allotmentReadyTime.getTooltip() : null);
		syncAllotmentPlotHeaderLayout();
		allotmentRows.setLayout(new GridLayout(0, 1, 0, !compactedView && largePlotText() ? 6 : 2));
		allotmentRows.removeAll();
		if (allotmentPatches.isEmpty())
		{
			JLabel empty = statLabel();
			empty.setText("Log in to see allotment plots");
			allotmentRows.add(empty);
		}
		else
		{
			for (HerbPatchView view : allotmentPatches)
			{
				try
				{
					allotmentRows.add(farmSiteRow(view, Collections.emptyList()));
				}
				catch (Exception ignored)
				{
					JLabel fallback = statLabel();
					fallback.setText(view.getLocation());
					allotmentRows.add(fallback);
				}
			}
		}
		allotmentRows.revalidate();
		allotmentRows.repaint();
		if (!compactedView)
		{
			revalidate();
			repaint();
		}
	}

	private Map<String, List<HerbPatchView>> allotmentsBySite()
	{
		Map<String, List<HerbPatchView>> bySite = new LinkedHashMap<>();
		for (HerbPatchView view : allotmentPatches)
		{
			bySite.computeIfAbsent(allotmentSite(view), key -> new ArrayList<>()).add(view);
		}
		return bySite;
	}

