	private JPanel farmSiteRow(HerbPatchView herb, List<HerbPatchView> allotments)
	{
		if (!compactedView)
		{
			return separatedFarmSiteRow(herb, allotments);
		}
		List<HerbPatchView> nested = allotments == null ? Collections.emptyList() : allotments;
		String siteName = herb != null ? herb.getLocation() : allotmentSite(nested.get(0));
		HerbPatchView teleportView = herb != null ? herb : teleportSource(nested);

		Font herbFont = herbPlotFont();
		boolean allotmentRow = herb != null && AllotmentPatch.byLocation(herb.getLocation()) != null;
		Font nameFont = allotmentRow ? FontManager.getRunescapeSmallFont() : herbFont;
		int teleportSize = allotmentRow ? 16 : herbTeleportIconSize();
		int compostSize = allotmentRow || !largePlotText()
			? ALLOTMENT_COMPOST_ICON
			: herbCompostIconSize();
		boolean showCrop = allotmentRow;
		int cropWidth = plotCropWidth();
		boolean spanCrop = spanHerbBarOverCrop();
		int statusCol = cropWidth > 0 ? 3 : 2;
		int rows = Math.max(1, (herb != null ? 1 : 0) + (showingAllotments ? nested.size() : 0));

		JLabel name = new JLabel(siteName);
		name.setFont(nameFont);
		name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JPanel left = new JPanel();
		left.setLayout(new BoxLayout(left, BoxLayout.Y_AXIS));
		left.setOpaque(false);
		name.setAlignmentX(Component.LEFT_ALIGNMENT);
		left.add(name);
		if (teleportView != null && teleportView.isShowTeleport())
		{
			JPanel marker = teleportMarker(teleportView, teleportSize, nameFont);
			marker.setAlignmentX(Component.LEFT_ALIGNMENT);
			left.add(marker);
		}
		pinWidth(left, plotLeftWidth());

		JPanel row = compactPanel();
		row.setLayout(plotGrid());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = 0;
		constraints.gridy = 0;
		constraints.gridheight = rows;
		constraints.weightx = 0;
		constraints.weighty = 0;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.NORTHWEST;
		constraints.insets = new Insets(1, 0, 1, PLOT_NAME_GAP);
		row.add(left, constraints);

		constraints = new GridBagConstraints();
		constraints.gridx = 1;
		constraints.gridy = 0;
		constraints.gridwidth = herb != null && spanCrop ? 2 : 1;
		constraints.weightx = 1;
		constraints.weighty = 0;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.NORTH;
		constraints.insets = new Insets(PLOT_BAR_INSET, PLOT_BAR_INSET, 0,
			spanCrop && herb != null ? 0 : PLOT_BAR_INSET);
		row.add(herbPlotProgress(herb), constraints);

		int statusY = 0;
		if (herb != null)
		{
			row.add(statusCell(statusCompost(herb, nameFont, compostSize, showCrop)),
				statusConstraints(statusCol, statusY));
			statusY++;
		}
		if (showingAllotments)
		{
			for (HerbPatchView allotment : nested)
			{
				JPanel allotmentStatus = statusCompost(allotment, FontManager.getRunescapeSmallFont(),
					ALLOTMENT_COMPOST_ICON, false);
				if (cropWidth > 0)
				{
					JLabel crop = cropIcon(allotment, ALLOTMENT_COMPOST_ICON);
					if (crop != null)
					{
						pinSize(crop, ALLOTMENT_COMPOST_ICON,
							Math.max(allotmentStatus.getPreferredSize().height, ALLOTMENT_COMPOST_ICON));
						constraints = new GridBagConstraints();
						constraints.gridx = 2;
						constraints.gridy = statusY;
						constraints.weightx = 0;
						constraints.weighty = 0;
						constraints.fill = GridBagConstraints.NONE;
						constraints.anchor = GridBagConstraints.EAST;
						constraints.insets = new Insets(0, 0, 0, PLOT_CROP_GAP);
						row.add(crop, constraints);
					}
				}
				row.add(statusCell(allotmentStatus), statusConstraints(statusCol, statusY));
				statusY++;
			}
		}

		String tooltip = herb != null ? herbTooltip(herb) : herbTooltip(nested.get(0));
		row.setToolTipText(tooltip);
		name.setToolTipText(tooltip);
		return row;
	}

	private JPanel herbRow(HerbPatchView view)
	{
		JLabel name = statLabel();
		name.setText(view.getLocation());

		JPanel left = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		left.setOpaque(false);
		left.add(name);
