		{
			left.add(teleportMarker(view));
		}
		left.setMinimumSize(new Dimension(0, 20));
		left.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		left.setAlignmentY(Component.CENTER_ALIGNMENT);

		JLabel state = statLabel();
		state.setText(view.isKnown() ? view.getState() : "Unknown");
		state.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		state.setAlignmentY(Component.CENTER_ALIGNMENT);
		state.setMaximumSize(state.getPreferredSize());

		JLabel cropIcon = cropIcon(view, 12);
		JLabel compostIcon = iconLabel(12);
