	private static HerbPatchView teleportSource(List<HerbPatchView> allotments)
	{
		for (HerbPatchView view : allotments)
		{
			if (view.isShowTeleport())
			{
				return view;
			}
		}
		return allotments.isEmpty() ? null : allotments.get(0);
	}

	private JPanel statusCompost(HerbPatchView view, Font font, int compostSize, boolean showCrop)
	{
		JLabel state = new JLabel(view.isKnown() ? view.getState() : "Unknown");
		state.setFont(font);
		state.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		state.setAlignmentY(Component.CENTER_ALIGNMENT);
		state.setToolTipText(herbTooltip(view));

		JLabel crop = showCrop ? cropIcon(view, compostSize) : null;
		JLabel compostIcon = iconLabel(compostSize);
		compostIcon.setAlignmentY(Component.CENTER_ALIGNMENT);
		compostIcon.setToolTipText(herbTooltip(view));
		if (view.getCompost() != null && !view.getCompost().isEmpty())
		{
			int compostId = compostItemId(view.getCompost());
			if (compostId > 0)
			{
				setItemIcon(compostIcon, compostId, compostSize);
			}
		}

		JPanel row = new JPanel();
		row.setLayout(new BoxLayout(row, BoxLayout.X_AXIS));
		row.setOpaque(false);
		if (crop != null)
		{
