			row.add(Box.createHorizontalStrut(PLOT_CROP_GAP));
		}
		row.add(state);
		row.add(Box.createHorizontalStrut(4));
		row.add(compostIcon);
		row.setToolTipText(herbTooltip(view));
		return row;
