	private JLabel cropIcon(HerbPatchView view, int size)
	{
		if (view == null || view.getCropItemId() <= 0)
		{
			return null;
		}
		JLabel icon = iconLabel(size);
		icon.setAlignmentY(Component.CENTER_ALIGNMENT);
		icon.setToolTipText(herbTooltip(view));
		setItemIcon(icon, view.getCropItemId(), size);
		return icon;
	}

	private JProgressBar herbPlotProgress(HerbPatchView view)
	{
		JProgressBar bar = new JProgressBar(0, 100);
		stylePlotBar(bar);
		int remaining = view == null ? -1 : view.getRemainingTicks();
		if (view == null || !view.isKnown() || remaining < 0)
		{
			bar.setValue(0);
			bar.setForeground(ColorScheme.BRAND_ORANGE);
		}
		else if (remaining == 0)
		{
			bar.setForeground(ColorScheme.PROGRESS_COMPLETE_COLOR);
			int lives = view.getHarvestLives();
			if (lives >= 0)
			{
				bar.setValue(Math.max(0, Math.min(100, lives * 100 / HERB_HARVEST_LIVES)));
			}
			else
			{
				bar.setValue(100);
			}
		}
		else
		{
			int total = Math.max(HERB_GROWTH_TICKS, remaining);
			bar.setValue(Math.max(0, Math.min(100, (total - remaining) * 100 / total)));
			bar.setForeground(ColorScheme.BRAND_ORANGE);
		}
		if (view != null)
		{
			bar.setToolTipText(herbTooltip(view));
		}
		return bar;
	}

