	private void layoutPlotHeader(JPanel heading, JButton toggle, JProgressBar bar, JLabel clock)
	{
		if (!compactedView)
		{
			layoutSeparatedHeader(heading, toggle, bar, clock);
			return;
		}
		int cropWidth = plotCropWidth();
		boolean spanCrop = spanHerbBarOverCrop();
		int statusCol = cropWidth > 0 ? 3 : 2;
		heading.setOpaque(false);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		heading.removeAll();
		heading.setLayout(plotGrid());

		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = 0;
		constraints.gridy = 0;
		constraints.weightx = 0;
		constraints.weighty = 1;
		constraints.fill = GridBagConstraints.NONE;
		constraints.anchor = GridBagConstraints.WEST;
		constraints.insets = new Insets(0, 0, 0, PLOT_NAME_GAP);
		heading.add(toggle, constraints);

		constraints = new GridBagConstraints();
		constraints.gridx = 1;
		constraints.gridy = 0;
		constraints.gridwidth = spanCrop ? 2 : 1;
		constraints.weightx = 1;
		constraints.weighty = 0;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.CENTER;
		constraints.insets = new Insets(PLOT_BAR_INSET, PLOT_BAR_INSET, 0,
			spanCrop ? 0 : PLOT_BAR_INSET);
		heading.add(bar, constraints);

		constraints = new GridBagConstraints();
		constraints.gridx = statusCol;
		constraints.gridy = 0;
		constraints.weightx = 0;
		constraints.weighty = 1;
		constraints.fill = GridBagConstraints.BOTH;
		constraints.anchor = plotStatusAnchor();
		heading.add(statusCell(clock), constraints);
		heading.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			Math.max(toggle.getPreferredSize().height, 18)));
		heading.revalidate();
		heading.repaint();
	}

	private void layoutSeparatedHeader(JPanel heading, JButton toggle, JProgressBar bar, JLabel clock)
	{
		heading.setOpaque(false);
		heading.setAlignmentX(Component.LEFT_ALIGNMENT);
		heading.removeAll();
		heading.setLayout(separatedPlotGrid());

		GridBagConstraints constraints = new GridBagConstraints();
		constraints.gridx = 0;
		constraints.gridy = 0;
		constraints.weightx = 0;
		constraints.weighty = 1;
		constraints.fill = GridBagConstraints.NONE;
		constraints.anchor = GridBagConstraints.WEST;
		constraints.insets = new Insets(0, 0, 1, PLOT_NAME_GAP);
		JPanel toggleCell = new JPanel(new BorderLayout());
		toggleCell.setOpaque(false);
		toggleCell.add(toggle, BorderLayout.WEST);
		pinWidth(toggleCell, separatedLeftWidth());
		heading.add(toggleCell, constraints);

		constraints = new GridBagConstraints();
		constraints.gridx = 1;
		constraints.gridy = 0;
		constraints.weightx = 1;
		constraints.weighty = 1;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.EAST;
		constraints.insets = new Insets(0, 0, 1, 6);
		JPanel clockCell = new JPanel(new BorderLayout());
		clockCell.setOpaque(false);
		clockCell.add(clock, BorderLayout.EAST);
		heading.add(clockCell, constraints);

		constraints = new GridBagConstraints();
		constraints.gridx = 1;
		constraints.gridy = 1;
		constraints.weightx = 1;
		constraints.weighty = 0;
		constraints.fill = GridBagConstraints.HORIZONTAL;
		constraints.anchor = GridBagConstraints.CENTER;
		constraints.insets = new Insets(2, 0, 2, 6);
		heading.add(bar, constraints);

		heading.setMaximumSize(new Dimension(Integer.MAX_VALUE,
			Math.max(toggle.getPreferredSize().height, 18) + 12));
		heading.revalidate();
		heading.repaint();
