	private GridBagLayout separatedPlotGrid()
	{
		GridBagLayout grid = new GridBagLayout();
		grid.columnWidths = new int[]{separatedLeftWidth(), 0};
		grid.columnWeights = new double[]{0, 1};
		return grid;
	}

	private GridBagLayout plotGrid()
	{
		GridBagLayout grid = new GridBagLayout();
		int cropWidth = plotCropWidth();
		if (cropWidth > 0)
		{
			grid.columnWidths = new int[]{plotLeftWidth(), 0, cropWidth, plotRightWidth()};
			grid.columnWeights = new double[]{0, 1, 0, 0};
		}
		else
		{
			grid.columnWidths = new int[]{plotLeftWidth(), 0, plotRightWidth()};
			grid.columnWeights = new double[]{0, 1, 0};
		}
		return grid;
	}

