	private static void pinWidth(JComponent component, int width)
	{
		int prefH = Math.max(component.getPreferredSize().height, 1);
		int minH = Math.max(component.getMinimumSize().height, prefH);
		component.setPreferredSize(new Dimension(width, prefH));
		component.setMinimumSize(new Dimension(width, minH));
		component.setMaximumSize(new Dimension(width, Integer.MAX_VALUE));
	}

	private static void pinSize(JComponent component, int width, int height)
	{
		Dimension size = new Dimension(width, Math.max(height, 1));
		component.setPreferredSize(size);
		component.setMinimumSize(size);
		component.setMaximumSize(size);
	}

	private JPanel teleportMarker(HerbPatchView view)
	{
		return teleportMarker(view, 16, FontManager.getRunescapeSmallFont());
	}

	private JPanel teleportMarker(HerbPatchView view, int iconSize, Font font)
	{
		JPanel marker = new JPanel(new FlowLayout(FlowLayout.LEFT, iconSize > 16 ? 4 : 2, 0));
		marker.setOpaque(false);
		marker.setToolTipText(view.getTeleportTooltip());
		if (!view.isTeleportReady() || view.getTeleportIcons() == null || view.getTeleportIcons().isEmpty())
		{
			JLabel missing = new JLabel("✕");
			missing.setFont(font);
			missing.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			missing.setToolTipText(view.getTeleportTooltip());
			marker.add(missing);
			return marker;
		}
		boolean first = true;
		for (HerbTeleport.Icon icon : view.getTeleportIcons())
		{
			if (icon == null || icon.getId() <= 0)
			{
				continue;
			}
			if (!first)
			{
				JLabel arrow = new JLabel("→");
				arrow.setFont(font);
				arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				arrow.setToolTipText(view.getTeleportTooltip());
				marker.add(arrow);
			}
			first = false;
			JLabel label = iconLabel(iconSize);
			label.setToolTipText(view.getTeleportTooltip());
			if (icon.isSprite())
			{
				setSpriteIcon(label, icon.getId(), iconSize);
			}
			else
			{
				setItemIcon(label, icon.getId(), iconSize);
			}
			marker.add(label);
		}
		if (first)
		{
			JLabel missing = new JLabel("✕");
			missing.setFont(font);
			missing.setForeground(ColorScheme.PROGRESS_ERROR_COLOR);
			missing.setToolTipText(view.getTeleportTooltip());
			marker.add(missing);
		}
		return marker;
	}

	private void setSpriteIcon(JLabel label, int spriteId, int size)
	{
		spriteManager.getSpriteAsync(spriteId, 0, image ->
		{
			if (image == null)
			{
				return;
			}
			BufferedImage icon = ImageUtil.resizeImage(image, size, size);
			SwingUtilities.invokeLater(() -> label.setIcon(new ImageIcon(icon)));
		});
	}

	private void setItemIcon(JLabel label, int itemId, int size)
	{
		AsyncBufferedImage image = itemManager.getImage(itemId);
		if (image == null)
		{
			return;
		}
		image.onLoaded(() -> SwingUtilities.invokeLater(() ->
			label.setIcon(new ImageIcon(ImageUtil.resizeImage(image, size, size)))));
	}

	private static String herbTooltip(HerbPatchView view)
	{
		if (!view.isKnown())
		{
			return view.getLocation() + " — visit this patch to update";
		}
		String compost = view.getCompost() == null || view.getCompost().isEmpty()
			? "Not treated"
			: "Treated with " + view.getCompost();
		String teleport = view.getTeleportTooltip() == null || view.getTeleportTooltip().isEmpty()
			? "No teleport ready"
			: view.getTeleportTooltip();
		return view.getLocation() + " — " + view.getCrop() + " (" + view.getState() + ")\n"
			+ compost + "\n" + teleport;
	}

	private static int compostItemId(String compost)
	{
		if (compost == null)
		{
			return 0;
		}
		String lower = compost.toLowerCase();
		if (lower.contains("ultra"))
		{
			return PrayerPotionItems.ULTRACOMPOST;
		}
		if (lower.contains("super"))
		{
			return PrayerPotionItems.SUPERCOMPOST;
		}
		if (lower.contains("compost"))
		{
			return PrayerPotionItems.COMPOST;
		}
		return 0;
	}

	private static JLabel iconLabel(int size)
	{
		JLabel label = new JLabel();
		Dimension dimension = new Dimension(size, size);
		label.setPreferredSize(dimension);
		label.setMinimumSize(dimension);
		label.setMaximumSize(dimension);
		return label;
	}

	private static void styleHeaderButton(JButton button)
	{
		button.setFocusable(false);
		button.setBorderPainted(false);
		button.setContentAreaFilled(false);
		button.setOpaque(false);
		button.setHorizontalAlignment(JButton.LEFT);
		button.setFont(FontManager.getRunescapeBoldFont());
		button.setForeground(ColorScheme.BRAND_ORANGE);
		button.setMargin(new Insets(0, 0, 0, 0));
		button.setBorder(new EmptyBorder(0, 0, 0, 0));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
	}

	private void renderAchievements()
	{
		achievementRows.removeAll();
		if (achievements.isEmpty())
		{
			JLabel empty = statLabel();
			empty.setText("Log in to see farming unlocks");
			achievementRows.add(empty);
		}
		else
		{
			for (FarmingAchievement achievement : achievements)
			{
				JLabel label = new JLabel("<html><div width='200'>"
					+ (achievement.isComplete() ? "Complete" : "Incomplete")
					+ " — "
					+ achievement.getName()
					+ "<br>"
					+ achievement.getBenefit()
					+ "</div></html>");
				label.setFont(FontManager.getRunescapeSmallFont());
				label.setForeground(achievement.isComplete()
					? ColorScheme.PROGRESS_COMPLETE_COLOR
					: ColorScheme.MEDIUM_GRAY_COLOR);
				achievementRows.add(label);
			}
		}
		achievementRows.revalidate();
		achievementRows.repaint();
	}

	private static JButton optionButton(String text, Color foreground)
	{
		JButton button = new JButton(text);
		button.setForeground(foreground);
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setOpaque(true);
		return button;
	}

	private JPanel pair(JPanel left, JPanel right)
	{
		left.setBorder(new EmptyBorder(0, 0, 0, 0));
		right.setBorder(new EmptyBorder(0, 0, 0, 0));
		left.setAlignmentY(Component.TOP_ALIGNMENT);
		right.setAlignmentY(Component.TOP_ALIGNMENT);

		JPanel row = compactPanel();
		row.setLayout(new GridLayout(1, 2, PAIR_GAP, 0));
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setBorder(new EmptyBorder(0, 0, SECTION_GAP, 0));
		row.add(left);
		row.add(right);
		return row;
	}

	private JPanel section(String title, JLabel... rows)
	{
		return section(title, null, rows);
	}

	private JPanel section(String title, StatSection reset, JLabel... rows)
	{
		JPanel section = compactPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setOpaque(false);
		section.setAlignmentX(Component.LEFT_ALIGNMENT);
		section.setBorder(new EmptyBorder(0, 0, SECTION_GAP, 0));

		JLabel heading = header(title);
		heading.setAlignmentY(Component.CENTER_ALIGNMENT);

		JPanel headingRow = new JPanel();
		headingRow.setLayout(new BoxLayout(headingRow, BoxLayout.X_AXIS));
		headingRow.setOpaque(false);
		headingRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		headingRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		headingRow.add(heading);
		if (reset != null)
		{
			headingRow.add(Box.createHorizontalStrut(4));
			headingRow.add(sectionResetButton(reset));
		}
		section.add(headingRow);
		section.add(Box.createVerticalStrut(HEADER_GAP));

		JPanel values = compactPanel();
		values.setLayout(new GridLayout(0, 1, 0, 0));
		values.setOpaque(false);
		values.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (JLabel row : rows)
		{
			values.add(row);
		}
		section.add(values);
		return section;
	}

	private JButton sectionResetButton(StatSection reset)
	{
		JButton button = new JButton(new ImageIcon(resetIcon()));
		button.setToolTipText("Clear " + reset.getTitle());
		button.setFocusable(false);
		button.setBorderPainted(false);
		button.setContentAreaFilled(false);
		button.setOpaque(false);
		button.setMargin(new Insets(0, 0, 0, 0));
		button.setBorder(new EmptyBorder(0, 0, 0, 0));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setAlignmentY(Component.CENTER_ALIGNMENT);
		button.addActionListener(event ->
		{
			store.resetSection(reset);
			update();
		});
		return button;
	}

	private static BufferedImage resetIcon()
	{
		BufferedImage image = new BufferedImage(12, 12, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.BRAND_ORANGE);
		g.setStroke(new BasicStroke(1.4f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.drawArc(1, 1, 9, 9, 50, 270);
		Path2D arrow = new Path2D.Float();
		arrow.moveTo(9.6, 1.2);
		arrow.lineTo(11.2, 4.4);
		arrow.lineTo(7.4, 4.2);
		arrow.closePath();
		g.fill(arrow);
		g.dispose();
		return image;
	}

	private static JPanel compactPanel()
	{
		return new JPanel()
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
	}

	private static final class ViewportWidthPanel extends JPanel implements Scrollable
	{
		private ViewportWidthPanel()
		{
			super(new BorderLayout());
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return orientation == SwingConstants.VERTICAL ? Math.max(visible.height * 3 / 4, 16) : 16;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	private static JLabel header(String text)
	{
		JLabel label = new JLabel(text);
		label.setFont(FontManager.getRunescapeBoldFont());
		label.setForeground(ColorScheme.BRAND_ORANGE);
		return label;
	}

	private static JLabel statLabel()
	{
		JLabel label = new JLabel();
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return label;
	}

	private static String gp(long value)
	{
		return QuantityFormatter.quantityToStackSize(value) + " gp";
	}

	private static String csv(String value)
	{
		if (value == null || value.isEmpty())
		{
			return "";
		}
		if (value.indexOf(',') >= 0 || value.indexOf('"') >= 0 || value.indexOf('\n') >= 0)
		{
			return '"' + value.replace("\"", "\"\"") + '"';
		}
		return value;
	}
